// War: the orthodox–unorthodox wars, the Cult invasions, family feuds turned wars, imperial campaigns
// and levies, sieges, refugees, supply lines, field hospitals, deserters, spies, war orphans, and what
// is left afterwards. Almost everything here is gated on the fixed history in timeline.js, so it shows up
// in the years those wars actually happen, and several events let you bend that history (avert/happen)
// or leave yourself memories (codex) for the next life.
import { E, O, C, R, P, M, Q, L, LATER } from './kit.js';
import { template } from '../../engine/registry.js';

// ── Memories this file defines (shared objects so each is defined once, identically) ──────────
const GRANARIES = { id: 'secret.wr_cult_granaries', cat: 'secrets', title: 'The army’s stomach', text: 'The Blood Demon’s army is fed from three granaries outside the Jade Gate Pass, filled in the winter of Year 32. Burn them before the spring of Year 34 and the army cannot march east.' };
const KONGTONG_GULLY = { id: 'secret.wr_kongtong_gully', cat: 'secrets', title: 'How Kongtong falls', text: 'Kongtong falls in Year 35 because the Cult climbs the dry gully behind the north gate in a dust storm, while every fist-master is on the western wall.' };
const NAMGUNG_GRANARY = { id: 'secret.wr_namgung_granary', cat: 'secrets', title: 'How the Namgung Estate burns', text: 'The fire that burns the Namgung Estate in Year 38 starts in the east granary. The new cooks hired that summer are Cult agents carrying oil, flint and a Shadow Hall token.' };
const CONTRACT = { id: 'secret.wr_blood_contract', cat: 'secrets', title: 'Who paid for the Namgung patriarch', text: 'The Blood Shadow contract on Namgung Hwi was paid through a Jegal account, but the silver came from the Cult’s Shadow Hall. The Cult wanted the Five Families at each other’s throats before the war.' };
const LEDGER = { id: 'secret.wr_grain_ledger', cat: 'secrets', title: 'The empty granary', text: 'During the Cult War the Alliance granary in Luoyang holds less than half of what its ledger says. Zhongnan carts, under the Alliance Leader’s seal, sell the rest west to the Cult.' };
const HWANGBO = { id: 'secret.wr_hwangbo_hideout', cat: 'secrets', title: 'Where the Alliance Leader hides', text: 'After his letters are exposed in Year 39, Hwangbo Jun flees Luoyang to a hermitage on Mount Qingcheng, where Qingcheng elders he once did favours keep him hidden.' };
const DEPOT_LISTS = { id: 'secret.wr_depot_lists', cat: 'secrets', title: 'The Depot’s war lists', text: 'The Eastern Depot’s clerks write down every living martial artist who fought in the Cult War. Fifteen years later, the Registry Edict of Year 55 begins with those lists.' };
const SONG_TUNNEL = { id: 'secret.wr_song_tunnel', cat: 'secrets', title: 'Under the Bell Tower', text: 'Before the Siege of Mount Song, the Cult’s sappers tunnel under Shaolin’s Bell Tower from the pine slope to the east. In the autumn of Year 35 you can hear them through the foundation stone.' };
const SCOUT_MAPS = { id: 'secret.wr_scout_maps', cat: 'secrets', title: 'The scouts’ maps', text: 'The Cult scouts in the salt mines west of Chang’an carry maps of Mount Hua with one path inked red: the Plum Blossom Path behind the eastern peak.' };
const FORD_SANDBAR = { id: 'secret.wr_ford_sandbar', cat: 'secrets', title: 'The sandbar at the Ford', text: 'A li upstream of the Yellow River Ford, a sandbar runs almost bank to bank under knee-deep water. The Cult never watches it. It is still there a generation later.' };
const TOURNIQUET = { id: 'secret.wr_tourniquet', cat: 'secrets', title: 'Old Bang’s knot', text: 'A one-handed binding above a wound, tied with the teeth. A one-handed veteran taught it to you as a child. It has saved more lives than any sword form you know.' };

// A war orphan: a new child bound for one event.
const ORPHAN = (age, g) => ({ role: 'acquaintance', age, g, aff: 45, res: 10, realm: 0, romance: false });
const VETERAN = ['wr.fought', 'wr.enlisted', 'wr.post_vanguard', 'wr.post_healer', 'wr.post_supply', 'wr.cult_vanguard'];

const events = [
  // ── Childhood: the wars before yours ──────────────────────────────────
  E('wr_ch_column', 'war', { if: { age: [4, 11], year: [5, 30], origin: ['peasant', 'merchant', 'orphan', 'branch', 'official', 'sectborn'] }, art: 'road', text: 'An army column comes through {home}: spears, mules, a general in a closed litter, and boys not much older than you carrying cooking pots. One of the boys winks at you.', choices: [
    C('Run alongside with a water gourd', O('You ran water up and down the column until the gourd was empty. The boy who winked gave you a copper and his name. You forgot the name by evening and kept the copper for years.', { charm: 1, wealth: 1 })),
    C('Ask the boy where they are going', O('"North," he said. "To the wall. Then home." He sounded very sure about the home part.', { insight: 1, sanity: -1 })),
    C('Hide in the rice store until they pass', O('You hid until the drums faded. Your family found you asleep in the rice and did not scold you, which was somehow worse.', { sanity: 1 })),
  ] }),
  E('wr_ch_veteran', 'war', { if: { age: [6, 13], year: [6, 30] }, text: 'Old Bang the night-soil man has one hand, and a story for each missing finger of the other. He fought in the last Cult war, forty years ago. Children are forbidden to listen to him, so all of them do.', choices: [
    C('Ask how he lost the hand', O('"Held it up to stop a sword," he said. "Never do that." Then he showed you how to bind a wound one-handed, with your teeth. You practised on a turnip until it was very safe.', { insight: 1, codex: TOURNIQUET })),
    C('Ask if the Cult really eats children', O('"Only the ones who ask stupid questions," he said. Then, more quietly: "They were boys, like us. Hungrier." You did not know what to do with that.', { sanity: -1, insight: 1 })),
    C('Bring him a steamed bun', O('He ate it in three bites and told you the story of the Battle of Black Water twice, differently each time.', { charm: 1 })),
  ] }),

  // ── Year 13: the grain fleet and the Dongting expedition ─────────────────
  E('wr_fleet_warn', 'war', { w: 3, if: { mem: 'timeline.grain_fleet', timeline: { grain_fleet: 'pending' }, year: [10, 13], region: 'jingchu', age: [9, 40] }, art: 'river', text: 'The imperial grain fleet is gathering at Wuchang: forty barges of rice, one drunk admiral, and a route that runs past the Dongting reeds. You remember how that ends.', choices: [
    R('Tell the admiral’s clerk the Water Fortress is waiting', 'charm', 30, O('The clerk did not believe you, but he was a careful man, and careful men like a second route. The fleet went the long way round, two weeks late and entirely afloat.', { avert: 'grain_fleet', fame: 3, rep: { court: 4 }, gaze: 1 }), O('The clerk had you thrown off the quay for spreading panic. The fleet sailed at dawn.', { rep: { court: -2 } })),
    P('Cut the lead barge loose the night before', 0.45, O('The lead barge drifted into the mud and the fleet spent a month arguing about whose fault it was. By the time it sailed, the Water Fortress had gone home for the season.', { avert: 'grain_fleet', infamy: 2, gaze: 1 }), O('A watchman saw you and blew his whistle. You spent the night in the river, swimming, and the fleet sailed on time.', { health: -6 })),
    C('Let it sail', O('You let it sail. Some rocks in the river are not yours to move.')),
  ] }),
  E('wr_fleet_drowned', 'war', { if: { happened: 'grain_fleet', year: [13, 15], region: 'jingchu', age: [10, 70] }, art: 'river', text: 'For a week after the grain fleet sank, the Great River gave back what it had taken: rice sacks, oars, and boatmen. This morning, one of the boatmen on the mudbank is still breathing.', choices: [
    C('Drag him out and get him warm', O('He lived. He was a rower from Jiangling named Tak, and when he could talk he told you the Fortress had known the fleet’s route a month before it sailed. Someone had sold it.', { sanity: 3, fame: 1, codex: { id: 'secret.wr_fleet_route', cat: 'secrets', title: 'The sold route', text: 'The Water Fortress sank the Year 13 grain fleet because a clerk of the admiralty sold them its route a month early. A second route would have saved it.' } })),
    C('Fetch the magistrate’s men', O('The magistrate’s men took him away for questioning about "the loss of imperial property". You never learned what he told them.', { rep: { court: 2 }, sanity: -2 })),
    C('Salvage the rice sacks first', O('You hauled six sacks of river-soaked rice home before anyone else thought of it. When you went back, the boatman had stopped breathing.', { wealth: 6, sanity: -5 })),
  ] }),
  E('wr_fleet_campaign', 'war', { if: { happened: 'grain_fleet', year: [14, 18], region: 'jingchu', age: [13, 70] }, art: 'lake', title: 'The punitive expedition', text: 'The court remembered its vengeance after all: a punitive fleet at the edge of Lake Dongting, and a commander who needs someone who knows the reeds. He is offering ten taels and a great deal of shouting.', choices: [
    P('Guide them in by the main channel', 0.6, O('The fleet burned three of the Fortress’s outer stockades and called it a victory. The commander paid you, and the Water Fortress learned your face.', { wealth: 10, rep: { court: 6, unorthodox: -6 } }), O('The Fortress was waiting. You swam home through the reeds while the fleet burned behind you, and nobody paid anybody.', { health: -8, rep: { unorthodox: -3 } })),
    C('Lead them into the shallows on purpose', O('Twenty war junks ran aground on a mudflat and sat there for a month, pelted with fish heads. The Fortress sent you a jar of excellent wine with no note.', { rep: { unorthodox: 6, court: -5 }, infamy: 2, item: { rice_wine: 1 } })),
    R('Talk the commander into a parley', 'charm', 35, O('A parley on a sandbar: the commander got an apology and some of the rice back, the Fortress kept its tolls. Both sides called it a victory. Nobody drowned, which nobody thanked you for.', { fame: 3, rep: { court: 3, unorthodox: 3 }, sanity: 3 }), O('The commander called you a pirate’s friend and had you whipped off the jetty.', { health: -5, rep: { court: -2 } })),
  ] }),

  // ── Years 24–30: the Namgung–Jegal feud ─────────────────────────────────
  E('wr_feud_spark', 'war', { w: 2, if: { happened: 'namgung_assassination', year: [24, 26], region: ['jiangnan', 'hebei'], age: [16, 70] }, art: 'estate', title: 'Blood for the patriarch', text: '{@namgung_jin}, heir of a murdered father, stands in the Namgung courtyard and names the Jegal family as the hand behind the knife. Three hundred swords answer him. Nobody asks for proof.', choices: [
    R('Ask for proof, loudly', 'fame', 30, O('The courtyard went quiet. Namgung Jin looked at you as if he would like to kill you, and then said, slowly, that he would wait one season for proof. One season.', { flag: 'wr.feud_proof', rep: { families: 2 }, rel: { '@namgung_jin': { res: 10, aff: -5 } } }), O('Somebody shoved you. Somebody else drew. You left the courtyard with a split lip, and the march went ahead.', { health: -4, flag: 'wr.feud_war' })),
    C('March with the Namgung', O('You marched north with the Namgung swords, under banners still wet from the dyers.', { flag: 'wr.feud_war', rep: { families: 4 }, rel: { '@namgung_jin': { aff: 8 } } })),
    C('Ride ahead and warn the Jegal', O('You rode north ahead of the march. Jegal Mun received your warning with no surprise at all, which was the most frightening thing about it.', { flag: 'wr.feud_war', rep: { families: -2 }, rel: { '@jegal_mun': { res: 10 } }, insight: 1 })),
  ] }),
  E('wr_feud_proof', 'war', { w: 3, if: { flag: 'wr.feud_proof', not: 'wr.feud_ended', loc: 'kaifeng', year: [24, 28], age: [16, 70] }, art: 'night', title: 'The contract', text: 'The Ghost Market sells everything, including the record of a sale. A ledger-keeper of the Blood Shadow Pavilion will show you the Namgung contract for a price, and possibly a knife.', choices: [
    Q('Pay him (60 taels)', { wealth: '>=60' }, O('The contract was paid through a Jegal account. The silver in that account came from the west, from the Cult’s Shadow Hall. Someone wanted the Five Families bleeding before the war.', { wealth: -60, flag: 'wr.feud_ended', codex: CONTRACT, next: 'wr_feud_reveal' })),
    R('Steal the page', 'insight', 40, O('You left with the page in your sleeve and the ledger-keeper none the wiser. A Jegal account, western silver, a Shadow Hall seal.', { flag: 'wr.feud_ended', codex: CONTRACT, next: 'wr_feud_reveal' }), O('The ledger-keeper’s smile widened. You left the Ghost Market at a run, without the page.', { health: -6, flag: 'bloodshadow.wary' })),
    C('Walk away', O('You walked away. The season ran out, and the Namgung marched.', { unflag: 'wr.feud_proof', flag: 'wr.feud_war' })),
  ] }),
  E('wr_feud_reveal', 'war', { on: 'scheduled', art: 'garden', text: 'You lay the contract on a teahouse table between Namgung Jin and Jegal Mun, on neutral ground. Both men read it twice.', choices: [
    C('Let them draw their own conclusions', O('Jegal Mun said, "We were used." Namgung Jin said nothing for a long time, then poured him tea. The feud ended at that table, and the Shadow Hall lost a year of work.', { fame: 8, rep: { families: 10, cult: -5 }, rel: { '@namgung_jin': { res: 20 }, '@jegal_mun': { res: 15 } }, sanity: 4 })),
    C('Point out that the Jegal still took the money', O('Jegal Mun paid a blood-price in silver and land, and bowed lower than anyone had seen a Jegal bow. Namgung Jin took it. Neither family forgot, but neither marched.', { fame: 5, rep: { families: 6 }, rel: { '@namgung_jin': { aff: 10 }, '@jegal_mun': { aff: -10 } } })),
  ] }),
  E('wr_feud_truce', 'war', { if: { flag: 'wr.feud_war', not: 'wr.feud_ended', year: [25, 30], region: ['hebei', 'jiangnan'], age: [16, 70] }, art: 'garden', text: '{@jegal_ha} sends you a baduk board with a game half-played on it. "My father will not ask. Namgung Jin will not listen. You are neither. Carry this to him and tell him it is his move."', choices: [
    R('Carry it, and explain the game', 'insight', 35, O('Namgung Jin stared at the board for an hour. Then he placed a stone that gave up the corner and saved the group. The truce was signed that winter. Jegal Ha sent you the rest of the game, which she had already won.', { flag: 'wr.feud_ended', rep: { families: 8 }, fame: 4, rel: { '@jegal_ha': { aff: 15, res: 15 }, '@namgung_jin': { res: 10 } } }), O('Namgung Jin swept the stones off the board. The feud ran another year and cost both families sons.', { rel: { '@jegal_ha': { aff: 5 } }, sanity: -3 })),
    P('Set it in front of him without a word', 0.45, O('You set the board in front of Namgung Jin and left. A week later there was a truce, and nobody ever explained it to you.', { flag: 'wr.feud_ended', rep: { families: 4 }, rel: { '@jegal_ha': { aff: 8 } } }), O('He used the board for kindling. You never told Jegal Ha.', { rel: { '@jegal_ha': { aff: 3 } } })),
    C('Refuse to be anybody’s stone', O('"Then you will be swept off the board with the rest of us," she said, without heat.', { rel: { '@jegal_ha': { res: 5 } } })),
  ] }),
  L('wr_feud_cost', 'war', { flag: 'wr.feud_war', not: 'wr.feud_ended', year: [28, 33], age: [16, 80] }, 'The Namgung–Jegal feud has burned through four years and two hundred lives. In the west, they say, someone laughs every time a son of the Five Families is buried.', { sanity: -2 }),

  // ── Year 26: the Dang civil war ──────────────────────────────────────────
  E('wr_dang_side', 'war', { if: { happened: 'dang_civil_war', year: [26, 27], region: 'shu', age: [16, 70] }, art: 'estate', title: 'Walls within walls', text: 'The Dang manor has become two armies separated by a garden full of poison. Dang Gwang’s men pay well and ask few questions. The loyalists pay in antidotes and ask a great many.', choices: [
    C('Take Dang Gwang’s silver', O('You guarded a gate for Dang Gwang for a season. The pay was excellent. The man you replaced had died of something in the gate’s paint.', { wealth: 25, infamy: 3, rep: { families: -3 } })),
    R('Run antidotes through the poison garden for the loyalists', 'insight', 30, O('You learned to walk the garden by smell. Twelve trips, twelve satchels, and the loyalists held the inner court. A Dang elder pressed a recipe on you, disgusted at how little you knew.', { rep: { families: 6 }, fame: 3, recipe: 'heart_calming' }), O('A leaf brushed your wrist on the third trip. You spent a month in a loyalist sickroom learning what the Dang mean by "mild".', { health: -15, rep: { families: 3 } })),
    C('Stay out of Dang business', O('You stayed out of it. In Shu, that is the most common advice and the least followed.')),
  ] }),
  E('wr_dang_min_hospital', 'war', { if: { happened: 'dang_civil_war', year: [26, 29], region: 'shu', alive: 'dang_min', age: [14, 70] }, art: 'estate', text: '{@dang_min} has turned a storehouse into a sickroom and is treating wounded from both sides of his family’s war, which both sides consider treason. He needs hands that do not shake.', choices: [
    C('Lend him yours', O('You boiled cloth, held men down, and learned that half the Dang poisons have cures nobody bothered to write down. Dang Min wrote them down. He thanked you by blushing.', { rel: { '@dang_min': { aff: 15, res: 10 } }, insight: 2, recipe: 'healing_salve' })),
    R('Persuade both sides to leave the storehouse alone', 'charm', 35, O('You walked into each camp and explained that the storehouse held their own brothers. Neither side burned it. Dang Min looked at you as if you had worked a miracle; it was mostly shame.', { rel: { '@dang_min': { aff: 10, res: 15 } }, rep: { families: 5 }, fame: 2 }), O('Dang Gwang’s men listened politely, then took the storehouse’s medicine "for safekeeping".', { rel: { '@dang_min': { aff: 5 } } })),
    C('Tell him he will get himself killed', O('"Probably," he said, and went back to stitching.', { meet: '@dang_min' })),
  ] }),

  // ── Years 29–33: the red banners gather ──────────────────────────────────
  E('wr_cult_muster', 'war', { if: { sect: 'cult', happened: 'blood_demon_throne', year: [30, 33], age: [14, 80] }, art: 'demonic', title: 'The muster', text: 'In the Hall of Ten Thousand Demons, {@blood_demon} tells the believers that the east has grown fat on their patience. Ten thousand fists strike ten thousand chests. Beside you, {@mokcheol} strikes his half a beat late.', choices: [
    C('Strike your chest with the rest', O('The sound was like a mountain breathing. By evening your name was on the vanguard roster.', { rep: { cult: 6 }, merit: 8, flag: 'wr.cult_vanguard', sanity: -2 })),
    C('Ask Mok Cheol what he is thinking', O('"That my mother’s village is on the road east," he said, "and the vanguard does not take the long way round." He said nothing else that day, and did not need to.', { rel: { '@mokcheol': { aff: 12 } }, insight: 1 })),
    R('Volunteer for the quartermaster’s hall instead', 'insight', 30, O('Grain counts, mule counts, arrow counts. Somewhere in the numbers you learned exactly what the army could not march without.', { merit: 6, codex: GRANARIES }), O('The quartermaster did not want a clerk. He wanted a spear, and gave you one.', { flag: 'wr.cult_vanguard' })),
  ] }),
  E('wr_scout_signals', 'war', { if: { flag: 'w.war_coming', year: [31, 33], region: 'guanzhong', age: [14, 80] }, art: 'forest', text: 'Strips of red cloth on dead trees, one every li, running east from the hills toward Mount Hua. Nobody else on the road seems to have noticed. Somebody hung them very carefully.', choices: [
    C('Report them to the Alliance post at Chang’an', O('A bored officer wrote it down. You watched him use the paper to wrap his lunch.', { rep: { orthodox: 1 } })),
    C('Cut them down', O('You cut down every strip you could find. Three nights later they were back, one every li, as if they had grown there.', { insight: 1 })),
    M('Follow them to the old salt mines', 'secret.cult_signals', O('Exactly where you remembered: the salt mines west of Chang’an, a dozen men in brown over red. You counted their horses, copied their maps, and left before the dogs woke.', { fame: 2, codex: SCOUT_MAPS })),
    Q('Take them to Mount Hua yourself', { sect: 'mounthua' }, O('The Sect Leader turned a strip of red cloth over in his fingers for a long time. "Double the night watch," he said, and nobody argued.', { merit: 10, flag: 'wr.hua_warned' })),
  ] }),
  E('wr_hoard', 'war', { if: { mem: 'timeline.cult_war', year: [29, 33], wealth: '>=40', age: [16, 80], not: 'wr.stockpile' }, art: 'market', text: 'Salt is cheap. Rice is cheap. Wound salve is cheap. You remember a spring when all three cost more than swords.', choices: [
    C('Buy a warehouse’s worth (40 taels)', O('You filled a rented warehouse with salt, rice and salve, and told the landlord it was for a wedding. A very long wedding.', { wealth: -40, flag: 'wr.stockpile' })),
    C('Buy medicine only (15 taels)', O('Bandage cloth, salve, and a sack of dried herbs, stacked under your bed.', { wealth: -15, item: { healing_salve: 2 }, flag: 'wr.medicine_store' })),
    C('Leave the market to the market', O('You let it be. Getting rich on a war you remember felt like robbing the dead in advance.', { sanity: 2 })),
  ] }),
  E('wr_stockpile_choice', 'war', { if: { flag: 'wr.stockpile', happened: 'cult_war', year: [35, 40], age: [16, 90] }, art: 'market', text: 'Rice in the Central Plains now costs what silver used to. Your warehouse is full. An Alliance quartermaster, a widow from the refugee camp and a grain broker from Kaifeng have all found out.', choices: [
    C('Sell to the broker', O('The broker paid in silver bars and did not say where the rice would go. You know where it went. You have a great deal of silver.', { wealth: 180, infamy: 6, sanity: -6, unflag: 'wr.stockpile' })),
    C('Sell to the Alliance at what you paid', O('The quartermaster stared at the price, then at you, and signed before you could change your mind. The army ate that winter.', { wealth: 40, fame: 6, rep: { orthodox: 8 }, unflag: 'wr.stockpile' })),
    C('Give it to the camp', O('The widow ran the distribution herself, with a ladle and a stare nobody argued with. For one winter the camp had no hunger deaths.', { fame: 10, sanity: 10, unflag: 'wr.stockpile' })),
  ] }),
  E('wr_prevent_war', 'war', { w: 4, danger: true, if: { mem: 'secret.wr_cult_granaries', flag: 'w.war_coming', timeline: { cult_war: 'pending' }, year: [32, 33], region: 'west', age: [16, 90] }, art: 'desert', title: 'The granaries at Jade Gate', text: 'Three granaries outside the Jade Gate Pass, filled to the roof last winter, guarded by bored men who think the war is somewhere else. You remember what is in them: the whole of next year’s war.', choices: [
    R('Fire them at night', 'insight', 40, O('Three fires, one after another, and a wind out of the desert to carry them. In spring the Blood Demon had nothing to feed an army on the road east. It never marched, not on Mount Hua and not on the Central Plains.', { avert: ['cult_war', 'blood_night'], unflag: 'w.war_coming', achieve: 'no_war', gaze: 2, infamy: 3, rep: { cult: -15 } }), O('A guard dog found you before the second fire caught. You ran into the desert with a spear graze, one granary burning behind you. It was not enough.', { health: -14, rep: { cult: -5 } })),
    C('Fight your way in', O('The guards were not as bored as they looked.', { combat: { foe: { name: 'the granary guard captain', kind: 'cultist', rel: 0 }, context: 'war', lethal: 0.35, win: { text: 'You cut down the captain and fired all three granaries while his men ran for water. In spring the Blood Demon’s army had nothing to eat. It never marched.', avert: ['cult_war', 'blood_night'], unflag: 'w.war_coming', achieve: 'no_war', gaze: 2, fame: 5, rep: { cult: -15 } }, lose: { text: 'They threw you out into the desert to die. You did not, quite.', health: -10 } } })),
    Q('Bribe the granary clerk to "lose" the grain (150 taels)', { wealth: '>=150' }, O('The clerk sold the grain to Silk Road caravans and burned the ledgers. The army that gathered in spring had nothing in its wagons, and went home.', { wealth: -150, avert: ['cult_war', 'blood_night'], unflag: 'w.war_coming', achieve: 'no_war', gaze: 2 })),
    C('Leave it', O('You left it. Perhaps the wheel needs this war. Perhaps you just could not do it.')),
  ] }),
  E('wr_alliance_muster', 'war', { w: 2, if: { flag: 'w.war_coming', year: [33, 34], faction: ['orthodox', 'families'], age: [15, 70] }, art: 'temple', title: 'The muster', text: 'The Murim Alliance has sent every sect the same letter: so many swords, so many healers, so many carts, by spring. The elders of {sect} read it aloud in the yard, then look at the disciples one by one.', choices: [
    C('Put your name down for the vanguard', O('Your name went first on the list, in a hand steadier than you felt.', { flag: 'wr.post_vanguard', merit: 10, fame: 2 })),
    C('Volunteer for the healers’ tents', O('The elder nodded as if he had expected it, and gave you a bundle of bandage cloth to carry until spring.', { flag: 'wr.post_healer', merit: 6, item: { healing_salve: 1 } })),
    C('Volunteer for the supply carts', O('"Somebody has to count the rice," the elder said. "Count it honestly." He seemed to think that was the hard part. He was right.', { flag: 'wr.post_supply', merit: 6 })),
    R('Argue the sect should not go at all', 'charm', 45, O('You asked who the war was for, and why the Alliance Leader would not say. Nobody agreed aloud. Three elders came to your door that night to agree quietly.', { merit: -5, insight: 2 }), O('You were sent to the Hall of Repentance to think about loyalty until spring, then sent to the vanguard anyway.', { merit: -10, flag: 'wr.post_vanguard' })),
  ] }),

  // ── Years 34–41: the Great Cult War ──────────────────────────────────────
  E('wr_war_news', 'war', { if: { happened: 'cult_war', year: [34, 35], age: [10, 90] }, art: 'city', text: 'The criers in {loc} say the Cult has crossed the western passes and the Alliance is at war. A woman at the well starts to laugh and cannot stop. Her husband is somewhere west.', choices: [
    C('Go and find a recruiting table', O('There were three, and a queue. You joined it behind a blacksmith and a boy who had lied about his age.', { flag: 'wr.enlisted', fame: 1 })),
    C('Pack for the south', O('You packed what you could carry and turned south, toward Shu and the rivers and anywhere the banners were not red.', { sanity: 2 })),
    C('Sit with the laughing woman until she stops', O('It took most of the afternoon. She told you her husband’s name twice, so that somebody else would know it.', { sanity: -2, charm: 1 })),
  ] }),
  E('wr_vanguard_night', 'war', { once: false, cd: 3, danger: true, if: { any: ['wr.post_vanguard', 'wr.enlisted', 'wr.cult_vanguard'], flag: 'w.war', age: [15, 70] }, art: 'night', title: 'Night watch', text: 'Night watch on the forward line. Someone in the dark ahead is moving very quietly, and stopping whenever you stop.', choices: [
    C('Go out and meet them', O('You went over the ditch, blade first.', { combat: { foe: { name: 'an enemy scout', kind: 'soldier', rel: -0.5 }, context: 'war', lethal: 0.25, win: { text: 'The scout carried a map of your own line, very accurate. Your captain went pale and moved the whole company before dawn.', fame: 3, merit: 6, flag: 'wr.fought' }, lose: { text: 'The scout left you in the ditch and was gone before the alarm.', health: -5, flag: 'wr.fought' } } })),
    C('Raise the alarm', O('The whole line woke cursing and lit torches. Nothing was there, or whatever had been there was gone. Nobody thanked you, but nobody slept on watch for a week.', { merit: 2 })),
    R('Keep still and listen', 'insight', 30, O('It was a boy from the other side, lost and crying very quietly. You watched him find his own way back. You told nobody.', { sanity: 2, insight: 1 }), O('You listened until dawn and heard only your own heart. In the morning there were footprints a yard from your post.', { sanity: -4 })),
  ] }),
  E('wr_healer_post', 'war', { once: false, cd: 3, if: { flag: ['wr.post_healer', 'w.war'], age: [15, 70] }, art: 'battlefield', title: 'The healers’ tents', text: 'The healers’ tents smell of vinegar and smoke. A boy with a crushed leg is asking for his mother, and the surgeon is asking for someone to hold the saw.', choices: [
    R('Hold the saw', 'sanity', 45, O('You held it steady. The boy lived. You did not sleep for three nights, and then you slept for two days.', { sanity: -6, fame: 3, insight: 2 }), O('Your hands shook. The surgeon took the saw back and did it himself, faster than you could have. The boy lived anyway.', { sanity: -10 })),
    C('Be his mother for an hour', O('You held his hand and told him about home as if it were his. He called you Mother twice. You let him.', { sanity: -3, charm: 2 })),
    M('Tie Old Bang’s knot above the wound', 'secret.wr_tourniquet', O('Teeth, cloth, one hand: the bleeding slowed to nothing. The surgeon looked up. "Who taught you that?" A dead man, you nearly said. A one-handed one.', { fame: 3, insight: 2, recipe: 'healing_salve' })),
  ] }),
  E('wr_quartermaster', 'war', { if: { flag: ['wr.post_supply', 'w.war'], age: [15, 70] }, art: 'scroll', title: 'Counting the rice', text: 'The Alliance granary at Luoyang should hold forty thousand sacks. The ledger says forty thousand. You have counted twice, and it holds nineteen.', choices: [
    C('Report it to your sect elders', O('Your elders reported it upward. Upward, it stopped. A month later the ledger had been rewritten and you had been moved to counting arrows.', { codex: LEDGER, merit: 3 })),
    R('Trace the missing rice', 'insight', 40, O('Ox-carts at night, Zhongnan seals on the passes, a buyer in the west. The rice went to the Cult, and the Alliance Leader’s own men drove the carts.', { codex: LEDGER, insight: 2, flag: 'wr.ledger_traced' }), O('A Zhongnan disciple asked you, very politely, why you were counting things that did not concern you.', { sanity: -3 })),
    C('Write the ledger the way it is written', O('You wrote forty thousand. It was easier, and it was what everyone wanted, and you hated it.', { sanity: -5, merit: 2 })),
  ] }),
  E('wr_ledger_expose', 'war', { w: 2, if: { flag: 'wr.ledger_traced', timeline: { alliance_betrayal: 'pending' }, year: [34, 38], loc: 'luoyang', age: [16, 90] }, art: 'city', text: 'You have the cart-masters’ names, the Zhongnan seals and the empty sacks. The Alliance hall sits in session tomorrow, with {@alliance_leader} in the chair.', choices: [
    R('Stand up in the hall and read it out', 'fame', 40, O('The hall went from uproar to silence in one sentence. By evening the Alliance had a new leader, and the old one had an escort of Shaolin monks to a cell. The war went differently after that.', { avert: 'alliance_betrayal', flag: 'alliance.cleansed', fame: 15, rep: { orthodox: 12 }, gaze: 1 }), O('Hwangbo Jun thanked you gravely for your diligence and promised an inquiry. The inquiry found that you had miscounted.', { rep: { orthodox: -4 } })),
    C('Give it all to the Beggars’ Sect', O('Hong Chil read it in an alley, chewing a chicken bone. "Good," he said. "Now he owes us, and he does not know it." Nothing happened in public. The rice stopped going west.', { rep: { orthodox: 5 }, rel: { '@beggar_chief': { res: 15 } } })),
  ] }),
  E('wr_kongtong_warn', 'war', { w: 3, if: { happened: 'cult_war', timeline: { kongtong_falls: 'pending' }, year: [34, 35], region: 'guanzhong', age: [16, 90] }, art: 'mountain', text: 'Kongtong’s masters are proud of their walls, which face west toward the passes. They do not think much about the dry gully that runs up behind the north gate.', choices: [
    M('Tell them the Cult comes up the gully in a dust storm', 'secret.wr_kongtong_gully', O('They did not ask how you knew. They filled the gully with thorn and oil and waited. When the dust storm came, so did the Cult, and so did the fire. Kongtong did not fall.', { avert: 'kongtong_falls', fame: 8, rep: { orthodox: 10 }, gaze: 1 })),
    M('Warn them Kongtong falls in a single night', 'timeline.kongtong_falls', O('A single night, you said. The elders sent their novices and scriptures south to Mount Zhongnan the next morning, just in case. When the night came, there were fewer people to lose.', { fame: 4, rep: { orthodox: 5 }, sanity: 3 })),
    R('Walk the gully and point at it', 'insight', 45, O('The elder who walked it with you went quiet halfway up. That night the north gate had a hundred fists behind it. The Cult tried it, found it, and went home bleeding.', { avert: 'kongtong_falls', fame: 6, rep: { orthodox: 8 }, gaze: 1 }), O('"Goats," said the elder. "Only goats come up here."')),
    C('Leave them to their walls', O('You left them to their walls.')),
  ] }),
  E('wr_kongtong_teacher', 'war', { if: { happened: 'kongtong_falls', year: [35, 50], region: 'guanzhong', realm: '>=1', noManual: 'kong_seven_injuries', age: [14, 80] }, art: 'inn', text: 'A Kongtong master, one of the few who walked out of the burning mountain, splits firewood behind a Chang’an inn with fists that crack the logs before they touch them. Every blow costs him; you can see it in his face.', choices: [
    R('Ask him to teach you', 'body', 35, O('"It wounds you as it wounds them," he said. "That is the price, and the point." He taught you through the winter, coughed blood every evening, and did not stop.', { manual: 'kong_seven_injuries', health: -8, body: 2 }), O('He looked at your hands and said no.', { insight: 1 })),
    C('Split wood with him', O('You split wood side by side all afternoon. He did not talk about the mountain, and you did not ask.', { body: 1, sanity: 2 })),
  ] }),
  E('wr_song_sappers', 'war', { w: 2, if: { happened: 'cult_war', timeline: { siege_song: 'pending' }, year: [35, 36], region: 'central', age: [16, 90] }, art: 'temple', title: 'Under the Bell Tower', text: 'Shaolin prepares for a siege the way it does everything: slowly, thoroughly, with chanting. Nobody has listened to the ground. You put your ear to the Bell Tower’s foundation stone and hear, very faintly, digging.', choices: [
    C('Tell the warrior monks', O('The monks dug a counter-tunnel and met the Cult’s sappers halfway, in the dark. Nobody who went down talked about it afterwards. The Bell Tower is still standing.', { fame: 5, rep: { orthodox: 8 }, codex: SONG_TUNNEL })),
    C('Help carry the scriptures out of the Pavilion', O('A thousand years of sutras in oxcarts, down the back of the mountain by night. You carried the Arhat Fist volumes yourself, wrapped in your coat.', { flag: 'wr.scriptures_saved', rep: { orthodox: 5 }, body: 1 })),
    C('Leave before the siege lines close', O('You left the mountain at dawn. From the road you could hear the bells for a day and a half.', { sanity: -3 })),
  ] }),
  E('wr_scriptures_return', 'war', { if: { flag: 'wr.scriptures_saved', year: [37, 70], loc: 'songshan', age: [16, 90] }, art: 'library', text: 'The scriptures you carried down the mountain have come home. A monk who keeps the Pavilion’s list finds your name on it, beside "Arhat Fist, three volumes, wrapped in a coat".', choices: [
    C('Ask to read what you carried', O('The monks argued for a day and then decided that anyone who carried a book through a war had already started reading it.', { manual: 'shao_arhat', rep: { orthodox: 5 } })),
    C('Ask for nothing', O('The old monk bowed to you, which Shaolin monks do not do lightly. You have been welcome on Mount Song ever since.', { rep: { orthodox: 10 }, fame: 3, sanity: 3 })),
  ] }),
  E('wr_cheongun_vigil', 'war', { if: { happened: 'wudang_holds', alive: 'cheongun', year: [37, 50], loc: 'wudang', age: [14, 90], not: 'wr.cheongun_woke' }, art: 'temple', text: '{@cheongun} has slept since he fought the Blood Demon to a standstill. Wudang disciples sit with him in shifts. He smiles slightly in his sleep, as if someone told him a joke years ago and he has only just understood it.', choices: [
    C('Take a shift', O('You sat with him through the night. Near dawn his breathing changed, and for a moment your own qi moved with it, slow and enormous, like a tide.', { qi: 15, insight: 2, sanity: 3 })),
    Q('Brew the Snow Lotus for him', { item: 'snow_lotus' }, O('The disciples argued for an hour. Then he drank it, opened his eyes, and asked who had been eating his peaches.', { take: { snow_lotus: 1 }, flag: 'wr.cheongun_woke', npcFlag: { '@cheongun': 'woken' }, rel: { '@cheongun': { aff: 30, res: 25 } }, fame: 10, rep: { orthodox: 12 } })),
    C('Leave a peach on the sill', O('You left a peach. When you came back the next day it was gone, and the disciples swore nobody had touched it.', { sanity: 2 })),
  ] }),
  E('wr_namgung_evac', 'war', { w: 3, if: { happened: 'cult_war', timeline: { namgung_burns: 'pending' }, year: [37, 38], region: 'jiangnan', age: [16, 90] }, art: 'estate', text: 'The Namgung Estate prepares for the Cult the Namgung way: polishing swords, refusing reinforcements, and hiring extra cooks for the victory feast.', choices: [
    M('Tell them the fire starts in the east granary, with the new cooks', 'secret.wr_namgung_granary', O('The new cooks were taken into the courtyard and their sleeves searched: oil, flint, a Shadow Hall token. When the Cult came, the gates held and the granary did not burn. The Namgung Estate stands.', { avert: 'namgung_burns', fame: 10, rep: { families: 15 }, gaze: 1 })),
    R('Persuade them to send the children to Hangzhou', 'charm', 40, O('The patriarch called it cowardice, his wife called it sense, and the children left at night in rice boats. Forty of them.', { fame: 5, rep: { families: 6 }, sanity: 4 }), O('"A Namgung does not run," they told you. You noticed that the children were not asked.', { sanity: -3 })),
    M('Warn them the Estate will burn', 'timeline.namgung_burns', O('They listened as far as was polite. A few servants left. Most of the family did not.', { rep: { families: 2 } })),
    C('Leave Jiangnan', O('You left Jiangnan before the leaves turned.')),
  ] }),
  E('wr_namgung_ashes', 'war', { if: { happened: 'namgung_burns', year: [38, 42], region: 'jiangnan', age: [14, 90] }, art: 'fire', title: 'The ashes', text: 'The Namgung Estate is black beams and white ash. In the ash by the gate, where {@namgung_jin} died, lies his sword, snapped a hand’s width from the hilt.', choices: [
    C('Carry the sword to the surviving branch family', O('A branch cousin of nineteen took it from you and did not cry until you had gone. She leads the family now, what is left of it.', { rep: { families: 10 }, fame: 3, sanity: -2 })),
    R('Find out how the fire began', 'insight', 30, O('The burn marks led back to the east granary. The cooks hired that summer were never found among the dead, or among the living.', { codex: NAMGUNG_GRANARY, insight: 1 }), O('Ash is ash. It would not tell you anything.')),
    C('Bury what you can', O('You dug graves until your hands blistered. Some of the stones you could not put names on.', { sanity: -4, fame: 1 })),
  ] }),
  E('wr_hwangbo_flight', 'war', { danger: true, if: { happened: 'alliance_betrayal', year: [39, 40], loc: 'luoyang', alive: 'alliance_leader', age: [16, 90] }, art: 'night', title: 'The Alliance Leader runs', text: 'A closed carriage clatters through Luoyang’s west gate after curfew. At its window, for a moment, a face everyone knows: {@alliance_leader}, Leader of the Murim Alliance, leaving it.', choices: [
    Q('Stop the carriage', { realm: '>=4' }, O('You landed on the carriage roof. He stepped down to meet you, smiling his public smile.', { combat: { foe: '@alliance_leader', context: 'war', lethal: 0.3, important: true, win: { text: 'He yielded on his knees in the road and asked, very reasonably, what you wanted. You wanted a trial. He got one.', fame: 15, rep: { orthodox: 12 }, flag: 'wr.hwangbo_caught' }, lose: { text: 'He left you in the road with a broken arm and an apology that sounded sincere.', health: -10 } } })),
    R('Follow the carriage', 'body', 35, O('Three weeks behind it, south and west, to a hermitage on Mount Qingcheng with new locks on its old doors.', { codex: HWANGBO }), O('You lost the carriage at a crossroads in the rain.', { health: -3 })),
    C('Let him go, and wake the Beggars', O('By morning the Beggars’ Sect knew which road he had taken, and by evening the whole Gangho did. He would never sit at a murim table again.', { rep: { orthodox: 4 }, fame: 2 })),
  ] }),
  E('wr_hwangbo_found', 'war', { if: { mem: 'secret.wr_hwangbo_hideout', happened: 'alliance_betrayal', year: [40, 70], loc: 'qingcheng', alive: 'alliance_leader', not: 'wr.hwangbo_caught', age: [18, 90] }, art: 'mountain', text: 'The hermitage on Mount Qingcheng has new locks on old doors. Inside, an old man who used to lead the Murim Alliance is pruning a bonsai, and expecting you.', choices: [
    C('Bring him to Luoyang for trial', O('He came without a fight. "Someone had to talk to the Cult," he said on the road. "I only charged them for it." The tribunal took a month. He was sealed in a cell under the Alliance hall.', { flag: 'wr.hwangbo_caught', fame: 12, rep: { orthodox: 10 } })),
    C('Take what he offers to forget the road', O('Three hundred taels in old Alliance silver, and letters of introduction to every Qingcheng elder. You felt the money in your sleeve all the way down the mountain.', { wealth: 300, infamy: 8, rep: { orthodox: -5 }, sanity: -6 })),
    C('Ask him why', O('He talked until the tea was cold: about sects that would rather die than share a granary, and a Cult that only wanted the passes. Some of it was even true. You left him to his bonsai.', { insight: 3, sanity: -2 })),
  ] }),
  E('wr_court_petition', 'war', { if: { faction: 'court', rank: '>=2', happened: 'cult_war', timeline: { depot_army: 'pending' }, year: [37, 39], age: [20, 100] }, art: 'palace', text: 'The Director is content to let the Cult and the murim bleed each other a while longer. You could put a memorial before the throne asking for the army now. The Director would not thank you for it.', choices: [
    R('Petition the throne', 'fame', 45, O('The young Emperor read your memorial himself and asked why the army was waiting. Nobody had a good answer. The imperial army marched two years early, and there were fewer dead to count.', { happen: 'depot_army', merit: 15, rep: { court: -4, orthodox: 10 }, fame: 8, gaze: 1 }), O('The memorial reached the Director first. He returned it with a single brushstroke through it and moved you to the archives.', { merit: -15 })),
    C('Wait, as the Director wishes', O('You waited. The Director noted your patience with approval. Fewer of the dead were his.', { merit: 5, sanity: -3 })),
  ] }),
  E('wr_depot_counting', 'war', { if: { happened: 'depot_army', year: [40, 42], region: 'central', realm: '>=1', age: [16, 90] }, art: 'battlefield', text: 'The Eastern Depot’s clerks walk between the wounded with brushes and ledgers, writing down names, sects and realms. They are very polite about it. They do not write down the dead, only the living.', choices: [
    C('Give your real name', O('The clerk wrote it in a beautiful hand and thanked you for your service to the throne.', { flag: 'wr.depot_listed', rep: { court: 3 } })),
    R('Give a false one', 'insight', 25, O('You gave the name of a pig farmer from your childhood. Somewhere in the capital, that pig farmer is now a registered swordsman.', { insight: 1, codex: DEPOT_LISTS }), O('The clerk looked at your hands, your sword and your face, and wrote down your real name anyway. "Thank you," he said.', { flag: 'wr.depot_listed' })),
    C('Ask the clerk what the lists are for', O('"Pensions," he said, and smiled, and went on writing.', { codex: DEPOT_LISTS, sanity: -2 })),
  ] }),
  E('wr_ford_eve', 'war', { if: { happened: 'depot_army', year: 41, season: 0, region: 'central', age: [16, 90] }, art: 'night', title: 'The night before the Ford', bind: { x: { role: 'acquaintance', ageRel: [-6, 4], minAge: 16, realm: [1, 4], aff: 55, res: 40 } }, text: 'Tomorrow the Alliance crosses the Yellow River at the Ford. Tonight {x}, who has shared your fire since winter, has a jar of terrible wine and wants to talk about anything but tomorrow.', choices: [
    C('Swear brotherhood under the river stars', O('You cut your palms, mixed the blood, and laughed at how much it stung. "If one of us dies tomorrow," {x} said, "the other has to finish this wine." It was a very large jar.', { role: { x: 'sworn' }, achieve: 'sworn', rel: { x: { aff: 20 } }, sanity: 4, next: { id: 'wr_ford_morning', in: 1 } })),
    C('Write letters for each other', O('{x} wrote yours and you wrote {x.his}. You both promised not to read them, swapped them back unread at dawn, and tucked them inside your armour.', { rel: { x: { aff: 10 } }, sanity: 2, next: { id: 'wr_ford_morning', in: 1 } })),
    C('Sleep instead', O('You slept badly, and {x} did not sleep at all. In the morning {x.he} gave you the rest of the wine.', { health: 3 })),
  ] }),
  E('wr_ford_morning', 'war', { on: 'scheduled', if: { npc: { x: true } }, art: 'battlefield', title: 'After the Ford', text: 'The Yellow River Ford is won and the Blood Demon is dead, and the bank is so crowded with the living and the dead that you cannot tell them apart from a distance. You have not seen {x} since the second charge.', choices: [
    P('Search the field', 0.55, O('You found {x} under a broken cart, filthy, furious and alive. "You read my letter," {x.he} said. "I can tell." You had not. You did not argue.', { rel: { x: { aff: 15 } }, sanity: 6 }), O('You found {x} at dusk, by the water, with your letter still inside {x.his} armour. You read {x.his} letter, finally. It was mostly about the wine.', { kill: 'x', sanity: -12 })),
    P('Wait at the fire where you said you would', 0.5, O('{x} came limping in at midnight on a spear-shaft crutch, and sat down beside you as if {x.he} had only been gone a moment.', { rel: { x: { aff: 10 } }, sanity: 4 }), O('{x} never came to the fire. The lists said only "missing", and then, a month later, not even that.', { kill: 'x', sanity: -10 })),
  ] }),
  E('wr_burned_fields', 'war', { if: { flag: 'w.war', region: ['guanzhong', 'central'], faction: ['orthodox', 'families'], age: [16, 80] }, art: 'fire', text: 'The Alliance has ordered the wheat burned along the western road so the Cult will find nothing to eat. The farmers whose wheat it is have been told this is an honour. An elder hands you a torch.', choices: [
    C('Burn it', O('It went up in an afternoon. The farmers watched from the ditch. One of them thanked you, which was the worst part.', { merit: 6, rep: { orthodox: 3 }, sanity: -8 })),
    R('Burn the barns and spare the fields', 'charm', 35, O('You argued that green wheat feeds nobody this season and everybody the next. The elder let you burn the barns instead. The farmers kept their fields, and the Cult found nothing it could eat this year.', { merit: 4, sanity: 3, fame: 2 }), O('The elder took the torch back, did it himself, and noted your name.', { merit: -6 })),
    C('Help the farmers carry out what they can first', O('You carried seed grain to a cave until dark. The fields burned at dawn without you.', { merit: -2, sanity: 2, fame: 1 })),
  ] }),
  E('wr_prisoners', 'war', { if: { flag: 'w.war', faction: ['orthodox', 'families'], age: [16, 80] }, art: 'prison', text: 'Twelve Cult prisoners in a sheepfold: farm boys from the western valleys, most of them, with red armbands and no shoes. The elder in charge says the Alliance has no rice for prisoners, and asks who will do it.', choices: [
    C('Refuse, in front of everyone', O('Others refused after you. The elder could not execute twelve prisoners and twenty disciples, so in the end he executed none. They were sent east to dig ditches. Most of them lived.', { merit: -8, fame: 4, sanity: 5, rep: { cult: 2 } })),
    C('Open the fold at night', O('By morning the fold was empty and the elder was looking at everyone. He never proved anything. He never forgot.', { merit: -4, sanity: 6, flag: 'wr.freed_prisoners', rep: { cult: 4 } })),
    C('Do as you are told', O('You did as you were told. Afterwards the elder praised your steadiness. You were sick behind the sheepfold.', { merit: 8, sanity: -15, infamy: 3 })),
  ] }),
  E('wr_prisoner_repays', 'war', { if: { flag: 'wr.freed_prisoners', year: [38, 90], region: ['west', 'guanzhong', 'central'], age: [18, 100] }, art: 'market', text: 'A man with a western accent stops you in the market, bows very low, and will not straighten up. "The sheepfold," he says. "You opened it. I have a farm now, and three daughters, and none of them would exist."', choices: [
    C('Help him up', O('He pressed a bag of dried apricots on you, and a name: a Cult elder who owes him a life. "Use it," he said. "He hates owing."', { sanity: 8, rep: { cult: 4 } })),
    C('Tell him you do not remember', O('"I remember enough for both of us," he said, and left you the apricots anyway.', { sanity: 5 })),
  ] }),
  E('wr_cult_village', 'war', { if: { flag: 'w.war', sect: 'cult', age: [16, 80] }, art: 'fire', text: 'The order is to burn the village of Three Elms so the Alliance cannot quarter there. The villagers are mostly old, and have already packed. {@mokcheol}, beside you, has not lit his torch.', choices: [
    C('Burn it on schedule', O('Three Elms burned on schedule. The commander was pleased. The old people walked east with their bundles and did not look back.', { merit: 8, rep: { cult: 4 }, sanity: -8 })),
    C('Give the villagers until dusk', O('You gave them until dusk and stood between them and the commander’s runners. The village burned empty. Mok Cheol said nothing, and walked beside you for the rest of the campaign.', { merit: -2, sanity: 2, rel: { '@mokcheol': { aff: 12, res: 10 } } })),
    R('Report the village already burned', 'charm', 35, O('A smudge of smoke on the horizon and your word for it. The commander did not ride over to check. Three Elms is still there; years later you passed it, and someone was drying peppers on a roof.', { merit: 2, sanity: 6 }), O('The commander rode over to check.', { merit: -10, health: -6, flag: 'cult.suspect' })),
  ] }),
  E('wr_greenforest_war', 'war', { if: { flag: 'w.war', faction: 'unorthodox', age: [16, 80] }, art: 'forest', text: 'In the great hall of the Taihang, {@mountain_tiger} has two letters on the table. The Alliance offers pardons to any bandit who fights the Cult. The Cult offers silver to any bandit who raids the Alliance’s carts. He wants your opinion before he decides, which is new.', choices: [
    C('Take the pardons', O('The Green Forest fought under its own banners on the Alliance’s flank, and better than anyone expected. The pardons, when they came, were on very cheap paper.', { rep: { unorthodox: 5, orthodox: 6 }, fame: 3 })),
    C('Take the silver', O('Alliance carts burned along the Taihang for a year. The Green Forest grew fat, and hated, and the Alliance would remember.', { rep: { unorthodox: 4, orthodox: -10, cult: 6 }, wealth: 30, infamy: 5 })),
    R('Take neither, and sell rice to both', 'insight', 35, O('"A bandit who picks a side in a war is a soldier," you said. "A bandit who sells rice to both is a merchant." Ma Hu laughed until the beams shook, and did it.', { rep: { unorthodox: 8 }, wealth: 20, rel: { '@mountain_tiger': { res: 15 } } }), O('Both sides found out. Both sides were annoyed. The Taihang had a very bad winter.', { rep: { unorthodox: -4 } })),
  ] }),

  // ── Trades at war ────────────────────────────────────────────────────────
  E('wr_merchant_prices', 'war', { if: { flag: 'w.war', career: 'merchant', age: [16, 80] }, art: 'market', text: 'Your rice has tripled in value since the war began. The army’s buyer offers the old price "for the realm". A Kaifeng speculator offers four times that, in cash.', choices: [
    C('Sell to the army at the old price', O('The buyer shook your hand twice. The army ate. Your accounts did not.', { wealth: 10, rep: { orthodox: 5, court: 3 }, fame: 2 })),
    C('Sell to the speculator', O('Four times the price, in silver. The rice reached the army anyway, at eight times the price, paid for with taxes from people like you.', { wealth: 60, infamy: 3, careerUp: 3, sanity: -3 })),
    R('Organise the street to sell at double', 'charm', 30, O('You got every merchant on the street to sell to the army at double the old price, in writing, under the Golden Abacus seal. Nobody got rich and nobody starved.', { wealth: 25, rep: { merchants: 6, orthodox: 3 }, careerUp: 4 }), O('The other merchants sold to the speculator behind your back.', { wealth: 10 })),
  ] }),
  E('wr_smith_orders', 'war', { if: { flag: 'w.war', career: 'smith', age: [14, 80] }, art: 'forge', text: 'Two orders on your anvil this morning: four hundred spearheads for the Alliance, at a price that barely covers the charcoal, and a quiet man paying triple for a hundred sabers, delivery west, no questions.', choices: [
    C('Forge the spearheads', O('You worked the forge day and night until your forearms were cooked red. Four hundred spearheads. Sometimes you wondered which of them came back.', { wealth: 8, body: 2, careerUp: 5, rep: { orthodox: 4 } })),
    C('Forge the sabers', O('A hundred good sabers, delivered west. The silver was very good. You did not ask, and the quiet man did not tell.', { wealth: 45, infamy: 4, rep: { cult: 4 }, careerUp: 4 })),
    R('Forge them badly, and tell the Alliance where they are going', 'insight', 35, O('The sabers looked perfect and snapped at the first parry. The Alliance met the delivery on the road. Nobody told the quiet man who had tipped them off; nobody had to.', { wealth: 20, rep: { orthodox: 6, cult: -6 }, careerUp: 3 }), O('The quiet man tested the first saber on your anvil. It snapped. He looked at you for a long time.', { wealth: -10, health: -8, rep: { cult: -4 } })),
  ] }),
  E('wr_scholar_memorial', 'war', { if: { flag: 'w.war', career: 'scholar', age: [16, 80] }, art: 'scroll', text: 'The Ministry wants a memorial to the throne on "the murim disturbance in the west". The Eastern Depot wants to read it first. Your brush is wet.', choices: [
    C('Write that the murim is bleeding for the empire', O('A true memorial and an unwise one. It reached the throne. So did a Depot note beside it, with your name underlined.', { fame: 3, rep: { orthodox: 4, court: -4 }, insight: 1 })),
    C('Write what the Depot wants', O('Unruly sects, private armies, a dangerous lack of registration. It was praised in council. Fifteen years later you recognised its phrases in an edict.', { careerUp: 6, rep: { court: 6 }, sanity: -5 })),
    R('Write something both can read as agreement', 'insight', 40, O('Four pages that said nothing, beautifully. The Depot approved it and the Alliance quoted it. You were promoted for your balance.', { careerUp: 8, rep: { court: 3 } }), O('Both sides read it as an insult.', { rep: { court: -3 } })),
  ] }),
  E('wr_farmer_requisition', 'war', { if: { flag: 'w.war', career: 'farmer', age: [14, 80] }, text: 'Alliance soldiers at your gate with a cart and a writ. They want your grain, all of it, including next spring’s seed. The writ has a very fine seal.', choices: [
    C('Give it', O('They took everything and gave you a receipt. By the second month of spring you would have eaten the receipt, if it had been edible.', { wealth: -6, sanity: -4, rep: { orthodox: 2 } })),
    R('Hide the seed grain in the pig shed', 'insight', 20, O('They took the grain and missed the seed. The pig was furious. Next spring, you planted.', { wealth: -2, insight: 1 }), O('The pig gave you away. They took the seed too, and the pig.', { wealth: -9 })),
    Q('Bribe the sergeant (8 taels)', { wealth: '>=8' }, O('The sergeant discovered that your farm was further down the road than he had thought, and kept going.', { wealth: -8 })),
  ] }),
  E('wr_camp_fever', 'war', { if: { flag: 'w.war', career: 'physician', age: [16, 80] }, art: 'plague', text: 'Camp fever in the Alliance lines: more men dying in the latrine trenches than on the field. The captains want it kept quiet. The physicians want it kept anywhere else.', choices: [
    R('Move the latrines downstream and boil the water', 'insight', 30, O('Simple, unglamorous, and nobody believed it until the dying stopped. A general who never learned your name wrote your method into his orders.', { careerUp: 6, fame: 4, rep: { orthodox: 4 } }), O('You caught it yourself and spent a season sweating in a tent full of men doing the same.', { health: -15, careerUp: 2 })),
    C('Treat the sick and say nothing', O('You treated whom you could, and buried the rest without the captains knowing, which was what they wanted.', { careerUp: 3, sanity: -5 })),
    C('Leave before it reaches the healers', O('You left at night with your needles. Nobody chased you; there were not enough healthy men.', { infamy: 2, sanity: -3 })),
  ] }),

  // ── Home, roads and taverns in wartime ───────────────────────────────────
  E('wr_letter_home', 'war', { once: false, cd: 4, if: { flag: 'w.war', has: 'parent', age: [16, 60] }, fmt: 'letter', from: 'x', bind: { x: 'parent' }, art: 'letter', text: '"We hear terrible things from the west. The neighbours’ son came home without his arm and will not speak. I am not sleeping. Come home, or at least write." The letter is three months old.', choices: [
    C('Go home for a season', O('You went home. {x} held you at the gate for a very long time and then scolded you about your hair.', { rel: { x: { aff: 12 } }, sanity: 6 })),
    C('Write back that you are well', O('You wrote that you were well, the food was good and the war was mostly marching. Two of those were lies.', { rel: { x: { aff: 5 } }, sanity: 1 })),
    C('Do not answer', O('You meant to answer. There was always tomorrow’s march.', { rel: { x: { aff: -8 } }, sanity: -2 })),
  ] }),
  E('wr_tavern_war', 'war', { on: 'tavern', once: false, cd: 2, if: { flag: 'w.war', age: [12, 90] }, art: 'inn', text: 'Every tavern in the empire is a war council now. Tonight’s generals: a carter, two drunk disciples, and a woman selling roast chestnuts, who is the only one making sense.', choices: [
    C('Buy the chestnut seller a cup', O('"Kongtong, Song, Wudang," she said. "They go mountain by mountain. Count the mountains between the west and Luoyang and you know when to leave." You counted.', { insight: 1, wealth: -1 })),
    C('Argue with the disciples', O('You won the argument and lost the room, and the chestnut seller charged you double.', { charm: 1, wealth: -2 })),
    C('Drink quietly', O('You drank quietly and listened to the carter explain why the war was the fault of the price of salt. He was not entirely wrong.', { sanity: 1 })),
  ] }),
  E('wr_road_checkpoint', 'war', { on: 'road', once: false, cd: 3, if: { flag: 'w.war', age: [14, 90] }, art: 'road', text: 'An Alliance checkpoint on the bridge: two disciples, a table, and a list of faces drawn by someone who has never seen a face. They want your sect, your business, and your reason for not being at the front.', choices: [
    Q('Show your sect token', { faction: ['orthodox', 'families'] }, O('They bowed, waved you through and asked if you had any news. You did not have any good news.', { rep: { orthodox: 1 } })),
    R('Explain yourself', 'charm', 22, O('A sick aunt, a debt, a wedding. They let you through, mostly to stop you talking.', { charm: 1 }), O('They held you a day "for questions" and fed you nothing.', { health: -3 })),
    C('Wade the river downstream', O('Cold, but nobody wrote your face down.', { health: -2, body: 1 })),
  ] }),
  E('wr_road_column', 'war', { on: 'road', once: false, cd: 4, if: { age: [12, 90], or: [{ flag: 'w.war' }, { flag: 'w.postwar', year: [41, 44] }] }, art: 'road', text: 'The road ahead is a river of people going the other way: carts, wheelbarrows, a bed carried by four sons with their grandmother still in it. Nobody is talking.', choices: [
    C('Turn and walk with them a while', O('You carried a child on your shoulders for twenty li. Her mother thanked you in a dialect you could not follow, and the child stole your hairpin.', { sanity: 3, charm: 1, fame: 1 })),
    C('Push on against the stream', O('You pushed on, shoulder first, apologising. It was like walking up a waterfall.', { body: 1 })),
    Q('Hand out what food you carry (3 taels)', { wealth: '>=3' }, O('It went in a moment. The boy who got the last bun broke it in half and gave half to the grandmother in the bed.', { wealth: -3, sanity: 4 })),
  ] }),
  E('wr_arrive_curfew', 'war', { on: 'arrive', once: false, cd: 3, if: { flag: 'w.war', locType: 'city', age: [12, 90] }, art: 'city', text: '{loc} is under curfew: gates shut at dusk, lanterns out at the second watch, and a militia of shopkeepers with borrowed spears who are very excited about it.', choices: [
    C('Find an inn before dark', O('You found the last room in the city, above a stable, at three times the price.', { wealth: -3 })),
    C('Volunteer for the night watch', O('You walked the walls with a cobbler and a fishmonger. The fishmonger knew every star and the cobbler knew every rumour. You learned a great deal.', { insight: 1, rep: { orthodox: 1 } })),
    C('Sleep under the city wall', O('You slept under the wall with the refugees who had not got in either. Someone shared a blanket.', { health: -2, sanity: 2 })),
  ] }),
  E('wr_war_nightmare', 'war', { once: false, cd: 4, if: { or: [{ flag: 'w.war' }, { flag: 'w.postwar' }], any: VETERAN, stat: { sanity: '<=45' }, age: [16, 100] }, art: 'night', text: 'You dream of the line again: the drums, the smoke, the face of somebody you did not save. You wake with your hand on your sword and your heart going like a war drum.', choices: [
    C('Sit up until dawn', O('You sat up until dawn. The heart-demon sat with you, polite and patient, like a guest who is not leaving.', { sanity: -3 })),
    Q('Burn calming incense', { item: 'heart_calming' }, O('The smoke smelled of temple mornings. You slept, finally, without dreams.', { take: { heart_calming: 1 }, sanity: 12 })),
    C('Find someone else who was there', O('You found another veteran awake at the well. Neither of you said much. It helped more than anything anyone else had ever said.', { sanity: 6 })),
  ] }),
  E('wr_orphan_grown', 'war', { on: 'scheduled', if: { npc: { x: true } }, art: 'blossom', title: 'The child you took in', text: '{x}, whom you took in as a war orphan, is grown now. {x.He} has your habit of sitting with {x.his} back to the wall, and someone else’s eyes.', choices: [
    C('Tell {x.him} what you remember of {x.his} parents', O('You told {x.him} what little you knew: a village, a burned roof, a name scratched on a door. {x.He} wrote it all down, went to find the village, and came back.', { rel: { x: { aff: 15 } }, sanity: 5 })),
    C('Tell {x.him} you are proud', O('{x.He} pretended not to care, then went outside and chopped a great deal of firewood very fast.', { rel: { x: { aff: 10, res: 10 } }, sanity: 3 })),
  ] }),
  E('wr_father_returns', 'war', { on: 'scheduled', if: { npc: { x: true } }, art: 'road', title: 'Home from the wall', text: '{x} comes home from the northern wall three years later: thinner, quieter, limping, with a carved wooden bird for you.', choices: [
    C('Take the bird', O('You kept the bird on your windowsill for the rest of your childhood. {x} never talked about the wall. Some nights {x.he} stood at the door and looked north.', { rel: { x: { aff: 15 } }, sanity: 4 })),
    C('Ask about the wall', O('"Long," {x} said. "Cold. Full of boys." Then {x.he} went out to look at the rice.', { rel: { x: { aff: 8 } }, insight: 1 })),
  ] }),

  // ── Years 41–52: peace, and what it costs ────────────────────────────────
  E('wr_peace_news', 'war', { if: { happened: 'yellow_ford', year: [41, 42], age: [8, 100] }, art: 'city', title: 'Peace', text: 'The criers say the Blood Demon is dead at the Yellow River Ford and the war is over. Nobody cheers at first. Then a child bangs a pot, and another, and by evening the whole street is a riot of pots.', choices: [
    C('Bang a pot', O('You banged a pot until your arm ached. It was the least dignified thing you had done in years, and you do not regret it.', { sanity: 8 })),
    C('Go to the temple and light lamps', O('The temple ran out of lamps by dusk. People lit candles, then sticks, then their own lanterns, until the courtyard was a field of small fires for the dead.', { sanity: 4, insight: 1 })),
    C('Get very drunk', O('You got very drunk with strangers and woke under a table beside a strange dog, unable to remember whose victory it had been.', { sanity: 5, health: -2 })),
  ] }),
  E('wr_veteran_beggar', 'war', { once: false, cd: 6, if: { flag: 'w.postwar', locType: 'city', year: [42, 80], age: [20, 100] }, art: 'inn', text: 'A legless man on a cart outside a {loc} wine-house wears an Alliance pension token around his neck. It has never paid. He sings marching songs for coppers, the clean versions.', choices: [
    C('Give him a tael', O('He bit it, thanked you, and sang you the rude version of the third song as a reward.', { wealth: -1, sanity: 2 })),
    R('Take his token to the Alliance office and shout', 'fame', 30, O('You shouted until a clerk paid two years of arrears to make you stop. The legless man bought the whole wine-house a round with it.', { fame: 3, sanity: 4 }), O('The clerk explained that the pension office had been closed for economy. You shouted at an empty room.', { sanity: -2 })),
    C('Sing with him', O('You knew the words. That surprised him. It surprised you too, a little.', { charm: 1, sanity: 3 })),
  ] }),
  E('wr_collab_trial', 'war', { if: { flag: 'w.postwar', year: [42, 46], loc: 'luoyang', age: [16, 90] }, art: 'palace', title: 'The tribunal', text: 'The Alliance is trying collaborators in Luoyang: anyone who sold the Cult so much as a bowl of noodles. Today it is a baker from Chang’an whose bread fed a Cult scouting patrol. He says they had swords. They did.', choices: [
    C('Testify for the baker', O('You told the tribunal what a sword at a baker’s throat looks like. They let him off with a fine. He sent you bread for a year, slightly burnt.', { fame: 3, sanity: 4, rep: { orthodox: -2 } })),
    C('Keep your head down', O('The baker was flogged and his ovens broken up. The tribunal moved on to a ferryman.', { sanity: -4 })),
    M('Ask the tribunal about the Alliance granary', 'secret.wr_grain_ledger', O('You asked, in public, why the tribunal was trying bakers when the Alliance’s own carts had driven rice west by the thousand sacks. The tribunal adjourned. It never met again.', { fame: 8, rep: { orthodox: -6 }, infamy: 2 })),
  ] }),
  E('wr_cult_children', 'war', { danger: true, if: { flag: 'w.postwar', region: ['guanzhong', 'west'], year: [42, 52], age: [16, 90] }, art: 'snow', text: 'Alliance zealots are hunting "Cult brats" in the western valleys: children of believers, left behind when the armies broke. You have found four of them first, in a shepherd’s hut, sharing one blanket.', choices: [
    R('Get them over the Jade Gate before the zealots come', 'body', 30, O('Nine days of goat paths. At the pass a Cult patrol took the children from you without a word, and then one of the soldiers came back to bow.', { sanity: 8, rep: { cult: 8, orthodox: -2 }, fame: 2 }), O('The zealots caught up with you on the sixth day.', { combat: { foe: { name: 'a zealot captain', kind: 'disciple', rel: 0 }, context: 'duel', lethal: 0.2, win: { text: 'They took their wounded and left you the children. You got all four over the pass.', sanity: 6, rep: { cult: 8, orthodox: -5 } }, lose: { text: 'They took the children. You do not know where.', sanity: -15 } } })),
    Q('Pay a farming widow to raise them as her own (20 taels)', { wealth: '>=20' }, O('The widow looked at the four of them, sighed, and put a pot on. Nobody in her valley ever asked where her new grandchildren came from.', { wealth: -20, sanity: 6, fame: 1 })),
    C('Leave them', O('You left them the rest of your food and walked away. You did not look back at the hut, and then you did.', { sanity: -10 })),
  ] }),
  E('wr_ten_years', 'war', { if: { happened: 'yellow_ford', year: [51, 52], any: VETERAN, age: [20, 100] }, art: 'river', title: 'Ten years', text: 'Ten years since the Yellow River Ford. A dozen old soldiers have met on the bank every summer. This year there are nine. They have saved you a place.', choices: [
    C('Go', O('Nine old soldiers and a jar of wine, and the river exactly as wide as it was. Someone told the story of the second charge wrong, and nobody corrected him.', { sanity: 8, fame: 1 })),
    C('Send wine and stay away', O('You sent the best wine you could buy. They drank it and complained it was too good for them.', { wealth: -5, sanity: 2 })),
  ] }),
  E('wr_drought_bandits', 'war', { if: { happened: 'hebei_drought', year: [46, 49], region: 'hebei', age: [16, 100] }, art: 'forest', text: 'The drought has filled the Green Forest with farmers who never held a saber before this spring. An imperial army is marching on the Taihang to "restore order". {@mountain_tiger} would surrender the farmers for grain, if anyone would carry the offer.', choices: [
    R('Carry it to the imperial commander', 'charm', 35, O('Three thousand farmers came down from the Taihang with their hands tied and went home with seed grain. The commander took the credit, and the real bandits thanked you for clearing out the dead weight.', { fame: 6, rep: { court: 4, unorthodox: 6 }, sanity: 6 }), O('The commander had hanged the last messenger, so you did not wait to be the second.', { rep: { court: -3 } })),
    C('Join the army', O('You marched on the Taihang and found mostly starving farmers. It was not a glorious campaign.', { rep: { court: 5, unorthodox: -5 }, sanity: -6, wealth: 8 })),
    Q('Bring grain up the mountain yourself (25 taels)', { wealth: '>=25' }, O('Twenty-five taels of millet on six mules. Ma Hu met you at the gate himself and said nothing at all, which from him was a speech.', { wealth: -25, rel: { '@mountain_tiger': { aff: 20, res: 15 } }, rep: { unorthodox: 8 }, fame: 2 })),
  ] }),

  // ── The war that never was ───────────────────────────────────────────────
  E('wr_war_that_wasnt', 'war', { if: { ...LATER, averted: 'cult_war', year: [34, 45], region: 'central', age: [20, 100] }, art: 'river', title: 'The war that never was', text: 'You stand at the Yellow River Ford, where in another life the water ran red. It is a ford. Cows are crossing it. A boy is fishing in the shallows where the Blood Demon died.', choices: [
    C('Sit down and watch the cows', O('You watched the cows for an hour. One of them looked back at you. You cried a little, and the cow did not mind.', { sanity: 15 })),
    C('Ask the boy his name', O('He told you. It was a name you had read on a stone at the Ford, in another life. You bought his whole catch.', { sanity: 10, wealth: -2 })),
  ] }),
  E('wr_peace_caravan', 'war', { if: { or: [{ happened: 'peace_kept' }, { averted: 'cult_war' }], alive: 'haryeong', region: 'west', year: [34, 60], age: [16, 100] }, art: 'desert', text: 'A Cult caravan at the Jade Gate: salt, horses and mountain wool under red banners with white borders, the new sign for trade. The caravan master has a list of what the Cult wants from the east. Medicine is at the top.', choices: [
    C('Trade', O('You traded silver for wool and wool for silver in Chang’an, came out ahead, and made a friend among the guards who swore the Young Heavenly Demon had written the trade laws herself.', { wealth: 20, rep: { cult: 4, merchants: 3 } })),
    C('Ask about the Young Heavenly Demon', O('"She is building schools," the caravan master said, in the tone of a man who thought this a strange use of a Heavenly Demon. "And roads. The roads are good."', { insight: 1, rep: { cult: 2 } })),
    Q('Sell them medicine at cost (20 taels)', { wealth: '>=20' }, O('A Cult physician took the salves and bowed in the eastern style, awkwardly, as if he had practised. Word of you would go west.', { wealth: -20, fame: 3, rep: { cult: 10 } })),
  ] }),

  // ── Years 55–60: the Registry, the Beggars, the coup ─────────────────────
  E('wr_registry_choice', 'war', { if: { happened: 'registry_edict', realm: '>=1', year: [55, 59], age: [16, 100], not: 'wr.registry_done' }, art: 'palace', title: 'The Registry', text: 'A Depot clerk has set up a table in the square of {loc} under a banner that reads, in beautiful calligraphy, MARTIAL ARTISTS REGISTER HERE. Behind him, a line. Behind the line, crossbows.', choices: [
    C('Register', O('Name, sect, realm, techniques, and the names of your masters and disciples. The clerk wrote it all down and gave you a wooden tag to wear. It is very light, for what it is.', { flag: 'wr.registry_done', rep: { court: 5, orthodox: -3 }, sanity: -4 })),
    R('Register under a false name', 'insight', 35, O('A new name, a new sect, a realm two ranks below yours. The clerk did not blink.', { flag: 'wr.registry_done', insight: 1 }), O('The clerk turned a page in an old ledger, Year 40, and found your real name.', { flag: ['wr.registry_done', 'wr.outlaw'], rep: { court: -8 }, infamy: 4 }), { show: { not: 'wr.depot_listed' } }),
    C('Walk away from the line', O('You walked away. By evening your name was on a different list.', { flag: ['wr.registry_done', 'wr.outlaw'], rep: { court: -10 }, infamy: 3, fame: 2 })),
  ] }),
  E('wr_outlaw_hunt', 'war', { once: false, cd: 3, danger: true, if: { flag: ['wr.outlaw', 'w.registry'], age: [16, 100] }, art: 'night', text: 'Depot hunters in the inn downstairs, asking the landlord about someone who looks like you. The landlord is taking a long time to answer, which is either loyalty or haggling.', choices: [
    R('Out the window and over the roofs', 'body', 35, O('Roof to roof, down a drainpipe, into a cart of cabbages. When they kicked in your door you were two streets away and smelled of cabbage.', { body: 1 }), O('A loose tile, a long fall. You got away, limping.', { injury: { name: 'twisted ankle', seasons: 2, sev: 8 } })),
    C('Wait for them on the stairs', O('The first hunter on the stairs was very surprised.', { combat: { foe: { name: 'a Depot hunter', kind: 'soldier', rel: 0 }, context: 'ambush', lethal: 0.3, win: { text: 'The hunters left with their wounded, and you left before more came.', infamy: 4, rep: { court: -6 } }, lose: { text: 'They beat you, fined you, and let you go as a warning to others.', wealth: -30, rep: { court: -4 } } } })),
    Q('Pay the landlord more than they would (20 taels)', { wealth: '>=20' }, O('The landlord remembered that the person they wanted had left that morning, going south.', { wealth: -20 })),
  ] }),
  E('wr_beggar_halls', 'war', { w: 3, if: { happened: 'registry_edict', timeline: { beggars_outlawed: 'pending' }, year: [55, 57], loc: 'luoyang', age: [16, 100] }, art: 'city', text: '{@beggar_chief} refuses to register the Beggars’ Sect. "Half my people have no names," he says. "The other half have six." The Depot has given him until spring.', choices: [
    R('Persuade him to register every beggar as "Hong"', 'charm', 40, O('Forty thousand beggars, all named Hong, all Third-Rate, all living under the same bridge. The Depot clerks wept. But the Sect was registered, and the Depot had no excuse to burn it.', { avert: 'beggars_outlawed', fame: 8, rel: { '@beggar_chief': { aff: 20, res: 20 } }, gaze: 1 }), O('"I would rather burn," said Hong Chil cheerfully, and ate your dumpling.', { rel: { '@beggar_chief': { res: 5 } } })),
    M('Tell him exactly when the Depot comes', 'timeline.beggars_outlawed', O('He listened with his eyes closed. When the Depot came, the halls were empty: every beggar in Luoyang had become, overnight, some other city’s problem.', { flag: 'wr.beggars_scattered', fame: 4, rel: { '@beggar_chief': { res: 15 } } })),
    C('Wish him luck', O('"Luck is for gamblers," he said. "Beggars use patience."')),
  ] }),
  E('wr_beggar_burn', 'war', { danger: true, if: { happened: 'beggars_outlawed', year: [57, 58], loc: 'luoyang', alive: 'dongsu', not: 'wr.beggars_scattered', age: [16, 100] }, art: 'fire', text: 'The Depot is burning the Beggars’ halls under the bridges of Luoyang. In the smoke you hear {@dongsu}’s voice, shouting the children toward the river.', choices: [
    C('Cut through the Depot line to him', O('A Depot officer in embroidered black stepped into your way.', { combat: { foe: { name: 'a Depot officer', kind: 'soldier', rel: 0 }, context: 'war', lethal: 0.3, win: { text: 'You and Dong-su got the last of the children into the boats. He grinned at you through the soot. "Took your time."', rel: { '@dongsu': { aff: 20, res: 15 } }, rep: { court: -10, orthodox: 6 }, fame: 5 }, lose: { text: 'You went into the river with a saber cut across your back. Downstream someone hauled you out: Dong-su, with three children clinging to him.', rel: { '@dongsu': { aff: 10 } }, rep: { court: -6 } } } })),
    R('Bring boats to the river side', 'insight', 30, O('You cut every boat loose along the quay and poled them under the bridge. The children came out of the smoke and into the boats, and Dong-su came last, coughing and swearing.', { rel: { '@dongsu': { aff: 15 } }, fame: 4, rep: { court: -4 } }), O('The current took the boats before the children reached them. Some swam. Some did not.', { sanity: -10, meet: '@dongsu' })),
    C('Stay out of the Depot’s way', O('You stayed out of the Depot’s way. In the morning the bridges were black, and the river was full of ash and sandals.', { sanity: -8 })),
  ] }),
  E('wr_coup_night', 'war', { if: { flag: 'w.registry', year: [59, 60], loc: 'capital', alive: 'guard_commander', age: [16, 100] }, art: 'palace', text: '{@guard_commander} of the Imperial Guard finds you in a teahouse and talks about the weather for a quarter of an hour. Then, quietly: the Director moves soon, and the Guard is small. Will you watch the east gate on a night he will name?', choices: [
    C('Watch the east gate', O('On the night he named, the Director’s men came to the east gate with a forged pass. You and four tired guardsmen held it until Han Gyeong arrived with the rest. The rest of the night belonged to him.', { rel: { '@guard_commander': { res: 25, aff: 15 } }, fame: 8, rep: { court: 8 } })),
    C('Tell him you are no soldier', O('"Neither am I, any more," he said, and paid for the tea.', { meet: '@guard_commander' })),
    C('Sell his plan to the Depot', O('The Depot paid in gold, and Han Gyeong’s name went onto a list. History had its own plans: the coup failed anyway. Han Gyeong never looked at you again.', { wealth: 120, infamy: 10, rep: { court: 4 }, sanity: -10, rel: { '@guard_commander': { aff: -40 } } })),
  ] }),

  // ── Years 66–79: the Second War ──────────────────────────────────────────
  E('wr_remnants_avert', 'war', { w: 3, if: { happened: 'cult_remnants', timeline: { second_war: 'pending' }, year: [66, 73], age: [30, 200], or: [{ mem: 'timeline.second_war' }, { stat: { fame: '>=60' } }] }, art: 'demonic', title: 'The new master', text: 'Red banners again in the Ten Thousand Mountains. The Cult’s new master is young, and listens to old men who remember the last war as a glorious one. Somebody should tell him what it was really like.', choices: [
    R('Go west and tell him yourself', 'fame', 50, O('You crossed the Jade Gate without an escort and talked for three days in a hall of red banners: the Ford, the sheepfold, the burnt wheat. He was quiet for a long time. The Cult did not come east.', { avert: 'second_war', fame: 15, rep: { cult: 10 }, gaze: 2, sanity: 5 }), O('He heard you out politely and had you escorted back to the pass. The banners kept multiplying.', { rep: { cult: -3 } })),
    M('Send him the names of those who died at the Ford, on both sides', 'timeline.yellow_ford', O('A cart of scrolls, every name you could gather. He read them himself, all winter. In spring he sent an envoy east with salt instead of soldiers.', { avert: 'second_war', fame: 8, gaze: 2, sanity: 8 })),
    C('Prepare the young for war instead', O('You trained every child who would stand still. When the Cult came, some of them lived because of you.', { insight: 2, fame: 2 })),
  ] }),
  E('wr_second_war_elder', 'war', { if: { happened: 'second_war', year: [74, 79], age: [55, 200] }, text: 'A boy with a new sword and a new armband asks you, very respectfully, what the first war was like. He is going to the second one tomorrow.', choices: [
    C('Tell him the truth', O('You told him about the mud, the camp fever, the boy with the crushed leg. He listened very seriously, and went anyway. You hoped he would remember the part about boiling the water.', { sanity: -2, insight: 1 })),
    C('Tell him the story he wants', O('You told him about the Blood Demon’s death at the Ford, with sword qi lighting up the river. His eyes shone. Yours did too, for different reasons.', { charm: 1, sanity: 2 })),
    C('Teach him one thing that will keep him alive', O('How to keep his guard up when he is tired. How to bind a wound. When to run. He practised until dark.', { fame: 1, sanity: 3 })),
  ] }),
];

// ── Templates ──────────────────────────────────────────────────────────────

// Battles, one per front. Fighting is always your choice; there is always another way through.
const tplBattle = template('wr_battle', [
  { key: 'dongting', if: { happened: 'grain_fleet', year: [14, 18], region: 'jingchu', age: [14, 70] }, art: 'lake', title: 'Battle in the reeds',
    text: 'Imperial war junks push into the Dongting reeds at dawn, and the reeds push back: fire-rafts, swimmers with hooks, arrows from nowhere. A Water Fortress raider climbs over the gunwale beside you with a knife in his teeth.',
    foe: { name: 'a Water Fortress raider', kind: 'bandit', rel: 0 }, lethal: 0.25,
    fight: ['Meet him at the gunwale', 'You met him blade to knife on a wet deck.'],
    win: { text: 'He went back into the lake the way he came, and the junk’s captain paid you a raider’s bounty.', wealth: 10, rep: { court: 4, unorthodox: -4 }, fame: 2 },
    lose: { text: 'You went into the lake too. A fisherman pulled you out downstream and charged you for the trouble.', wealth: -5 },
    alt: ['Dive and cut the fire-raft’s tow rope', 'body', 30, O('You came up under the raft, sawed through the tow rope, and watched it drift back into the Fortress’s own reeds. The captain called it the best thing he had seen all war.', { fame: 4, rep: { court: 5 }, body: 1 }), O('The water was full of hooks. You came up bleeding and empty-handed.', { health: -10 })],
    help: ['Haul the wounded below decks', O('You spent the battle below decks in the dark, holding men still while the hull boomed. The junk made it back to Wuchang, and most of them did too.', { sanity: -2, fame: 1, rep: { court: 2 } })],
    leave: ['Go over the side and swim for shore', O('You swam for shore. The reeds hid you. They hid a great many things that day.', { health: -3, rep: { court: -2 } })] },
  { key: 'jegal_gate', if: { flag: 'wr.feud_war', not: 'wr.feud_ended', year: [24, 30], region: 'hebei', age: [16, 70] }, art: 'estate', title: 'The Jegal gate',
    text: 'The Namgung come at the Jegal Estate in a wedge of white silk and drawn swords. The Jegal wait behind a garden that rearranges itself: stones, pines and lanterns that are never quite where you left them.',
    foe: { name: 'a Jegal formation master', kind: 'disciple', rel: 0 }, lethal: 0.2,
    fight: ['Cut straight through the garden', 'The formation folded around you, and a Jegal master stepped out of it.'],
    win: { text: 'You broke the formation’s living gate and the Namgung poured through after you. It was a victory. Afterwards, counting the dead of both families, nobody felt like it.', fame: 4, rep: { families: 4 }, sanity: -3 },
    lose: { text: 'The garden turned you about until you walked out of it backwards and into a carp pond.', health: -4 },
    alt: ['Read the formation from outside', 'insight', 38, O('You watched the lanterns for an hour and saw it: the Gate of Life moves with the shadow of the tallest pine. You stopped twelve Namgung swordsmen walking into the Gate of Death.', { insight: 3, rep: { families: 5 }, fame: 2 }), O('The pattern made sense for one moment and then none at all. You walked into a pine.', { health: -2 })],
    help: ['Carry the wounded of both houses to the same tent', O('Namgung and Jegal wounded lay in the same tent and argued weakly about who had started it. Nobody died arguing. A few were friends by the end.', { rep: { families: 3 }, sanity: 2 })],
    leave: ['Refuse to fight a war between cousins', O('You sat on a wall and watched. Both families noticed. Neither forgave you for it, or for being right.', { rep: { families: -2 }, sanity: 1 })] },
  { key: 'dang_court', if: { happened: 'dang_civil_war', year: [26, 27], region: 'shu', age: [16, 70] }, art: 'estate', title: 'The inner court',
    text: 'Dang Gwang’s men storm the inner court of the Dang manor at dusk. The air is full of needles and something sweet you should not breathe. A poisoner in grey steps out of the rain of darts in front of you.',
    foe: { name: 'a Dang poisoner', kind: 'assassin', rel: 0 }, lethal: 0.3,
    fight: ['Close with the poisoner', 'You closed the distance before the next dart.'],
    win: { text: 'He fell among the peonies, and the loyalists held the inner court. A Dang elder gave you a salve without being asked, which in the Dang manor is a declaration of love.', rep: { families: 6 }, fame: 3, item: { healing_salve: 1 } },
    lose: { text: 'A needle in your neck. You woke three days later in a loyalist sickroom, with a Dang physician taking notes on your symptoms.', health: -12 },
    alt: ['Hold your breath and drag the fallen out of the cloud', 'health', 55, O('You pulled six of them out before the sweet air made your eyes stream. All six lived. The Dang keep count of such things.', { fame: 3, rep: { families: 5 } }), O('You breathed. Everything turned lilac for a day.', { health: -10, sanity: -3 })],
    help: ['Light the lanterns for the archers', O('You ran the walls with a taper, lighting lanterns so the loyalist archers could see. A dart took the lantern from your hand twice; you lit it three times.', { rep: { families: 2 }, insight: 1 })],
    leave: ['Climb out over the poison garden wall', O('You went over the garden wall very carefully, touching nothing. Afterwards you burned your shoes.', { rep: { families: -1 } })] },
  { key: 'jade_gate', if: { happened: 'blood_demon_throne', year: [31, 33], region: 'west', age: [16, 70] }, art: 'desert', title: 'The Jade Gate',
    text: 'Cult outriders hit the Jade Gate garrison at noon, testing it the way a cat tests a door. The gate captain has forty men, one beacon, and a great deal of sand in his armour.',
    foe: { name: 'a Cult outrider', kind: 'cultist', rel: -0.5 }, lethal: 0.25,
    fight: ['Ride out with the captain', 'You rode out into the glare with the captain’s forty.'],
    win: { text: 'The outriders turned back into the desert. On the one you unhorsed you found a quartermaster’s tally: three granaries outside the pass, filled last winter, enough to feed an army on the road east.', codex: GRANARIES, fame: 3, rep: { court: 3 } },
    lose: { text: 'An outrider’s horse went over you. You woke in the gatehouse with the captain pouring water on your face.', health: -6 },
    alt: ['Ride for the beacon tower', 'body', 32, O('You lit the beacon with arrows hissing past. Fifty li east the next tower answered, and the next. The Alliance was told. The Alliance did nothing, but it was told.', { fame: 4 }), O('Your horse took an arrow halfway there. You walked the rest, and someone else lit the beacon.', { health: -6 })],
    help: ['Get the caravan families inside before the gate shuts', O('Two caravans, sixty people, eleven camels and a goat that refused. The gate shut behind the goat.', { sanity: 3, fame: 1, rep: { merchants: 3 } })],
    leave: ['Ride east before the gate shuts', O('You rode east. Behind you the gate shut, and you heard the drums for a long time.', { sanity: -2 })] },
  { key: 'kongtong', if: { happened: 'cult_war', timeline: { kongtong_falls: 'pending' }, year: [34, 35], region: 'guanzhong', age: [16, 70] }, art: 'mountain', title: 'Kongtong’s north gate', w: 2,
    text: 'A dust storm comes down off the plateau at dusk, and in it Cult warriors are climbing the dry gully behind Kongtong’s north gate. Every fist-master is on the western wall. A Blood Faction vanguard climbs out of the gully in front of you.',
    foe: { name: 'a Blood Faction vanguard', kind: 'cultist', rel: 0 }, lethal: 0.35,
    fight: ['Hold the head of the gully', 'You planted your feet at the head of the gully.'],
    win: { text: 'You held the gully long enough for the fist-masters to come running. Kongtong did not fall, though it would have; you saw exactly how.', avert: 'kongtong_falls', codex: KONGTONG_GULLY, fame: 6, rep: { orthodox: 8 }, gaze: 1 },
    lose: { text: 'They went past you. You crawled down the mountain in the dust while Kongtong burned above you.', codex: KONGTONG_GULLY, health: -8 },
    alt: ['Roll the gully’s boulders down on them', 'body', 40, O('The first boulder took the second, and the second took the gully. The climb was blocked until dawn, and by dawn the fist-masters were waiting. Kongtong did not fall.', { avert: 'kongtong_falls', codex: KONGTONG_GULLY, fame: 4, rep: { orthodox: 6 }, gaze: 1 }), O('The boulder did not move. They did.', { codex: KONGTONG_GULLY, health: -6 })],
    help: ['Get the novices down the south stair', O('Thirty novices, the youngest six years old, down the south stair in the dark, holding a rope. You counted them at the bottom three times.', { sanity: 4, fame: 3, rep: { orthodox: 4 } })],
    leave: ['Go down the south stair alone', O('You went down alone. Halfway, you heard the novices behind you, and did not wait.', { sanity: -8 })] },
  { key: 'changan', if: { happened: 'kongtong_falls', year: [35, 38], loc: 'changan', age: [16, 70] }, art: 'city', title: 'The walls of Chang’an',
    text: 'The Cult brings ladders to Chang’an’s west wall, the old one the city council has been meaning to repair for sixty years. A Cult siege captain reaches the top of a ladder beside you.',
    foe: { name: 'a Cult siege captain', kind: 'cultist', rel: 0 }, lethal: 0.3,
    fight: ['Meet him at the top of the ladder', 'You met him with the ladder still swaying under him.'],
    win: { text: 'He went back down the ladder faster than he came up. The council voted you a commendation and then, to be fair, voted to repair the wall.', fame: 5, rep: { orthodox: 4, court: 3 }, wealth: 6 },
    lose: { text: 'He threw you off the wall into a cabbage cart. The cabbages, at least, were kind.', health: -8 },
    alt: ['Rally the shopkeepers on the wall', 'charm', 30, O('A butcher with a cleaver, a teacher with a ladle and you, shouting. The ladder went down. The butcher has told the story ever since, and you are in it.', { fame: 4, charm: 1 }), O('The shopkeepers looked at you, then at the ladder, and went home.', { sanity: -3 })],
    help: ['Carry boiling water up the wall steps', O('Up and down the steps until your arms were scalded and your legs were water. Nobody sings about the water-carriers. The wall held.', { body: 2, health: -3 })],
    leave: ['Hide in the bell tower', O('You hid in the bell tower and watched the ladders rise and fall. The wall held without you. You were very glad, and a little ashamed.', { sanity: -3 })] },
  { key: 'song', if: { happened: 'cult_war', year: [35, 36], region: 'central', age: [16, 70] }, art: 'temple', title: 'The steps of Mount Song',
    text: 'The Cult’s main army climbs Mount Song in the snow. Warrior monks hold the thousand steps in a line of saffron and iron staves. A Cult elder’s disciple comes up the steps toward you, palms already black.',
    foe: { name: 'a Cult elder’s disciple', kind: 'cultist', rel: 0.5 }, lethal: 0.3,
    fight: ['Take a step down to meet him', 'You took one step down, which on Mount Song is a vow.'],
    win: { text: 'You knocked him down a hundred steps. The monk beside you said a short prayer for him and went back to fighting. Shaolin held, barely.', fame: 6, rep: { orthodox: 8 } },
    lose: { text: 'His palm left a black print on your chest that ached every winter for years. The monks carried you up to the infirmary.', health: -12 },
    alt: ['Join the monks’ Golden Bell line', 'qi', 40, O('You linked arms and breath with the monks, and for a moment the whole line breathed as one body. The Cult’s charge broke on it like water on a bell.', { qi: 15, insight: 2, rep: { orthodox: 6 } }), O('Your qi was not enough. The line held without you, and you stumbled out of it coughing blood.', { health: -8 })],
    help: ['Carry arrows up from the storerooms', O('A thousand steps, a hundred times. The monks who took the arrows from you never once said thank you, and never once let the quivers run dry.', { body: 1, rep: { orthodox: 3 } })],
    leave: ['Slip down the back of the mountain', O('You slipped down the back of the mountain while the bells rang. They rang for three days.', { sanity: -4 })] },
  { key: 'wudang', if: { happened: 'cult_war', year: [36, 37], region: 'jingchu', age: [16, 70] }, art: 'mountain', title: 'The Wudang slopes',
    text: 'The Cult comes up through Wudang’s seventy-two peaks in fog. The disciples meet them in pairs, swords turning in slow circles, as if the battle were a lesson. Out of the fog, a Blood Faction swordsman finds you.',
    foe: { name: 'a Blood Faction swordsman', kind: 'cultist', rel: 0 }, lethal: 0.3,
    fight: ['Turn with him, the way the disciples do', 'You let his first cut go past and turned with it.'],
    win: { text: 'His blade slid off yours and into a pine. A Wudang elder nodded at your form as he passed, which you will be proud of until you die.', fame: 5, rep: { orthodox: 6 }, insight: 1 },
    lose: { text: 'You were cut, and fell, and rolled into a hermit’s vegetable garden. He bandaged you and complained about his leeks.', health: -10 },
    alt: ['Lead them into the fog the wrong way', 'insight', 35, O('You led a Cult column into a valley that ends in a cliff. They stood at the edge in the fog for an hour arguing about whose fault it was.', { fame: 4, rep: { orthodox: 5 } }), O('You got lost in your own fog, and came out at the bottom of the mountain at noon.', { health: -4 })],
    help: ['Keep the lamps lit in the Golden Hall', O('All night you kept the lamps lit so the wounded could find their way up. Near dawn, an old Daoist sat beside you and taught you to breathe with the flames.', { sanity: 3, qi: 6 })],
    leave: ['Wait out the fog in a cave', O('You waited out the fog in a cave with a goat. When it lifted the battle was over and the goat had eaten your sleeve.', { sanity: -2 })] },
  { key: 'namgung', if: { happened: 'cult_war', timeline: { namgung_burns: 'pending' }, year: [37, 38], region: 'jiangnan', age: [16, 70] }, art: 'estate', title: 'The Namgung gate', w: 2,
    text: 'The Cult comes at the Namgung Estate from three sides, and the Namgung meet it at the front gate, all together, in white, because that is how a Namgung fights. A Cult commander is cutting his way toward {@namgung_jin}.',
    foe: { name: 'a Cult commander', kind: 'cultist', rel: 0.5 }, lethal: 0.35,
    fight: ['Take the commander on his flank', 'You came at the commander from his blind side.'],
    win: { text: 'You took the commander off Namgung Jin’s flank. He did not thank you; he nodded once, which from a Namgung is a poem.', fame: 6, rep: { families: 10 }, rel: { '@namgung_jin': { res: 20 } } },
    lose: { text: 'The commander went through you on his way to the gate. You lay in the courtyard and watched the east granary catch fire.', codex: NAMGUNG_GRANARY, health: -12 },
    alt: ['Run to the east granary', 'insight', 35, O('You found the new cooks in the granary with oil jars and flint, and shouted until half the courtyard came running. The granary did not burn, and neither did the Estate.', { avert: 'namgung_burns', codex: NAMGUNG_GRANARY, fame: 6, rep: { families: 8 }, gaze: 1 }), O('You were too late. The granary was already roaring.', { codex: NAMGUNG_GRANARY, sanity: -5 })],
    help: ['Get the sword-students out of the west court', O('Namgung So-hee’s students, twelve girls with practice swords, out through the west court and into the rice paddies. She saw you go, and did not stop you.', { rep: { families: 4 }, sanity: 3, rel: { '@namgung_sohee': { aff: 10 } } })],
    leave: ['Go over the back wall', O('You went over the back wall into the paddies. The Estate glowed behind you all night.', { sanity: -6 })] },
  { key: 'luoyang', if: { happened: 'alliance_betrayal', year: [39, 40], loc: 'luoyang', age: [16, 70] }, art: 'city', title: 'The bridges of Luoyang',
    text: 'With its Leader fled and the Alliance in uproar, the Cult strikes at Luoyang itself. Beggars hold the bridges with staves and broken bottles. A Cult raider vaults the parapet in front of you.',
    foe: { name: 'a Cult raider', kind: 'cultist', rel: -0.5 }, lethal: 0.25,
    fight: ['Hold the bridge with the Beggars', 'You took a place in the line of staves.'],
    win: { text: 'The raider went over the parapet backwards into the Luo. The Beggars cheered and passed you a bottle that was not, it turned out, broken.', fame: 4, rep: { orthodox: 5 }, rel: { '@beggar_chief': { res: 10 } } },
    lose: { text: 'He knocked you flat and ran on. A Beggar child dragged you under the bridge and sat on you until it was over.', health: -8 },
    alt: ['Drop the bridge’s centre span', 'insight', 40, O('Three pins, a lot of swearing, and the centre span fell into the river with a dozen raiders on it. Luoyang has been one bridge short ever since, and is proud of it.', { fame: 5, rep: { orthodox: 6 } }), O('The pins would not come out. You were still pulling when the raiders came over.', { health: -6 })],
    help: ['Hide the street children in the Beggars’ tunnels', O('Thirty children in the dark under the city, and you telling stories in a whisper until the fighting overhead stopped. Some of them remember the stories still.', { sanity: 4, charm: 1, rep: { orthodox: 3 } })],
    leave: ['Bar your door and wait', O('You barred your door and waited. The bridges held without you.', { sanity: -3 })] },
  { key: 'ford', if: { happened: 'depot_army', year: 41, region: 'central', age: [16, 80] }, art: 'river', title: 'The Yellow River Ford', w: 2,
    text: 'The Alliance crosses the Yellow River at the Ford in the grey before dawn, waist-deep, swords held over their heads. On the far bank the red banners wait. A Blood Faction elder wades out to meet you.',
    foe: { name: 'a Blood Faction elder', kind: 'cultist', rel: 1 }, lethal: 0.35,
    fight: ['Meet him in the water', 'You met him waist-deep, the current pulling at you both.'],
    win: { text: 'You held the shallows until the second wave reached the bank. When the Blood Demon fell, later, you were close enough to see it.', fame: 10, rep: { orthodox: 10 } },
    lose: { text: 'The river took you downstream. A Depot boat fished you out, and a clerk wrote your name in a ledger.', health: -12, flag: 'wr.depot_listed' },
    alt: ['Find the shallows the Cult is not watching', 'insight', 35, O('A li upstream, a sandbar ran nearly bank to bank under knee-deep water. Two hundred swords crossed there and came at the red banners from the side.', { fame: 6, rep: { orthodox: 6 }, codex: FORD_SANDBAR }), O('You found a sandbar, and then the deep water past it.', { health: -6 })],
    help: ['Pull the drowning out of the Ford', O('You stood in the river all day pulling men out by their collars. You do not know how many. Neither does anyone else.', { sanity: -3, fame: 3, health: -4 })],
    leave: ['Stay on the near bank', O('You stayed on the near bank and watched the river go red and then brown again. Somebody had to watch.', { sanity: -5 })] },
  { key: 'taihang', if: { happened: 'hebei_drought', year: [46, 49], region: 'hebei', age: [16, 80] }, art: 'forest', title: 'The Taihang campaign',
    text: 'The imperial army storms the Green Forest strongholds of the Taihang one by one. Most of the defenders are starving farmers. Some are not. A Green Forest axeman with a scarred face comes down the stockade at you.',
    foe: { name: 'a Green Forest axeman', kind: 'bandit', rel: 0 }, lethal: 0.25,
    fight: ['Meet the axeman', 'You met the axe on its way down.'],
    win: { text: 'The axeman went down and the stockade opened. Inside were sixty farmers and a single sack of millet. The army’s paymaster still paid you a bounty.', rep: { court: 5, unorthodox: -5 }, wealth: 12, sanity: -2 },
    lose: { text: 'The axe handle caught you across the head. You woke in an army tent with a lump like a hen’s egg.', health: -8 },
    alt: ['Talk the farmers out of the stockade', 'charm', 30, O('You walked up to the stockade with your hands open and talked about seed grain and pardons. Forty farmers came out. The axeman, alone, went back up the mountain.', { rep: { court: 2, unorthodox: 3 }, sanity: 4 }), O('A stone from the stockade hit you on the shoulder. Nobody came out.', { health: -4 })],
    help: ['Bury the dead of both sides', O('You buried soldiers and farmers in the same field. A sergeant objected. You kept digging, and after a while he helped.', { sanity: 2, fame: 1 })],
    leave: ['Desert the campaign', O('You walked off into the hills one night. Nobody came looking; half the army was doing the same.', { rep: { court: -4 } })] },
  { key: 'second_pass', if: { happened: 'second_war', year: [74, 77], region: 'guanzhong', age: [16, 120] }, art: 'mountain', title: 'The western passes again',
    text: 'The Cult comes through the western passes again, a generation later, by the same roads. The young Alliance captain has never seen a war. You have. A Cult warrior half your age comes at you, very fast.',
    foe: { name: 'a young Cult warrior', kind: 'cultist', rel: 0 }, lethal: 0.3,
    fight: ['Meet him the way you learned to', 'You let him come, the way the old war taught you.'],
    win: { text: 'You knocked the sword from his hand and he stared at you. You let him run. Some things you have learned.', fame: 4, sanity: 3 },
    lose: { text: 'He was faster than you remembered being. You were carried off the pass on a shield.', health: -10 },
    alt: ['Tell the captain where they will come from', 'fame', 40, O('He listened, for once, because of who you were. The Cult came exactly where you said and found the whole company waiting.', { fame: 5, rep: { orthodox: 6 } }), O('"Things are different now, grandfather," the captain said. They were not.', { sanity: -4 })],
    help: ['Teach the recruits to dig in', O('You showed a company of children how to dig a trench that does not flood. Some of them lived because of it, and never knew.', { fame: 2, sanity: 2 })],
    leave: ['Go home; this war is theirs', O('You went home. You had fought your war. It did not feel as fair as it sounded.', { sanity: -2 })] },
  { key: 'second_river', if: { happened: 'second_war', year: [75, 79], region: ['central', 'jingchu'], age: [16, 120] }, art: 'river', title: 'The river crossings',
    text: 'The Second War comes down to the river crossings, as the first one did. Cult rafts in the mist, an Alliance line on the bank, and a Cult river captain poling straight for the gap beside you.',
    foe: { name: 'a Cult river captain', kind: 'cultist', rel: 0.5 }, lethal: 0.3,
    fight: ['Wade out to meet his raft', 'You waded out into the cold to meet the raft.'],
    win: { text: 'The raft spun away downstream without its captain. The line held, and someone younger than you will tell the story wrong for years.', fame: 6, rep: { orthodox: 6 } },
    lose: { text: 'His pole caught you in the chest and the river did the rest. You came out a li downstream, alive and furious.', health: -10 },
    alt: ['Cut the rafts’ guide rope', 'body', 38, O('You swam out under the mist and cut the rope the rafts were hauling on. Half of them went downstream and out of the war.', { fame: 5, rep: { orthodox: 5 }, body: 1 }), O('The cold took your strength halfway out. You barely got back.', { health: -8 })],
    help: ['Keep the signal fires burning', O('You kept the signal fires alight in the rain all night so the line could see the rafts coming. It was dull and it mattered.', { sanity: 2, insight: 1 })],
    leave: ['Let the young ones hold the line', O('You let the young ones hold it. They held it. You were proud, and a little hurt.', { sanity: 1 })] },
], (r) => E('wr_battle', 'war', { if: r.if, w: r.w || 1, danger: true, art: r.art, title: r.title, text: r.text, choices: [
  C(r.fight[0], O(r.fight[1], { flag: 'wr.fought', combat: { foe: r.foe, context: 'war', lethal: r.lethal, win: r.win, lose: r.lose } })),
  R(r.alt[0], r.alt[1], r.alt[2], r.alt[3], r.alt[4]),
  C(r.help[0], r.help[1]),
  C(r.leave[0], r.leave[1]),
] }));

// Sieges, one per city: life inside the walls.
const tplSiege = template('wr_siege', [
  { key: 'wuchang', if: { happened: 'grain_fleet', year: [13, 16], loc: 'wuchang', age: [10, 80] }, title: 'The blockade', art: 'river',
    text: 'The Water Fortress has closed the Great River below Wuchang until the court pays for its insult. No rice boats come up. The fishmongers are selling carp heads at the price of carp.',
    share: ['Cook rice in the lane for whoever comes', O('You cooked a pot of rice in the lane and fed whoever came. Whoever came was a great many people.', { wealth: -3, sanity: 4, charm: 1 })],
    sneak: ['Slip a rice skiff past the Fortress chain', 'body', 30, O('You poled a skiff of rice past the chain under a moonless sky and sold it on the quay at dawn for a small fortune.', { wealth: 18, rep: { unorthodox: -2 } }), O('A Fortress lookout put one arrow through your hat and another through the hull. You swam home.', { health: -6, wealth: -4 })],
    buy: ['Pay the Fortress toll for a boat (15 taels)', { wealth: '>=15' }, O('You paid the pirates’ toll. A boat came up with rice and a receipt bearing the Water Fortress seal. You kept the receipt as a souvenir of something.', { wealth: -15, rep: { unorthodox: 4 }, sanity: 2 })],
    wall: ['Help the magistrate ration the granary', O('You stood at the granary door with a scoop and a list for a whole season. The list was always wrong and the scoop was always too small.', { insight: 1, rep: { court: 3 } })] },
  { key: 'dangclan', if: { happened: 'dang_civil_war', year: [26, 27], loc: 'dangclan', age: [10, 80] }, title: 'Sealed in', art: 'estate',
    text: 'The Dang manor’s inner walls are sealed, and you are on the wrong side of two of them. Every well is suspect. The cook tastes everything first, and the cook is getting thinner.',
    share: ['Share your water skin with the cook', O('You shared your water with the cook. He wept, quietly, and from then on your bowl was always the fullest.', { sanity: 3, health: 2 })],
    sneak: ['Test the wells with a silver pin', 'insight', 30, O('Three wells blackened the silver. The fourth did not. You told the kitchen, and the kitchen told everyone, and for once the Dang were grateful in public.', { rep: { families: 5 }, insight: 2 }), O('The pin stayed bright and the water was not clean. A day of cramps taught you the Dang know poisons that silver does not.', { health: -10 })],
    buy: ['Buy an antidote from a loyalist (10 taels)', { wealth: '>=10' }, O('A small green pill in a twist of paper. You did not need it in the end, which in the Dang manor is the best use of money there is.', { wealth: -10, sanity: 3, cure: 'poison' })],
    wall: ['Stand watch at the inner gate', O('You stood watch at the inner gate for a season with a lantern and a stick. Nobody tried the gate. Somebody tried the wall beside it, twice.', { rep: { families: 3 }, body: 1 })] },
  { key: 'jadegate', if: { happened: 'blood_demon_throne', year: [31, 33], loc: 'jadegate', age: [10, 80] }, title: 'The last gate', art: 'desert',
    text: 'Cult outriders circle the Jade Gate Pass like gulls. Three caravans are trapped inside the fort, the well is low, and the camels are drinking more than the men.',
    share: ['Give your water ration to the caravan children', O('You went thirsty for a week. The caravan children did not. One of them drew you a camel in the sand every morning as payment.', { health: -4, sanity: 6 })],
    sneak: ['Lead a caravan out by the old smugglers’ wash', 'insight', 35, O('A dry riverbed, no moon, and camels with their bells stuffed with wool. Twenty li from the gate the caravan master paid you in silk and swore you were a desert ghost.', { wealth: 20, rep: { merchants: 5 } }), O('The wash ran out into open sand in sight of the outriders. You turned back with the caravan intact and your nerves in pieces.', { sanity: -4 })],
    buy: ['Buy a fast camel and leave (30 taels)', { wealth: '>=30' }, O('You bought the fastest camel in the fort and rode east at night. The outriders chased you for half a day out of professional interest.', { wealth: -30, travel: 'changan' })],
    wall: ['Keep the beacon fire fed', O('You hauled dung cakes up the beacon tower every night so the fire would be ready. It was never lit while you were there. You smelled of it for a month.', { body: 1, rep: { court: 2 } })] },
  { key: 'changan', if: { happened: 'kongtong_falls', year: [35, 38], loc: 'changan', age: [8, 80] }, title: 'Chang’an besieged', art: 'city',
    text: 'Chang’an is besieged. The markets sell rat on skewers and call it squab. Refugees sleep in the temple courtyards, and the Alliance commander has requisitioned every wine-house, which is more than anyone can forgive.',
    share: ['Take a refugee family into your lodging', O('A mother, two boys and a grandfather who snored. Your room was very small for a season and much less lonely.', { sanity: 5, wealth: -4 })],
    sneak: ['Carry letters out through the old drains', 'body', 30, O('You crawled out under the west wall with a satchel of letters and came back a week later with answers. Mothers and wives came looking for you after that.', { fame: 4, rep: { orthodox: 3 } }), O('The drain was flooded. You came back without the satchel and with a fever.', { health: -10 })],
    buy: ['Buy black-market rice (20 taels)', { wealth: '>=20' }, O('Twenty taels for a sack of rice that was mostly rice. You ate, and shared, and did not ask the seller where he got it.', { wealth: -20, health: 6, sanity: 2 })],
    wall: ['Carry stones to the west wall', O('You carried stones to the west wall until your shoulders were raw. The wall held. You like to think one of the stones was yours.', { body: 2, rep: { orthodox: 2 } })] },
  { key: 'songshan', if: { happened: 'cult_war', year: [35, 36], loc: 'songshan', age: [8, 80] }, title: 'Inside Shaolin', art: 'temple',
    text: 'The Cult has closed the roads around Mount Song, and you are inside the temple with five hundred monks, two hundred refugees and one very old cook who is making the rice last by sheer force of will.',
    share: ['Give your rations to the novices', O('You gave your bowl to the novices for a month. A monk noticed, and the next week your bowl came back full, with a pickled radish on top.', { health: -4, sanity: 6, rep: { orthodox: 3 } })],
    sneak: ['Fetch water from the spring below the walls', 'body', 35, O('Down the cliff path at night with two buckets on a pole, and back up before the Cult sentries changed. The cook gave you a nod. In Shaolin, that is a medal.', { body: 2, rep: { orthodox: 4 } }), O('A sentry saw you. You dropped the buckets and climbed for your life.', { health: -6 })],
    buy: ['Donate to the temple kitchen (10 taels)', { wealth: '>=10' }, O('The cook took your silver, looked at it, and said, "We cannot eat this." Then he bought rice with it from a smuggler at the back gate.', { wealth: -10, rep: { orthodox: 5 } })],
    wall: ['Sit in the hall and chant with the monks', O('You sat in the hall and chanted with the monks while the drums beat outside. Somewhere in the second hour your fear went quiet and your qi did not.', { qi: 10, sanity: 3 })] },
  { key: 'wudang', if: { happened: 'cult_war', year: [36, 37], loc: 'wudang', age: [8, 80] }, title: 'Fog on the peaks', art: 'temple',
    text: 'The Cult holds the roads below Wudang and the fog holds everything else. Up on the peaks, the Daoists ration rice by the grain and tea by the leaf, and argue philosophy to keep warm.',
    share: ['Share your blanket with the wounded', O('You gave your blanket to a wounded disciple and slept in your coat. She returned it in spring, washed and mended, with a pine sprig folded inside.', { health: -3, sanity: 5 })],
    sneak: ['Climb down the cliff path for medicinal herbs', 'body', 38, O('A day down, a day up, and a satchel of herbs the Daoists turned into salve. You kept a jar.', { item: { healing_salve: 1 }, rep: { orthodox: 4 } }), O('The cliff path was icy. You came down it faster than you meant to.', { health: -10 })],
    buy: ['Buy rice from a hermit who hoarded it (8 taels)', { wealth: '>=8' }, O('The hermit sold you rice and lectured you on the vanity of hoarding while he did it. He saw no contradiction.', { wealth: -8, health: 4 })],
    wall: ['Practise the Taiji with the disciples at dawn', O('Every dawn in the fog, a hundred people turning slowly in silence. You did not get warmer, but you got steadier.', { insight: 2, qi: 8 })] },
  { key: 'namgung', if: { happened: 'cult_war', year: [37, 38], loc: 'namgung', age: [8, 80] }, title: 'The Estate under siege', art: 'estate',
    text: 'The Namgung Estate is besieged, and the Namgung are holding banquets anyway, because to stop would be to admit something. The servants’ table, two courtyards away, is eating millet.',
    share: ['Carry your banquet plate to the servants’ table', O('You walked your plate two courtyards and set it down among the servants. The steward was scandalised. The servants were not.', { sanity: 4, rep: { families: -2 }, charm: 1 })],
    sneak: ['Carry a message through the lines to Hangzhou', 'body', 40, O('Through the paddies at night, nine days to Hangzhou and nine back. The reinforcements were too few and too late, but they were not nothing.', { fame: 4, rep: { families: 6 } }), O('A Cult patrol caught you in the paddies. You fought free and crawled back to the Estate.', { health: -10 })],
    buy: ['Bribe the steward for a servant’s pass out (40 taels)', { wealth: '>=40' }, O('Forty taels bought you a servant’s jacket and a place on the night boat to Hangzhou. The steward did not look at you as he took it.', { wealth: -40, travel: 'hangzhou', sanity: -2 })],
    wall: ['Stand the walls with the retainers', O('You stood the walls with the old retainers, who told you about every siege the Estate had ever survived. There had been eleven. They did not mention the ones it had not.', { body: 1, rep: { families: 4 } })] },
  { key: 'luoyang', if: { happened: 'alliance_betrayal', year: [39, 41], loc: 'luoyang', age: [8, 80] }, title: 'A city without a leader', art: 'city',
    text: 'The Alliance Leader has fled, the Alliance hall is shouting itself hoarse, and the Cult is two days from the walls. Luoyang has stopped believing anyone in charge, and started hoarding.',
    share: ['Share bread with the Beggars’ children', O('You broke bread under the bridges with a dozen children who ate like wolves and thanked you like courtiers. Hong Chil watched from the shadows and did not interfere.', { sanity: 4, rep: { orthodox: 2 } })],
    sneak: ['Find out who is selling the city’s grain', 'insight', 35, O('You followed the ox-carts at night to a warehouse with a Zhongnan seal on the door. The Alliance granary had been half empty for years.', { codex: LEDGER, insight: 2 }), O('The carters noticed you following. You spent a night hiding in a dye vat.', { health: -3 })],
    buy: ['Buy a place on a boat south (25 taels)', { wealth: '>=25' }, O('Twenty-five taels for a plank to sit on and a boatman who sang. You were in Wuchang before the Cult reached the walls.', { wealth: -25, travel: 'wuchang' })],
    wall: ['Join the Beggars on the bridges', O('You stood with the Beggars on the bridges through three alarms. Nothing came over them. You felt the city breathe out each time.', { rep: { orthodox: 4 }, fame: 1 })] },
  { key: 'kaifeng', if: { happened: 'depot_army', year: [40, 42], loc: 'kaifeng', age: [8, 80] }, title: 'Martial law', art: 'city',
    text: 'The Eastern Depot has quartered its army in Kaifeng and declared martial law. The Ghost Market is shut, the gambling dens are shut, and the Depot’s officers are walking the canals asking anyone with calluses what sect they belong to.',
    share: ['Hide a wanted swordsman in your room', O('A Qingcheng disciple with a Depot warrant slept under your bed for a week. He left a jade button on your pillow as thanks.', { rep: { orthodox: 4, court: -3 }, item: { jade_pendant: 1 } })],
    sneak: ['Reopen the Ghost Market’s tunnels', 'insight', 30, O('You found the old tunnel under the pawnshop and the Ghost Market opened again, underground, for a very select clientele who paid you a percentage.', { wealth: 20, infamy: 3 }), O('A Depot patrol found the tunnel the same night. You got out. The pawnbroker did not.', { sanity: -6 })],
    buy: ['Pay for a Depot travel permit (12 taels)', { wealth: '>=12' }, O('Twelve taels for a square of stamped paper that let you walk out of the gate like an honest citizen. You felt very dishonest.', { wealth: -12, rep: { court: 2 } })],
    wall: ['Keep your head down and your sword wrapped', O('You kept your head down and your sword in a roll of bedding. The Depot officers walked past you twice. The third time they stopped, looked, and walked on.', { sanity: -2 })] },
  { key: 'capital', if: { flag: 'w.registry', year: [58, 60], loc: 'capital', age: [8, 100] }, title: 'The locked city', art: 'palace',
    text: 'The Imperial Capital is locked down: Depot patrols at every crossing, registry tags checked at every gate, and a rumour in every teahouse that the Director wants more than the Registry.',
    share: ['Hide an untagged swordswoman in your attic', O('An Emei nun with no tag hid in your attic for a month and repaired every piece of clothing you owned. She left by night with a nod.', { rep: { orthodox: 5, court: -4 }, sanity: 3 })],
    sneak: ['Carry a message to the Imperial Guard', 'charm', 35, O('You walked into the Guard barracks with a basket of pears and a message under the pears. Commander Han Gyeong read it, ate a pear, and remembered your face.', { rel: { '@guard_commander': { res: 15 } }, fame: 2 }), O('A Depot officer bought a pear from your basket, and then another, and then took the basket.', { rep: { court: -3 }, sanity: -3 })],
    buy: ['Buy a forged registry tag (30 taels)', { wealth: '>=30' }, O('A very good forgery, in pine instead of cypress. Nobody checked the wood.', { wealth: -30, flag: 'wr.registry_done', unflag: 'wr.outlaw' })],
    wall: ['Stay indoors and listen', O('You stayed indoors and listened to boots in the street every night. You learned the patrols by their footsteps, which is a strange thing to know.', { insight: 1, sanity: -2 })] },
  { key: 'chengdu', if: { happened: 'second_war', year: [75, 79], loc: 'chengdu', age: [8, 120] }, title: 'Shu cut off', art: 'city',
    text: 'The Second War has cut Shu off from the rest of the empire. Chengdu has pepper and brocade enough to drown in, and no salt at all. Food tastes of nothing, and tempers taste of pepper.',
    share: ['Share your last salt with the neighbours', O('A pinch each, on a festival day. The neighbours talked about it for a year, as if you had shared gold.', { sanity: 4, charm: 1 })],
    sneak: ['Bring salt over the plank roads', 'body', 35, O('Up the plank roads on a cliff face with a sack of salt on your back, and down again. The salt sold at the price of silver. Some you gave away.', { wealth: 15, body: 1, fame: 1 }), O('A plank broke. You held on. The salt did not.', { health: -8, wealth: -5 })],
    buy: ['Buy salt from a profiteer (15 taels)', { wealth: '>=15' }, O('Fifteen taels for a jar of salt that was a third sand. You were too tired of tasteless rice to complain.', { wealth: -15, sanity: 2 })],
    wall: ['Drill with the city militia', O('Old men and children drilling with bamboo spears in the square. You corrected their stances. They corrected your temper.', { body: 1, fame: 1 })] },
], (r) => E('wr_siege', 'war', { if: r.if, art: r.art, title: r.title, text: r.text, choices: [
  C(r.share[0], r.share[1]),
  R(r.sneak[0], r.sneak[1], r.sneak[2], r.sneak[3], r.sneak[4]),
  Q(r.buy[0], r.buy[1], r.buy[2]),
  C(r.wall[0], r.wall[1]),
] }));

// Refugees, one per region and war.
const tplRefugees = template('wr_refugees', [
  { key: 'guanzhong', if: { happened: 'kongtong_falls', year: [35, 38], region: 'guanzhong', age: [12, 90] }, art: 'road',
    text: 'Refugees from the western valleys on the Chang’an road: Kongtong farmers, Mount Hua tenant families, a cart of nuns. An old Kongtong porter is telling anyone who will listen how the mountain fell.',
    feed: ['Buy them a cartload of buns (6 taels)', { wealth: '>=6' }, O('The baker could not believe his luck. The refugees could not believe theirs. The nuns blessed you, the farmers thanked you, and the buns lasted about as long as a sneeze.', { wealth: -6, sanity: 4, fame: 1 })],
    guide: ['Find them a camp with water', 'insight', 25, O('A stream, a stand of willows, a field the Alliance had not burned. By evening there were cookfires, and a child singing.', { sanity: 4, fame: 2 }), O('The camp you found was already full. You kept walking with them until dark.', { sanity: -2 })],
    take: ['Listen to the porter', O('"Up the dry gully," he said, "behind the north gate, in the dust storm, when nobody could see his own hand. We had goats up there forty years and never thought."', { codex: KONGTONG_GULLY, insight: 1 })],
    pass: ['Sell them water at the well', O('Two coppers a dipper. You made a tael and lost something harder to count.', { wealth: 1, infamy: 2, sanity: -4 })] },
  { key: 'central', if: { happened: 'siege_song', year: [36, 41], region: 'central', age: [12, 90] }, art: 'city',
    text: 'A camp of ten thousand outside Luoyang’s walls: people from Mount Song, from the western road, from villages that are now only names. The city gate opens at noon for one hour, and the guards choose who goes in.',
    feed: ['Pay for a soup kitchen for a week (15 taels)', { wealth: '>=15' }, O('A borrowed cauldron, a hired cook and fifteen taels of millet. For a week, a line of people ate every morning. Then the money ran out, and the line did not.', { wealth: -15, fame: 4, sanity: 3 })],
    guide: ['Talk the gate captain into opening the gate longer', 'charm', 30, O('You talked, and bribed a little, and shamed a lot. The gate stayed open three hours that day. The captain said never again. He said it every day for a month.', { fame: 4, sanity: 3 }), O('The captain shut the gate on your foot.', { health: -3 })],
    take: ['Take a family in under your own roof (10 taels)', O('A grandmother, a mother, a boy who did not speak. They stayed a season. When they left, the boy said goodbye.', { wealth: -10, sanity: 6 }), { wealth: '>=10' }],
    pass: ['Push through to the gate yourself', O('You pushed through to the gate and went in. A woman with a baby did not. You heard her for a long time.', { sanity: -6 })] },
  { key: 'jingchu', if: { happened: 'wudang_holds', year: [37, 40], region: 'jingchu', age: [12, 90] }, art: 'river',
    text: 'Every boat on the Han River is full of people fleeing south from the fighting around Wudang, and every boatman has tripled his price. On the bank, a family with five children and no silver is watching the boats go.',
    feed: ['Pay their passage (12 taels)', { wealth: '>=12' }, O('Twelve taels, and the boatman made room as if it had been his own idea. The smallest child waved at you all the way downstream.', { wealth: -12, sanity: 6 })],
    guide: ['Pilot a leaking boat down the rapids yourself', 'body', 35, O('A borrowed boat, five children bailing, and you on the pole. You reached Wuchang soaked, and so did everyone in the boat.', { body: 2, fame: 3, sanity: 4 }), O('The boat went over in the second rapid. Everyone reached the bank. Not everything did.', { health: -6, sanity: -3 })],
    take: ['Shame the boatmen into a fair price', O('You stood on the quay and read out each boatman’s price in a loud voice, with his name. Prices came down. Some boatmen will not carry you to this day.', { fame: 2, rep: { merchants: -2 } })],
    pass: ['Take the last seat on a boat yourself', O('You took the last seat. The family watched you go.', { sanity: -5 })] },
  { key: 'shu', if: { happened: 'dang_civil_war', year: [26, 28], region: 'shu', age: [12, 90] }, art: 'forest',
    text: 'Servants of the Dang manor are walking the road to Chengdu in a long line: cooks, gardeners, maids, a man who only ever trimmed the poison hedges. Nobody in Shu will hire anyone who has worked for the Dang.',
    feed: ['Buy them a meal at a roadside inn (5 taels)', { wealth: '>=5' }, O('The innkeeper served them nervously, as if they might poison the soup. They did not. They did ask for extra pepper.', { wealth: -5, sanity: 3 })],
    guide: ['Vouch for them to a Chengdu guild', 'charm', 30, O('You talked a brocade guild into hiring a dozen of them. Within a year, the guild had the most beautiful gardens in Chengdu and no rats at all.', { rep: { merchants: 4 }, fame: 2 }), O('The guild master asked if you would vouch with your life. You hesitated, and that was that.', { sanity: -2 })],
    take: ['Hire the hedge-trimmer to teach you what he knows', O('He taught you every plant on the road that could kill you and three that could save you. He would not take payment. "Nobody ever asked," he said.', { insight: 2, item: { healing_salve: 1 } })],
    pass: ['Keep your distance like everyone else', O('You kept your distance, like everyone else. In Shu, a Dang servant is a rumour with legs.')] },
  { key: 'jiangnan', if: { happened: 'namgung_burns', year: [38, 41], region: 'jiangnan', age: [12, 90] }, art: 'lake',
    text: 'Namgung retainers and servants have come to Hangzhou with nothing but their surname. They are too proud to beg, which means they are mostly starving very politely by West Lake.',
    feed: ['Leave food at their door without a word (8 taels)', { wealth: '>=8' }, O('Every morning for a month you left rice at the door of the house they had rented. Nobody ever saw you. Everybody knew.', { wealth: -8, rep: { families: 5 }, sanity: 3 })],
    guide: ['Find them honourable work', 'insight', 30, O('A tea merchant needed guards who could read, and a school needed a sword teacher who could not be insulted. Pride, you discovered, is employable.', { rep: { families: 6, merchants: 2 } }), O('Every job you found was beneath a Namgung, they told you, with dignity.', { sanity: -2 })],
    take: ['Offer the old retainer a place in your house', O('He accepted with a bow so low it creaked, and ran your house for years with a terrifying efficiency.', { rep: { families: 3 }, sanity: 4, wealth: -5 })],
    pass: ['Let pride feed them', O('You let pride feed them. It did not, much.', { sanity: -3 })] },
  { key: 'hebei', if: { happened: 'hebei_drought', year: [46, 50], region: 'hebei', age: [12, 90] }, art: 'road',
    text: 'The drought has emptied Hebei’s villages onto the roads. Half the young men have gone to the Green Forest; the rest are pulling carts of grandparents toward the capital, where they have heard there is grain.',
    feed: ['Hand out millet from a cart (10 taels)', { wealth: '>=10' }, O('A cart of millet went in an hour. A grandfather insisted on paying you with his last copper. You let him, so he could keep his face.', { wealth: -10, sanity: 4, fame: 2 })],
    guide: ['Show them the well the drought has not reached', 'insight', 30, O('An old monastery well in the hills, still sweet. A village moved there, the whole village, and stayed.', { sanity: 5, fame: 3 }), O('The well was dry too. You walked back down with them in silence.', { sanity: -4 })],
    take: ['Talk a boy out of joining the Green Forest', O('You talked to him all evening about what bandits eat in winter. He went to the capital with his family instead. You will never know if you were right.', { sanity: 2, rep: { unorthodox: -1 } })],
    pass: ['Hurry past', O('You hurried past with your own provisions on your back. Nobody stopped you. That was worse.', { sanity: -4 })] },
  { key: 'liaodong', if: { happened: 'registry_edict', year: [55, 61], region: 'liaodong', age: [12, 90] }, art: 'snow',
    text: 'Martial families fleeing the Registry have come north to Liaodong, hoping the Moyong will shelter them. The Moyong have closed their gates with exquisite courtesy. Children are sleeping in the snow under the Moyong wall.',
    feed: ['Buy them furs and firewood (20 taels)', { wealth: '>=20' }, O('Twenty taels of furs and firewood, and a camp under the wall that survived the winter. A Kunlun exile gave you a bow of thanks that was very nearly Moyong in its coldness.', { wealth: -20, sanity: 5, fame: 3 })],
    guide: ['Ask the Moyong to open their gates', 'charm', 40, O('You argued courtesy with the Moyong, which is like arguing water with the sea. Somehow you won. The gates opened, a little, for the children.', { rel: { '@moyong_baek': { res: 15 } }, rep: { families: 4 }, fame: 4 }), O('Moyong Baek thanked you for your interesting perspective and closed the gate himself.', { rel: { '@moyong_baek': { aff: -5 } } })],
    take: ['Lead a family on to the coast and a boat', O('Six days to the coast, a fisherman with a boat and no questions. They went over the sea to somewhere the Depot does not reach.', { sanity: 4, rep: { court: -3 } })],
    pass: ['Report them to the Depot post', O('The Depot post paid a bounty per head. You did not count the heads. You counted the silver.', { wealth: 15, infamy: 6, sanity: -10, rep: { court: 4 } })] },
  { key: 'west', if: { happened: 'cult_coup', year: [29, 31], region: 'west', age: [12, 90] }, art: 'desert',
    text: 'The Blood Faction is purging the Young Heavenly Demon’s loyalists, and their families are walking out of the Ten Thousand Mountains toward the Jade Gate. A loyalist officer, out of uniform, is carrying two children.',
    feed: ['Share your water and dried meat (4 taels)', { wealth: '>=4' }, O('You shared what you had. The officer watched you feed his children and did not say a word, but he wrote your name on the inside of his sleeve.', { wealth: -4, sanity: 4, rep: { cult: 2 } })],
    guide: ['Talk them past the Jade Gate garrison', 'charm', 30, O('A family of salt traders, you told the garrison, and very sick. The garrison stepped back. The officer’s children played sick very convincingly.', { sanity: 4, fame: 1 }), O('The garrison turned them back. They went north, toward worse roads.', { sanity: -5 })],
    take: ['Ask the officer what the Blood Demon is planning', O('"Granaries," he said. "Three, outside the Jade Gate. He fills them this winter and next. When they are full, he marches." He looked at you. "Burn them, if anyone can."', { codex: GRANARIES })],
    pass: ['Turn them over to the Blood Faction riders', O('The riders paid you and took them. The officer did not fight. He only looked at you.', { wealth: 12, infamy: 6, sanity: -12, rep: { cult: 4 } })] },
  { key: 'second', if: { happened: 'second_war', year: [74, 79], region: ['central', 'guanzhong'], age: [12, 120] }, art: 'road',
    text: 'Refugees again on the western roads, a generation after the last ones. Some of the grandmothers in the carts were children in carts the first time. One of them recognises the road and starts to laugh.',
    feed: ['Feed the cart with the laughing grandmother (5 taels)', { wealth: '>=5' }, O('She ate, and told you about the first war, and you told her about yours, and you found you had been in the same camp outside Luoyang forty years ago.', { wealth: -5, sanity: 6 })],
    guide: ['Show them the camp you remember', 'insight', 25, O('The stream was still there, and the willows. You put the first cookfire exactly where it had been last time.', { sanity: 5, fame: 2 }), O('The stream had moved. So had everything.', { sanity: -3 })],
    take: ['Carry a child on your shoulders for a while', O('Your shoulders are older than they were. The child did not mind, and neither did you.', { sanity: 4, health: -2 })],
    pass: ['Go home and bar the door', O('You went home and barred the door. You have done this before. It does not get easier.', { sanity: -4 })] },
], (r) => E('wr_refugees', 'war', { if: r.if, art: r.art, title: 'Refugees', text: r.text, choices: [
  Q(r.feed[0], r.feed[1], r.feed[2]),
  R(r.guide[0], r.guide[1], r.guide[2], r.guide[3], r.guide[4]),
  C(r.take[0], r.take[1], r.take[2] ? { req: r.take[2] } : {}),
  C(r.pass[0], r.pass[1]),
] }));

// Levies and conscription, one per faction that does the calling.
const tplLevy = template('wr_levy', [
  { key: 'father', if: { year: [6, 13], age: [5, 12], has: 'father', origin: ['peasant', 'merchant', 'official'] }, bind: { x: 'father' }, art: 'road', title: 'The levy',
    text: 'The magistrate’s men are at the door with a list. The regency needs men for the northern wall, one from each household, and {x}’s name is on it.',
    answer: ['Say goodbye properly', O('You held on to {x}’s sleeve at the gate until {x.he} gently took it back. "Three years," {x.he} said. "Look after the house."', { sanity: -4, rel: { x: { aff: 10 } }, next: { id: 'wr_father_returns', in: 12 } })],
    dodge: ['Hide {x.him} in the rice store', 'insight', 25, O('The men searched the house and missed the rice store. The magistrate fined the household instead. {x} looked at you differently after that, as if you were older.', { wealth: -3, rel: { x: { aff: 15, res: 15 } } }), O('They found {x.him} in the rice. {x.He} went anyway, and the household was fined for hiding {x.him}.', { wealth: -4, sanity: -4, next: { id: 'wr_father_returns', in: 12 } })],
    bribe: ['Give the clerk the family savings', { wealth: '>=8' }, O('The clerk crossed out the name. The neighbour’s son went instead. You saw his mother at the well every day after that.', { wealth: -8, sanity: -3 })],
    other: ['Offer to go in {x.his} place', O('The magistrate’s men laughed until they cried. One of them gave you a sweet. {x} went anyway, but {x.he} was smiling.', { charm: 1, rel: { x: { aff: 10 } }, next: { id: 'wr_father_returns', in: 12 } })] },
  { key: 'court', if: { happened: 'grain_fleet', year: [14, 18], region: ['jingchu', 'central'], age: [15, 45], not: 'wr.levied' }, art: 'city', title: 'The emperor’s levy',
    text: 'The court is raising a levy of boatmen and spearmen for its vengeance on the Water Fortress. The recruiting officer has a drum, a list, and a sergeant who does not look at faces.',
    answer: ['Take the signing coin', O('You took the coin and the spear. The drilling was dull, the food was worse, and you learned to sleep standing up.', { flag: 'wr.levied', wealth: 5, body: 2, rep: { court: 4 } })],
    dodge: ['Look too sick to march', 'charm', 25, O('A cough, a limp and a description of your bowels so vivid the sergeant waved you away in disgust.', { flag: 'wr.levied', charm: 1 }), O('The sergeant had heard that cough before.', { flag: 'wr.levied', body: 1, rep: { court: 1 } })],
    bribe: ['Pay the officer (10 taels)', { wealth: '>=10' }, O('Ten taels, and your name was spelled wrong in a way that made it someone else’s.', { flag: 'wr.levied', wealth: -10 })],
    other: ['Volunteer as a boat-pilot instead', O('Pilots stayed at the back and were paid double. You learned every channel of the Great River and none of the war.', { flag: 'wr.levied', wealth: 8, insight: 1 })] },
  { key: 'alliance', if: { flag: 'w.war', faction: 'orthodox', rank: [0, 2], age: [15, 60], not: 'wr.enlisted' }, art: 'temple', title: 'The sect’s quota',
    text: 'The Alliance wants more disciples at the front, and {sect} has to send its quota. The elders are drawing names from a bowl, which they say is fair, and which they have certainly arranged.',
    answer: ['Step forward before your name is drawn', O('The yard went quiet. An elder wrote your name down first, very carefully, as if it might be the last time.', { flag: 'wr.enlisted', merit: 10, fame: 2 })],
    dodge: ['Argue you are needed at the sect', 'charm', 30, O('Somebody has to guard the scripture hall and teach the novices, you argued. The elders agreed, and sent your friend instead.', { merit: -2, sanity: -3 }), O('The elders agreed you were needed at the front.', { flag: 'wr.enlisted', merit: 4 })],
    bribe: ['Hire a mercenary to go under your name (40 taels)', { wealth: '>=40' }, O('A mercenary with your sect badge marched west. You never learned if he came back. You never asked.', { wealth: -40, merit: -5, infamy: 2 })],
    other: ['Volunteer for the healers instead', O('The healers were always short. Nobody objected.', { flag: ['wr.enlisted', 'wr.post_healer'], merit: 6 })] },
  { key: 'families', if: { or: [{ flag: 'wr.feud_war' }, { flag: 'w.war' }], faction: 'families', age: [15, 60], not: 'wr.enlisted' }, art: 'estate', title: 'The family calls',
    text: 'The family elders have called every kinsman of fighting age to the ancestral hall. There is incense, a speech about blood, and a list with your name on it, already written.',
    answer: ['Kneel to the ancestors and take up your sword', O('You knelt, and the elders bound the family colours on your arm. It felt heavier than the sword.', { flag: 'wr.enlisted', rep: { families: 6 }, merit: 8 })],
    dodge: ['Plead a sick parent', 'charm', 25, O('Filial piety outranks most things in a family hall. The elders let you stay. Your cousins did not speak to you for a year.', { rep: { families: -2 }, sanity: -2 }), O('"The ancestors also had parents," said the eldest, and your name stayed on the list.', { flag: 'wr.enlisted', rep: { families: 2 } })],
    bribe: ['Pay a retainer to go in your stead (30 taels)', { wealth: '>=30' }, O('A retainer with a wife and three children took your silver and your place. He came back. That was luck, not virtue.', { wealth: -30, rep: { families: -3 } })],
    other: ['Offer to keep the war accounts instead', O('The family steward was delighted. You spent the war counting sabers and dead men’s pensions.', { flag: 'wr.post_supply', insight: 2, merit: 4 })] },
  { key: 'unorthodox', if: { or: [{ flag: 'w.war' }, { happened: 'hebei_drought' }], faction: 'unorthodox', year: [34, 50], age: [15, 60], not: 'wr.enlisted' }, art: 'forest', title: 'The brotherhood calls',
    text: 'A runner from the stronghold with a red arrow: the brotherhood is calling in every sworn brother and sister. Nobody has ever refused a red arrow and kept both hands.',
    answer: ['Break the arrow and ride', O('You broke the arrow across your knee and rode. The brotherhood remembers who comes when called.', { flag: 'wr.enlisted', rep: { unorthodox: 6 }, infamy: 2 })],
    dodge: ['Send the runner back with a convincing excuse', 'insight', 35, O('A sick mother, a broken leg, and a promise of silver in lieu. The stronghold accepted the silver.', { wealth: -5, rep: { unorthodox: -1 } }), O('The runner did not believe you. Neither did the two men who came after him.', { flag: 'wr.enlisted', health: -6 })],
    bribe: ['Pay the stronghold a hundred arrows’ worth (25 taels)', { wealth: '>=25' }, O('Silver speaks the brotherhood’s language fluently. Your name went to the bottom of the list.', { wealth: -25 })],
    other: ['Bring three new recruits instead of yourself', O('Three hungry farmers, very glad of the meal. The stronghold took them and asked no questions about you.', { infamy: 3, sanity: -3, rep: { unorthodox: 4 } })] },
  { key: 'cult', if: { flag: 'w.war_coming', sect: 'cult', age: [14, 60], not: 'wr.cult_vanguard' }, art: 'demonic', title: 'The Shadow Hall’s list',
    text: 'The Shadow Hall’s recruiters are going hall to hall with a list of believers who have not yet volunteered for the march east. Their master, {@shadow_master}, is said to read the list personally.',
    answer: ['Volunteer before they reach your door', O('You volunteered before they reached your door. The recruiter made a small mark beside your name that might have been approval.', { flag: 'wr.cult_vanguard', rep: { cult: 5 }, merit: 6 })],
    dodge: ['Get yourself posted to the herb gardens', 'insight', 35, O('The herb gardens needed someone who could tell wolfsbane from parsley. You could. The march went east without you.', { rep: { cult: -1 }, insight: 1 }), O('The herb master did not need anyone. The recruiter did.', { flag: 'wr.cult_vanguard', sanity: -3 })],
    bribe: ['Give the recruiter your savings', { wealth: '>=20' }, O('The recruiter took your silver and your name off the list, and added it to a different list, of people who pay.', { wealth: -20, flag: 'cult.suspect' })],
    other: ['Ask to be a runner for the healers', O('Runners carried messages and bandages and did not carry spears. The recruiter shrugged and wrote it down.', { flag: 'wr.post_healer', merit: 3 })] },
  { key: 'merchants', if: { flag: 'w.war', or: [{ faction: 'merchants' }, { career: ['escort', 'merchant'] }], age: [16, 65] }, art: 'market', title: 'The guild’s war levy',
    text: 'The Golden Abacus Guild has announced a war levy: every member must provide either a man for the guild militia or a war tax of thirty taels. The guild master calls this patriotism, and has bought the militia’s supply contract.',
    answer: ['Join the guild militia', O('You marched with clerks and shop boys behind a banner with an abacus on it. You guarded supply wagons and were, by the end, rather good at it.', { rep: { merchants: 5 }, body: 2, careerUp: 2 })],
    dodge: ['Find a loophole in the levy', 'insight', 30, O('Members in the medicine trade were exempt. You were, by the end of the week, in the medicine trade.', { rep: { merchants: -1 }, insight: 1 }), O('The guild’s lawyers found your loophole first and closed it.', { wealth: -10 })],
    bribe: ['Pay the war tax (30 taels)', { wealth: '>=30' }, O('You paid the thirty taels and got a very fine certificate of patriotism. You hung it in the shop. It did not bring in customers.', { wealth: -30, rep: { merchants: 3 } })],
    other: ['Pay a porter to march for you (15 taels)', O('A porter took your fifteen taels and your place in the militia, and came back with a limp and a story.', { wealth: -15, sanity: -2 }), { wealth: '>=15' }] },
  { key: 'depot', if: { happened: 'registry_edict', flag: 'wr.registry_done', not: 'wr.outlaw', realm: '>=1', age: [16, 60] }, art: 'palace', title: 'The Pacification Corps',
    text: 'Your registry tag has a new mark on it. Registered martial artists of your realm are to report to the Eastern Depot’s Murim Pacification Corps, to "assist in the registration of others".',
    answer: ['Report for duty', O('You spent a season escorting Depot clerks to sect gates and watching sects decide whether to open them. Most did. You hated the ones that did not, and the ones that did.', { rep: { court: 8, orthodox: -6 }, sanity: -8, wealth: 10 })],
    dodge: ['Have a physician certify you crippled', 'charm', 35, O('A physician certified your meridians ruined for twenty taels and a good story. The Corps struck your name.', { wealth: -5, rep: { court: -2 } }), O('The Depot physician tested your meridians himself. They were fine. You were fined.', { wealth: -20, rep: { court: -3 } })],
    bribe: ['Pay the Corps officer (40 taels)', { wealth: '>=40' }, O('Forty taels, and you were assigned to the archives, where nobody needs to be pacified.', { wealth: -40 })],
    other: ['Burn your tag and go outlaw', O('You burned the tag in a brazier and walked out of the city. You are on a different list now.', { flag: 'wr.outlaw', rep: { court: -10 }, fame: 3 })] },
  { key: 'child', if: { flag: 'w.war', has: 'child', npc: { x: { age: [16, 30] } }, age: [32, 100] }, bind: { x: 'child' }, art: 'road', title: 'Your child’s name',
    text: 'The recruiting officer has a list, and on it, in a clerk’s neat hand, is {x}’s name. {x} has already seen it, and is trying not to look excited.',
    answer: ['Let {x} go, and say what you need to', O('You said what you needed to, and some things you had not known you needed to. {x} went west with your old sword.', { rel: { x: { aff: 15 } }, sanity: -6 })],
    dodge: ['Hide {x} at a relative’s farm', 'insight', 30, O('{x} spent the war milking cows and complaining. {x.He} has never quite forgiven you. {x.He} is alive to not forgive you.', { rel: { x: { aff: -10 } }, sanity: 4 }), O('The officer found {x} at the farm and marched {x.him} off anyway, embarrassed in front of the cows.', { rel: { x: { aff: -5 } }, sanity: -4 })],
    bribe: ['Buy {x} out of the levy (50 taels)', { wealth: '>=50' }, O('Fifty taels, and a poorer family’s son went instead. {x} found out, and did not speak to you for a month.', { wealth: -50, rel: { x: { aff: -5 } }, sanity: -2 })],
    other: ['Go in {x.his} place', O('You told the officer you were worth three of the young ones. He looked at your grey hair and agreed to one. {x} stood at the gate as you left, finally old enough to look scared.', { flag: 'wr.enlisted', rel: { x: { aff: 25, res: 20 } }, fame: 2 })] },
], (r) => E('wr_levy', 'war', { if: r.if, bind: r.bind, art: r.art, title: r.title, text: r.text, choices: [
  C(r.answer[0], r.answer[1]),
  R(r.dodge[0], r.dodge[1], r.dodge[2], r.dodge[3], r.dodge[4]),
  Q(r.bribe[0], r.bribe[1], r.bribe[2]),
  C(r.other[0], r.other[1], r.other[2] ? { req: r.other[2] } : {}),
] }));

// Supply lines, one per route. What you carry matters more than what you swing.
const tplSupply = template('wr_supply', [
  { key: 'canal', if: { happened: 'cult_war', year: [34, 41], region: 'jiangnan', age: [16, 70] }, art: 'ship',
    text: 'Forty rice barges are going up the Grand Canal to feed the Alliance armies, and the escort captain is short of hands. The locks are slow, the canal pirates are not, and the rice is worth more every li it travels.',
    escort: ['Ride the barges north', P('Ride the barges north', 0.7, O('Thirty-eight barges reached the Yellow River. Two did not, which the escort captain said was the best run of the war. He paid you double.', { wealth: 12, rep: { merchants: 3, orthodox: 3 } }), O('Canal pirates cut out four barges at a lock in the night. The captain blamed the lock-keeper, the lock-keeper blamed the moon.', { wealth: 4 }))],
    route: ['Send the barges by the old salt canal', 'insight', 30, O('Narrower, older, forgotten by the pirates. The barges arrived a week early and the captain bought you a dinner you still think about.', { insight: 1, rep: { merchants: 4 }, wealth: 6 }), O('The old salt canal had silted up. You spent a week digging barges out of mud.', { body: 1, health: -3 })],
    skim: ['Sell a barge in Yangzhou and report it sunk', O('Forty taels in your sleeve and a barge on the bottom of the canal, on paper. Somewhere a regiment was a barge short.', { wealth: 40, infamy: 4, sanity: -5 })],
    give: ['Pay the lock-keepers to work through the night (15 taels)', { wealth: '>=15' }, O('The lock-keepers worked by torchlight and the barges went through in half the time. The rice reached the front before the snow.', { wealth: -15, rep: { orthodox: 4 }, fame: 2 })] },
  { key: 'river', if: { happened: 'cult_war', year: [36, 40], region: 'jingchu', age: [16, 70] }, art: 'river', danger: true,
    text: 'Alliance supply junks on the Great River, and the Water Fortress charging tolls on them as if there were no war at all. A Fortress toll boat comes alongside with a captain who is in no mood to haggle.',
    escort: ['Refuse the toll', O('The toll captain jumped the gap between the boats.', { combat: { foe: { name: 'a Water Fortress toll captain', kind: 'bandit', rel: 0 }, context: 'duel', lethal: 0.2, win: { text: 'The toll captain went into the river and the toll boat backed off. The junks went through free, this time.', fame: 3, rep: { orthodox: 4, unorthodox: -4 } }, lose: { text: 'He knocked you flat on your own deck and collected double.', wealth: -10 } } })],
    route: ['Negotiate the toll down', 'charm', 35, O('You explained that if the Cult won the war, the Fortress would be collecting tolls from the Cult. The captain thought about it, halved the toll, and threw in a fish.', { rep: { unorthodox: 3, orthodox: 2 }, rel: { '@water_lord': { res: 5 } } }), O('The captain thought your explanation was funny and doubled the toll.', { wealth: -8 })],
    skim: ['Pay the toll from the cargo and keep the silver', O('You paid the toll in Alliance rice and kept the toll silver. The ledgers balanced, if nobody looked hard.', { wealth: 20, infamy: 3, sanity: -3 })],
    give: ['Pay the toll yourself (12 taels)', { wealth: '>=12' }, O('You paid the toll from your own purse to save time. The toll captain looked at you as if you were mad. The rice reached Wuchang on time.', { wealth: -12, rep: { orthodox: 3 } })] },
  { key: 'passes', if: { happened: 'cult_war', year: [34, 37], region: 'guanzhong', age: [16, 70] }, art: 'snow',
    text: 'Carts of arrows and padded coats for the western front, and the passes are already under snow. The carters want double pay, the mules want nothing to do with any of it, and the front wants everything yesterday.',
    escort: ['Drive the lead cart yourself', P('Drive the lead cart yourself', 0.6, O('Six days through the snow with the mules swearing in their own way. The coats arrived. A frostbitten sentry hugged you.', { body: 2, fame: 2, rep: { orthodox: 4 } }), O('A cart went over the edge on the third day, mules and all. The rest arrived. You still dream about the mules.', { sanity: -5, health: -4 }))],
    route: ['Take the river valley road instead', 'insight', 30, O('Longer, lower, and free of snow. The carts arrived two days later than planned and with every arrow.', { insight: 1, rep: { orthodox: 3 } }), O('The river valley road had been washed away. You took the pass after all, three days late.', { health: -3 })],
    skim: ['Sell a cart of arrows to the Green Forest', O('The Green Forest paid well for arrows and asked no questions. Some of those arrows came back toward the Alliance later, you suspect.', { wealth: 25, infamy: 4, rep: { unorthodox: 3, orthodox: -2 } })],
    give: ['Buy fresh mules at Chang’an (20 taels)', { wealth: '>=20' }, O('Fresh mules made all the difference. The carters stopped asking for double pay, mostly.', { wealth: -20, rep: { orthodox: 4 }, fame: 1 })] },
  { key: 'ferries', if: { happened: 'depot_army', year: [40, 41], region: 'central', age: [16, 70] }, art: 'river',
    text: 'The ferries at the Yellow River are carrying rice, horses and powder for the coming battle at the Ford. The ferry ropes are old, the river is high, and the Depot officer in charge wants it done by dusk.',
    escort: ['Ride the powder ferry across', P('Ride the powder ferry across', 0.65, O('You crossed with the powder, nursing it like an infant. It reached the far bank dry. The Depot officer did not thank you, but he wrote something down.', { fame: 2, rep: { court: 3, orthodox: 2 } }), O('A wave came over the side and soaked half the powder. The officer wrote something else down.', { rep: { court: -2 } }))],
    route: ['Swim a new rope across', 'body', 35, O('You swam the river with a rope in your teeth. The new rope held, and the ferries ran until dark.', { body: 2, fame: 3 }), O('The current took you a li downstream. Somebody else swam the rope.', { health: -8 })],
    skim: ['Sell a horse off the ferry to a farmer', O('A fine cavalry horse for twelve taels, and the farmer very pleased. The ledger said the horse drowned.', { wealth: 12, infamy: 2 })],
    give: ['Hire extra boatmen (10 taels)', { wealth: '>=10' }, O('Ten extra boatmen and the job done by midafternoon. The Depot officer looked almost disappointed.', { wealth: -10, rep: { court: 2, orthodox: 2 } })] },
  { key: 'plank_roads', if: { happened: 'cult_war', year: [34, 41], region: 'shu', age: [16, 70] }, art: 'mountain',
    text: 'Emei herbs and Dang antidotes for the northern armies, carried on porters’ backs over the plank roads that cling to the Shu cliffs. The head porter is sixty and has done this for forty years. He does not like your boots.',
    escort: ['Carry a load yourself', P('Carry a load yourself', 0.7, O('Eleven days on the plank roads with a basket of medicine on your back. The head porter conceded, at the end, that your boots were adequate.', { body: 2, rep: { orthodox: 3 }, sanity: 2 }), O('A plank gave way under you. You caught the chain. The basket did not.', { health: -6, rep: { orthodox: -1 } }))],
    route: ['Plan the stages so nobody walks at night', 'insight', 30, O('You rearranged the stages so every night ended at an inn. Nobody fell. The head porter looked at your plan, grunted, and kept it.', { insight: 2, rep: { orthodox: 3 } }), O('Your stages ended at inns that had burned down. The porters slept on the cliff.', { sanity: -2 })],
    skim: ['Sell the antidotes in Chengdu instead', O('Dang antidotes sell for their weight in silver in Chengdu. Somebody in the north died of something that one of them would have cured.', { wealth: 35, infamy: 4, sanity: -6 })],
    give: ['Pay the porters a bonus (10 taels)', { wealth: '>=10' }, O('The porters sang the whole way. The head porter allowed that you were not as useless as your boots.', { wealth: -10, sanity: 3, rep: { orthodox: 2 } })] },
  { key: 'taihang', if: { happened: 'hebei_drought', year: [46, 49], region: 'hebei', age: [16, 70] }, art: 'road', danger: true,
    text: 'Grain for the imperial campaign against the Green Forest, through the very mountains the Green Forest holds. The convoy commander thinks this is a fine joke. The Green Forest raider on the ridge above you does not.',
    escort: ['Hold the ridge', O('The raider came down the ridge at you.', { combat: { foe: { name: 'a Green Forest raider', kind: 'bandit', rel: 0 }, context: 'ambush', lethal: 0.25, win: { text: 'The raiders pulled back up the ridge. The convoy went through, and the commander stopped finding it funny.', fame: 3, rep: { court: 4, unorthodox: -4 }, wealth: 6 }, lose: { text: 'The raiders took six carts and your cloak. They left you the cart with the turnips.', wealth: -5 } } })],
    route: ['Pay the Green Forest a toll in rice', 'charm', 30, O('A cart of rice for safe passage, agreed at a roadside shrine. The commander complained. The convoy arrived complete minus one cart.', { rep: { unorthodox: 4, court: 1 } }), O('The Green Forest took the cart of rice and then the convoy.', { wealth: -5, rep: { court: -2 } })],
    skim: ['Sell grain to the starving villages on the way', O('You sold grain off the back of the carts to villages that had none, at a fair price. The campaign went a little hungry. The villages did not.', { wealth: 10, sanity: 4, rep: { court: -3 } })],
    give: ['Hire local guides (12 taels)', { wealth: '>=12' }, O('The guides knew every ridge the raiders used. The convoy went round all of them.', { wealth: -12, rep: { court: 3 } })] },
  { key: 'jade_road', if: { happened: 'blood_demon_throne', year: [31, 33], region: 'west', age: [16, 70] }, art: 'desert',
    text: 'Water barrels and arrows for the Jade Gate garrison, by camel across sixty li of open sand. The caravan master watches the horizon for Cult outriders more than he watches the road.',
    escort: ['Ride at the head of the caravan', P('Ride at the head of the caravan', 0.65, O('Three days of sand and nothing on the horizon but more sand. The garrison captain met you at the gate and drank half a barrel on the spot.', { wealth: 8, rep: { court: 3 }, body: 1 }), O('Outriders on the second day. You lost a third of the barrels running from them.', { sanity: -3, wealth: 2 }))],
    route: ['Travel by night and rest by day', 'insight', 28, O('Cool nights, hidden days, and no outriders. The camels approved, which camels rarely do.', { insight: 1, rep: { court: 3 } }), O('Night travel in the desert is how people walk in circles. You walked in circles.', { health: -4 })],
    skim: ['Sell water to a passing caravan', O('A Silk Road caravan paid in silver for water. The garrison got a little less, and drank a little less, and did not know why.', { wealth: 15, infamy: 2 })],
    give: ['Buy extra barrels (15 taels)', { wealth: '>=15' }, O('Extra barrels, and the garrison had water through the dry season for the first time in years.', { wealth: -15, rep: { court: 4 }, fame: 1 })] },
  { key: 'granary', if: { happened: 'cult_war', year: [35, 41], loc: 'luoyang', age: [16, 70] }, art: 'scroll',
    text: 'You have been given a cart and a chit for two hundred sacks from the Alliance granary in Luoyang. The granary clerk looks at your chit, and at you, and suggests that a hundred and fifty sacks would be a more realistic number.',
    escort: ['Insist on two hundred', P('Insist on two hundred', 0.4, O('You insisted, loudly, in front of other carters. The clerk found two hundred sacks, somehow, and noted your face.', { rep: { orthodox: 3 }, fame: 1 }), O('The clerk found a hundred and fifty, and a problem with your chit.', { rep: { orthodox: -1 } }))],
    route: ['Count the sacks in the granary yourself', 'insight', 35, O('You counted while the clerk was at lunch. The granary held less than half what the ledgers said.', { codex: LEDGER, insight: 2 }), O('The clerk came back early from lunch.', { sanity: -3 })],
    skim: ['Take the clerk’s suggestion and his percentage', O('A hundred and fifty sacks, and a quiet tael per sack for you. The front got a hundred and fifty. You got fifty taels and a share in something rotten.', { wealth: 50, infamy: 5, sanity: -6 })],
    give: ['Buy the missing sacks yourself (30 taels)', { wealth: '>=30' }, O('You bought fifty sacks at the market and loaded them yourself. Two hundred reached the front. The clerk watched you go with an expression you could not read.', { wealth: -30, rep: { orthodox: 5 }, fame: 2 })] },
  { key: 'second', if: { happened: 'second_war', year: [74, 79], region: ['central', 'jingchu'], age: [16, 120] }, art: 'road',
    text: 'The Second War needs rice and arrows like the first, and the convoys are run by young men who think the old roads are the only roads. You know the other roads.',
    escort: ['Ride with the convoy', P('Ride with the convoy', 0.7, O('The convoy arrived. The young captain thanked you for your company, as if you were someone’s grandparent along for the ride. You were.', { wealth: 6, sanity: 2 }), O('Cult raiders hit the convoy at a ford. You got the young ones out. Not the carts.', { sanity: -4, health: -3 }))],
    route: ['Show them the road you used forty years ago', 'insight', 25, O('An old drovers’ track nobody had used since the first war. The convoy came through without a single raider.', { fame: 3, rep: { orthodox: 4 } }), O('The old road was a reservoir now. You had to admit it, publicly.', { sanity: -2 })],
    skim: ['Take your old soldier’s share', O('"A veteran’s share," you called it. The young captain was too polite to argue. You were not proud of it.', { wealth: 15, sanity: -4 })],
    give: ['Feed the drivers at your own expense (8 taels)', { wealth: '>=8' }, O('You fed the drivers like your own children. They drove like it, too.', { wealth: -8, sanity: 3 })] },
], (r) => E('wr_supply', 'war', { if: r.if, once: false, cd: 4, danger: !!r.danger, art: r.art, title: 'Supply lines', text: r.text, choices: [
  C(r.escort[0], r.escort[1]),
  R(r.route[0], r.route[1], r.route[2], r.route[3], r.route[4]),
  C(r.skim[0], r.skim[1]),
  Q(r.give[0], r.give[1], r.give[2]),
] }));

// Field hospitals, one per site.
const tplHospital = template('wr_hospital', [
  { key: 'shaolin', if: { happened: 'siege_song', year: [36, 37], loc: 'songshan', age: [14, 80] }, art: 'temple',
    text: 'The Shaolin infirmary after the siege: monks with burns from the Cult’s fire-oil, novices with broken arms, and a Cult prisoner with a spear wound that the monks are treating with exactly the same care as everyone else.',
    triage: ['Help the monks sort the wounded', 'insight', 30, O('Those who will live, those who will not, and those who might. The monks taught you to sort them without your hands shaking. You are not sure you wanted to learn it.', { insight: 2, rep: { orthodox: 4 }, sanity: -3 }), O('You sorted badly and a monk quietly re-sorted behind you.', { sanity: -4 })],
    comfort: ['Sit with the Cult prisoner', O('He was nineteen and very frightened of the monks being kind. You talked about food. He liked dumplings. Everyone likes dumplings.', { sanity: 3, rep: { cult: 2 } })],
    knot: O('You tied the knot on a monk whose leg would not stop bleeding. The infirmary master asked you to show the novices, all of them, twice.', { fame: 3, rep: { orthodox: 5 } }),
    store: O('Your salves and bandage cloth went in an afternoon. The infirmary master bowed to you. A monk bowing is a serious thing.', { unflag: 'wr.medicine_store', fame: 4, rep: { orthodox: 6 } }),
    leave: ['Leave it to the monks', O('You left it to the monks, who have been doing this for a thousand years.')] },
  { key: 'wudang', if: { happened: 'wudang_holds', year: [37, 38], loc: 'wudang', age: [14, 80] }, art: 'temple',
    text: 'Wudang’s wounded lie in the Purple Cloud Hall, and the Daoist physicians treat them with needles, herbs and, when nothing else works, jokes. A disciple who held the pass alone is dying cheerfully.',
    triage: ['Assist with the needles', 'insight', 35, O('You learned more about the meridians in one night than in a year of meditation. The disciple who held the pass did not die, which surprised him.', { insight: 3, qi: 6 }), O('A needle in the wrong place. The physician took over without a word.', { sanity: -3 })],
    comfort: ['Laugh at the dying disciple’s jokes', O('His jokes were terrible and you laughed at every one. He died laughing, which he said was the plan.', { sanity: -2, charm: 2 })],
    knot: O('You tied the knot and the Daoist physician tilted his head. "Inelegant," he said. "Effective. Teach me." You did.', { insight: 2, rep: { orthodox: 4 } }),
    store: O('You opened your medicine store to the Purple Cloud Hall. The Daoists insisted on paying you in tea, which was worth more than the medicine.', { unflag: 'wr.medicine_store', item: { tea_brick: 2 }, rep: { orthodox: 5 } }),
    leave: ['Walk the mountain instead', O('You walked the mountain paths all night instead. It helped you, if nobody else.', { sanity: 2 })] },
  { key: 'beggars', if: { happened: 'cult_war', year: [35, 41], loc: 'luoyang', age: [14, 80] }, art: 'city',
    text: 'Under a Luoyang bridge, the Beggars’ Sect runs a field hospital for wounded nobody else will take: unorthodox fighters, deserters, Cult prisoners who escaped. The surgeon is a one-eyed Nine-Pouch elder with very clean hands.',
    triage: ['Help the elder with a deep wound', 'insight', 25, O('He talked you through it: here, and here, and pull. The man lived. The elder gave you a pouch for your belt, which among Beggars is a kind of diploma.', { insight: 2, rep: { orthodox: 3 } }), O('You fainted. The elder stepped over you and finished.', { sanity: -3 })],
    comfort: ['Bring the patients wine', O('You bought two jars of terrible wine for the whole bridge. The elder pretended to disapprove and drank a cup himself.', { wealth: -2, sanity: 4 })],
    knot: O('The elder watched you tie it with his one eye. "Where did a nice person learn a filthy trick like that?" He was delighted.', { rel: { '@beggar_chief': { res: 8 } }, fame: 2 }),
    store: O('Your medicine store went under the bridge. The Beggars’ Sect remembers its friends, and it has a very good memory.', { unflag: 'wr.medicine_store', rep: { orthodox: 5 }, rel: { '@beggar_chief': { aff: 10 } } }),
    leave: ['Give the elder a few coppers and go', O('He took the coppers with dignity. A bridge hospital runs on coppers.', { wealth: -1 })] },
  { key: 'changan', if: { happened: 'kongtong_falls', year: [35, 38], loc: 'changan', age: [14, 80] }, art: 'shrine',
    text: 'A Chang’an temple has become a hospital for the survivors of Kongtong and the western valleys. The abbot has turned the main hall over to the wounded and the gods to the courtyard, where they are getting rained on.',
    triage: ['Sort the wounded at the temple gate', 'insight', 30, O('You stood at the gate for three days deciding who went in first. It was the hardest work of the war, and the abbot said you did it fairly.', { insight: 2, fame: 2, sanity: -4 }), O('You let in the loudest first. The quietest died waiting.', { sanity: -8 })],
    comfort: ['Write letters for the wounded', O('Letters to mothers, wives, a dog. You wrote them all in your best hand, and lied where you had to.', { charm: 2, sanity: 2 })],
    knot: O('You tied the knot on a Kongtong fist-master with a severed artery. He lived to curse you for the scar.', { fame: 3, rep: { orthodox: 4 } }),
    store: O('Your stores went to the temple. The abbot moved one god back inside, out of the rain, in your honour.', { unflag: 'wr.medicine_store', fame: 3, rep: { orthodox: 5 }, sanity: 3 }),
    leave: ['Light incense for the gods in the courtyard', O('You lit incense for the rained-on gods. Someone had to.', { sanity: 1 })] },
  { key: 'dang', if: { happened: 'dang_civil_war', year: [26, 27], loc: 'dangclan', age: [14, 80] }, art: 'estate',
    text: 'The Dang field hospital has the best physicians in the empire and the worst patients: everyone in it has been poisoned by a relative. The physicians argue over each case like scholars over a disputed text.',
    triage: ['Help identify the poisons', 'insight', 40, O('Purple lips, green fingernails, a smell of almonds. You named three poisons the Dang physicians had not, and they treated you like a colleague for a week.', { insight: 3, rep: { families: 5 }, recipe: 'healing_salve' }), O('You named the wrong poison, and the physicians kindly explained, at length, why.', { insight: 1 })],
    comfort: ['Keep the patients from poisoning each other', O('A surprisingly full-time job. You confiscated eleven hairpins, two rings and a very suspicious pear.', { rep: { families: 3 }, sanity: 2 })],
    knot: O('The knot stopped the poison climbing a man’s arm long enough for the antidote. A Dang physician wrote it down in a book with no title.', { rep: { families: 4 }, fame: 2 }),
    store: O('Your salves were crude by Dang standards, they told you, and then used every one.', { unflag: 'wr.medicine_store', rep: { families: 6 } }),
    leave: ['Leave before anyone offers you tea', O('You left before anyone offered you tea. In the Dang manor, that is not cowardice; that is literacy.')] },
  { key: 'namgung', if: { happened: 'namgung_burns', year: [38, 39], region: 'jiangnan', age: [14, 80] }, art: 'fire',
    text: 'The survivors of the Namgung Estate are in a Hangzhou warehouse turned hospital: burns, mostly, and smoke in the lungs. The Namgung wounded refuse to cry out, which makes the burns harder to find.',
    triage: ['Find the burns they are hiding', 'insight', 30, O('You learned to read pride the way physicians read pulses. You found every hidden burn, and the proudest patients forgave you, eventually.', { insight: 2, rep: { families: 6 } }), O('A retainer hid a burn on his back from you until it festered. You found it too late.', { sanity: -6 })],
    comfort: ['Tell them the Namgung name still means something', O('You told them the name still meant something. It was true, and it helped more than the salves.', { charm: 1, rep: { families: 4 }, sanity: 2 })],
    knot: O('The knot held a cut retainer together until the surgeon came. He bowed to you from the stretcher, which nearly undid it.', { rep: { families: 5 }, fame: 2 }),
    store: O('Your salves soothed burns that had kept people awake for weeks. One old aunt wept, and blamed the smoke.', { unflag: 'wr.medicine_store', rep: { families: 8 }, fame: 3 }),
    leave: ['Leave them their pride', O('You left them their pride. It was all they had brought out of the fire.')] },
  { key: 'ford', if: { happened: 'yellow_ford', year: [41, 42], region: 'central', age: [14, 80] }, art: 'battlefield',
    text: 'After the Ford, the healers’ tents stretch a li along the riverbank. Alliance, Depot and Cult wounded lie in the same mud. Somebody has to decide whether the Cult wounded get treated at all.',
    triage: ['Treat everyone in order of need', 'insight', 35, O('In order of need, regardless of armband. Some Alliance captains objected. You treated one of them next, and he stopped objecting.', { insight: 2, fame: 4, rep: { cult: 4 } }), O('You tried. There were too many, and not enough of you.', { sanity: -8 })],
    comfort: ['Walk the line with water', O('A li of wounded and one bucket. You walked it six times. Nobody asked which side you were on.', { sanity: 2, body: 1 })],
    knot: O('The knot again, and again, until your teeth ached. More men walked away from that riverbank because of a one-handed beggar than will ever know it.', { fame: 4, rep: { orthodox: 4 } }),
    store: O('You emptied your medicine store into the healers’ tents. It was gone by noon. It was the best thing you ever bought.', { unflag: 'wr.medicine_store', fame: 6, sanity: 6 }),
    leave: ['Go and look for people you know', O('You walked the tents looking for faces you knew. You found some.', { sanity: -3 })] },
  { key: 'emei', if: { happened: 'cult_war', year: [34, 41], loc: 'emei', age: [14, 80] }, art: 'temple',
    text: 'Emei sends its nuns north and takes in the wounded who come south. The Golden Summit hospice is quiet, clean, and full of soldiers who keep apologising to the nuns for their language.',
    triage: ['Assist the nun-physicians', 'insight', 30, O('The nuns worked in silence and you learned to as well. In the silence you could hear what each patient needed.', { insight: 2, sanity: 4, rep: { orthodox: 3 } }), O('You talked too much. A nun put a finger to her lips and pointed you at the laundry.', { body: 1 })],
    comfort: ['Teach the soldiers to apologise less', O('You told them the nuns had heard worse. A nun nodded. The soldiers were scandalised, and relieved.', { charm: 2, sanity: 2 })],
    knot: O('The nuns watched you tie it and the Abbess, passing, stopped. "Teach it to the novices," she said. That was all. It was enough.', { rep: { orthodox: 5 }, fame: 2 }),
    store: O('The nuns accepted your stores with a bow and recorded them in a ledger in tiny, perfect characters.', { unflag: 'wr.medicine_store', rep: { orthodox: 5 }, sanity: 3 }),
    leave: ['Sit by the sea of clouds', O('You sat by the sea of clouds for an hour. The war was very far below.', { sanity: 4 })] },
  { key: 'depot_camp', if: { happened: 'depot_army', year: [40, 41], faction: 'court', age: [14, 80] }, art: 'battlefield',
    text: 'The imperial camp hospital treats soldiers first, officers second, and murim volunteers if there is time, which there is not. A Huashan swordsman with a gut wound has been waiting since morning.',
    triage: ['Treat the swordsman against orders', 'insight', 30, O('You treated him behind a tent. He lived. Your officer pretended not to see, which in the Depot is a form of kindness.', { insight: 2, rep: { orthodox: 5, court: -2 } }), O('You were caught and docked a month’s pay. The swordsman lived anyway; someone else had been treating him too.', { wealth: -5, rep: { court: -3 } })],
    comfort: ['Bring the murim wounded water', O('Water is not against orders. You made sure of it with a very careful reading of the orders.', { sanity: 3, rep: { orthodox: 3 } })],
    knot: O('The knot saved a soldier’s leg, and a Depot surgeon asked where you learned it. You said the murim. He looked at the murim wounded differently after that.', { rep: { orthodox: 4, court: 2 } }),
    store: O('You opened your medicine store to the murim wounded only. The Depot noted it.', { unflag: 'wr.medicine_store', rep: { orthodox: 8, court: -4 }, fame: 3 }),
    leave: ['Follow orders', O('You followed orders. The swordsman was still waiting at dusk.', { sanity: -6, merit: 3 })] },
], (r) => E('wr_hospital', 'war', { if: r.if, once: false, cd: 3, art: r.art, title: 'Field hospital', text: r.text, choices: [
  R(r.triage[0], r.triage[1], r.triage[2], r.triage[3], r.triage[4]),
  C(r.comfort[0], r.comfort[1]),
  M('Tie Old Bang’s knot', 'secret.wr_tourniquet', r.knot),
  C('Open your medicine store', r.store, { show: { flag: 'wr.medicine_store' } }),
  C(r.leave[0], r.leave[1]),
] }));

// Spies and informers, one per city and war.
const tplSpy = template('wr_spy', [
  { key: 'luoyang_cult', if: { or: [{ flag: 'w.war_coming' }, { flag: 'w.war' }], year: [32, 41], loc: 'luoyang', age: [16, 80] }, art: 'inn',
    text: 'A tea merchant at the inn asks a great many questions about the Alliance hall: who comes, when, how many guards. He pays for everyone’s tea. His hands have a fighter’s calluses and his accent slips west when he laughs.',
    expose: ['Watch him until you are sure', 'insight', 30, O('You followed him to a Cult drop under a shrine and brought the Beggars to it. They let him collect, and followed him home, and the Shadow Hall lost a network.', { fame: 4, rep: { orthodox: 6, cult: -4 } }), O('He noticed you watching and was gone by morning.', { insight: 1 })],
    turn: ['Feed him false numbers', O('Twelve guards, you told him, never fewer, and a secret gate in the east wall. Somewhere in the west a Cult commander planned around a gate that does not exist.', { insight: 2, rep: { orthodox: 3 } })],
    use: ['Sell him real answers', O('He paid very well for the hours of the Alliance guard. You did not think about what he would do with them, and then you did.', { wealth: 30, infamy: 5, rep: { cult: 4 }, sanity: -6 })],
    ignore: ['Drink your tea', O('You drank your tea. It was very good tea.')] },
  { key: 'mounthua', if: { flag: 'w.war_coming', not: 'traitor.exposed', alive: 'hua_traitor', year: [31, 33], region: 'guanzhong', age: [14, 80] }, art: 'night', danger: true,
    text: 'A masked rider waits at a shrine below Mount Hua every tenth night, and every tenth night a Mount Hua elder with a warm smile comes down the mountain to meet him. Tonight is the tenth night.',
    expose: ['Bring the Mount Hua Sect Leader to see for himself', 'fame', 35, O('Hyeon Mu-gyeong stood behind the shrine with you and watched his old friend take a purse from a masked rider. He did not speak all the way back up the mountain. Gu Dal-pyeong was sealed in the Hall of Repentance by dawn.', { flag: 'traitor.exposed', codex: 'secret.gu_debts', rep: { orthodox: 8 }, fame: 6, gaze: 1 }), O('The Sect Leader would not come. "Gu is my friend," he said. "I will not spy on him." The rider came and went.', { flag: 'hua.leader_doubts' })],
    turn: ['Follow the rider instead', O('The rider led you to the old salt mines west of Chang’an and a camp of Cult scouts with maps of Mount Hua.', { codex: SCOUT_MAPS, insight: 1 })],
    use: ['Step out and confront the elder', O('Gu Dal-pyeong turned, still smiling.', { combat: { foe: '@hua_traitor', context: 'duel', lethal: 0.25, important: true, win: { text: 'You dragged him up the mountain with his purse still in his sleeve. The Plum Blossom Path has new guards.', flag: 'traitor.exposed', fame: 8, rep: { orthodox: 8 }, gaze: 1 }, lose: { text: 'He beat you, and smiled, and went back up the mountain to tell the Sect Leader that bandits had attacked him on the road.', health: -6 } } })],
    ignore: ['Let it be', O('You let it be. It was not your mountain. Not yet.')] },
  { key: 'namgung', if: { year: [20, 23], loc: 'namgung', timeline: { namgung_assassination: 'pending' }, age: [14, 80] }, art: 'estate',
    text: 'A new servant in the Namgung patriarch’s wing reads every letter he carries, and draws little maps of the roofs on the back of his hand. He is very good at being forgettable.',
    expose: ['Catch him at it', 'insight', 35, O('You caught him copying the patriarch’s study roof onto a rice paper. Under questioning he named a buyer in Kaifeng and a payer nobody could trace.', { rep: { families: 6 }, codex: { id: 'secret.wr_roof_map', cat: 'secrets', title: 'The roof map', text: 'Before the Namgung patriarch is killed in Year 23, a new servant in his wing maps the study roof for a buyer in Kaifeng’s Ghost Market.' } }), O('He saw you watching and became, overnight, the most diligent servant in Jiangnan.', { insight: 1 })],
    turn: ['Warn the patriarch about his roof', O('Namgung Hwi listened, unamused, and had the study roof tiled over with bronze. It did not occur to him that it might have been a warning about more than tiles.', { rel: { '@namgung_hwi': { res: 5 } } })],
    use: ['Ask the servant who pays him', O('He laughed, quite genuinely. "Nobody knows who pays anybody," he said. "That is the point of the Ghost Market."', { insight: 1 })],
    ignore: ['It is not your house', O('It was not your house. It would not be your funeral.')] },
  { key: 'kaifeng_depot', if: { happened: 'depot_army', year: [40, 56], loc: 'kaifeng', age: [16, 90] }, art: 'city',
    text: 'The friendly old man who sells candied hawthorn by the Kaifeng canal remembers every martial artist who buys from him, and their sect, and their realm. He writes it all down after dark, for the Eastern Depot.',
    expose: ['Find his ledger', 'insight', 30, O('You found the ledger under his stall and read your own name in it. You burned the page. You left the rest, so he would not know.', { codex: DEPOT_LISTS, insight: 1 }), O('The ledger was not under the stall. Your hawthorn was very sticky.', {})],
    turn: ['Buy him a drink and ask about the Depot', O('He drank and talked: lists, more lists, a Director who says the murim is a disease. "I only write names," he said. Everybody only writes names.', { codex: DEPOT_LISTS, sanity: -2 })],
    use: ['Pay him to forget you', O('Five taels and he forgot your face so thoroughly he sold you hawthorn the next day as a stranger.', { wealth: -5 })],
    ignore: ['Buy hawthorn and go', O('You bought hawthorn and went. It was excellent hawthorn, as informers’ hawthorn usually is.')] },
  { key: 'tenthousand', if: { flag: 'w.war', sect: 'cult', age: [16, 80] }, art: 'demonic',
    text: 'A believer in your hall prays a little too carefully, the way people pray who learned it from a book. You have seen him counting the barracks. The Shadow Hall pays a bounty for Alliance spies, and makes an example of them.',
    expose: ['Report him to the Shadow Hall', 'insight', 25, O('You reported him. The Shadow Hall made its example. You received a bounty and a nod from a man who never blinks.', { merit: 10, rep: { cult: 6 }, wealth: 15, sanity: -8, rel: { '@shadow_master': { res: 10 } } }), O('You reported him, and he was gone before they came. Someone had warned him. The Shadow Hall wondered who.', { flag: 'cult.suspect' })],
    turn: ['Warn him to run', O('You told him, quietly, that he prays like a scholar. He was gone by morning. He left you his prayer beads.', { sanity: 4, rep: { orthodox: 3 }, flag: 'cult.suspect' })],
    use: ['Feed him the granary tallies', O('You let him see the quartermaster’s tallies: the three granaries outside the Jade Gate, the whole of the army’s stomach. You did not quite know why. Perhaps you wanted someone to stop it.', { codex: GRANARIES, rep: { cult: -3 } })],
    ignore: ['Say nothing', O('You said nothing. In the Ten Thousand Mountains, saying nothing is a skill.')] },
  { key: 'wuchang', if: { happened: 'grain_fleet', year: [13, 17], loc: 'wuchang', age: [12, 80] }, art: 'river',
    text: 'One of the imperial boatmen on the Wuchang quay is a Water Fortress man: he whistles a Dongting fishing song when he thinks nobody is listening, and he has been counting the war junks.',
    expose: ['Tell the harbour master', 'charm', 25, O('The harbour master laughed at you, then listened, then sent men. The boatman went into the river and swam for Dongting with half the harbour watching.', { rep: { court: 4 }, fame: 2 }), O('The harbour master did not care for children’s stories.', {})],
    turn: ['Whistle the second verse at him', O('He froze, then grinned, and bought you noodles. "Fortress family?" he asked. You let him think so. He told you more than he meant to about the reeds.', { insight: 2, rep: { unorthodox: 2 } })],
    use: ['Sell the harbour master his name', O('The harbour master paid three taels for the name. The boatman was not seen again. You learned how cheap a name is.', { wealth: 3, sanity: -4, rep: { court: 2, unorthodox: -3 } })],
    ignore: ['Learn the song yourself', O('You learned the song. It is a good song, about a fish that outwits a fisherman.', { charm: 1 })] },
  { key: 'zhongnan', if: { or: [{ flag: 'w.war_coming' }, { flag: 'w.war' }], timeline: { alliance_betrayal: 'pending' }, year: [33, 38], region: 'guanzhong', age: [16, 80] }, art: 'forest',
    text: 'A Zhongnan courier rides west from Mount Zhongnan every month with a sealed case. Nobody stops a courier carrying the Alliance Leader’s seal. Tonight he has camped by the same spring as you, and he drinks heavily.',
    expose: ['Open the case while he sleeps', 'insight', 40, O('Letters in the Alliance Leader’s hand to the Cult’s Shadow Hall, very polite, about prices. You resealed the case and made a copy, and the copy went to the Beggars’ Sect, and the Beggars’ Sect went to the Alliance hall.', { avert: 'alliance_betrayal', flag: 'alliance.cleansed', fame: 10, rep: { orthodox: 8 }, gaze: 1 }), O('He woke with his hand on the case and his eyes on you. You pretended to be looking for the latrine.', { sanity: -3 })],
    turn: ['Drink with him', O('He talked, as drunk men do: the Leader’s letters, the money, a house in the south he was promised. He did not remember telling you.', { codex: { id: 'secret.wr_zhongnan_courier', cat: 'secrets', title: 'The Zhongnan courier', text: 'From Year 33, a Zhongnan courier carries Hwangbo Jun’s letters west to the Cult every month, sealed with the Alliance Leader’s seal. He drinks, and camps by the spring below Zhongnan.' } })],
    use: ['Steal his horse', O('A very fine horse. The courier walked. His letters arrived a month late, and the Cult wondered why.', { wealth: 15, infamy: 2 })],
    ignore: ['Move your camp upstream', O('You moved your camp upstream. Some springs are not for drinking from.')] },
  { key: 'paeng', if: { happened: 'hebei_drought', year: [46, 49], loc: 'paeng', age: [16, 80] }, art: 'estate', danger: true,
    text: 'A new stable hand at the Paeng fortress is a Green Forest scout: he knows horses too well and sabers not at all, and goes up the hill every evening to "pray". The Paeng are loud enough not to notice anything.',
    expose: ['Tell Paeng Dae-ho', 'charm', 25, O('Paeng Dae-ho laughed until the rafters shook, then had the stable hand brought in and fed him dinner. "Tell your mountain," he said, "the Paeng saber is sharp and our gates are open, if they want to come and die." The Green Forest did not come.', { rel: { '@paeng_daeho': { res: 10, aff: 10 } }, rep: { families: 4 } }), O('Paeng Dae-ho thought you were joking and laughed at that too.', {})],
    turn: ['Ask him why he joined the Green Forest', O('"Drought," he said. "My village had nothing. The Forest had rice." He went back to the mountain that night with a sack of Paeng oats you gave him. It seemed the right thing.', { sanity: 3, rep: { unorthodox: 2 } })],
    use: ['Catch him on the hill', O('You caught him on the hill with a signal mirror.', { combat: { foe: { name: 'a Green Forest scout', kind: 'bandit', rel: -0.5 }, context: 'duel', lethal: 0.15, win: { text: 'He yielded and talked. The Paeng moved their horses before the raid, and the raid found an empty paddock.', rep: { families: 5 }, fame: 2 }, lose: { text: 'He knocked you down and ran for the mountain, mirror and all.', health: -4 } } })],
    ignore: ['It is not your fortress', O('The Paeng have survived worse than a stable hand.')] },
  { key: 'capital_coup', if: { flag: 'w.registry', alive: 'guard_commander', year: [57, 60], loc: 'capital', age: [16, 100] }, art: 'palace',
    text: 'A Depot clerk you know from the registry office has been copying the duty rosters of the Imperial Guard, at night, by a hooded lamp. The Director, people say, has more ambitions than the Registry.',
    expose: ['Take the copies to Commander Han Gyeong', 'insight', 30, O('You lifted the copies from the clerk’s desk and carried them to Han Gyeong in a basket of leeks. He read them in silence and changed every roster in the Guard that night.', { rel: { '@guard_commander': { res: 20, aff: 10 } }, fame: 3 }), O('The clerk’s desk was locked, and the clerk came back for his lamp.', { sanity: -3 })],
    turn: ['Ask the clerk what he is copying', O('He went white, then grey, then told you everything in a whisper: the Director, the palace, a night not yet set. "I only copy," he said.', { insight: 2, codex: { id: 'secret.wr_coup_rosters', cat: 'secrets', title: 'The Director’s coup', text: 'Before Wi Chung-hyeon’s coup in Year 60, a Depot registry clerk copies the Imperial Guard’s duty rosters at night. Han Gyeong never sees them unless someone carries them to him.' } })],
    use: ['Sell the rosters back to the Director', O('The Director’s secretary paid for the rosters without a flicker of surprise. You had sold him something he already had, and he had bought you.', { wealth: 40, infamy: 6, rep: { court: 5 } })],
    ignore: ['Close the door and leave', O('You closed the door very quietly and went home.')] },
], (r) => E('wr_spy', 'war', { if: r.if, danger: !!r.danger, art: r.art, title: 'A spy', text: r.text, choices: [
  R(r.expose[0], r.expose[1], r.expose[2], r.expose[3], r.expose[4]),
  C(r.turn[0], r.turn[1]),
  C(r.use[0], r.use[1]),
  C(r.ignore[0], r.ignore[1]),
] }));

// Deserters, one per army.
const tplDeserter = template('wr_deserter', [
  { key: 'levy', if: { happened: 'grain_fleet', year: [14, 18], region: 'jingchu', age: [12, 80] }, art: 'river',
    text: 'A levy spearman from the Dongting expedition is hiding in your woodshed, seventeen and wet through. He says the reeds ate his whole company. The expedition hangs deserters at the quay.',
    hide: ['Hide him until the fleet leaves', P('Hide him until the fleet leaves', 0.7, O('The fleet sailed and the searches stopped. He walked home to his village, three hundred li, on your old sandals.', { sanity: 5 }), O('A neighbour told the sergeant. They took him from your woodshed and fined you for the shed.', { wealth: -5, sanity: -6 }))],
    feed: ['Feed him and point him toward the hills', O('You fed him and pointed. He went. You hoped he knew the way better than you did.', { sanity: 2, wealth: -1 })],
    turn: ['Turn him in', O('The sergeant paid a tael. You did not go down to the quay the next morning.', { wealth: 1, rep: { court: 2 }, sanity: -8 })],
    extra: ['Teach him to pass for a fisherman', O('Two days of mending nets and learning to curse like a Wuchang fisherman. He passed the checkpoint selling fish.', { insight: 1, sanity: 3 })] },
  { key: 'alliance', if: { happened: 'cult_war', year: [34, 41], region: 'central', age: [14, 90] }, art: 'road',
    text: 'An Alliance disciple with his sect badge torn off is begging at a crossroads. He held the line at Mount Song for three days and then could not hold anything. His sect will expel him, and the Alliance will brand him.',
    hide: ['Give him your spare clothes and a new name', P('Give him your spare clothes and a new name', 0.75, O('He became a cook in a Kaifeng noodle shop, and a good one. Years later he served you noodles and did not charge.', { sanity: 5, rep: { orthodox: -1 } }), O('An Alliance patrol recognised his face from a list. Your clothes did not help him.', { sanity: -6 }))],
    feed: ['Share your meal and listen', O('He talked about the steps of Mount Song until it was dark. You did not judge him. You were not sure you had the right.', { sanity: 1, insight: 1 })],
    turn: ['Hand him to an Alliance patrol', O('The patrol thanked you. His sect thanked you. You did not thank yourself.', { rep: { orthodox: 4 }, sanity: -8 })],
    extra: ['Take him back to his sect and speak for him', O('You stood in his sect’s hall and argued that a man who held three days had earned the fourth. The elders let him stay, as a gate-keeper. He kept the gate very well.', { fame: 3, rep: { orthodox: 3 }, sanity: 4 })] },
  { key: 'cult', if: { happened: 'cult_war', year: [34, 41], region: 'guanzhong', age: [14, 90] }, art: 'forest',
    text: 'A Cult believer is hiding in a ruined shrine, but he has not abandoned his faith; he still prays to the Heavenly Demon every dawn. He has only abandoned the Blood Demon. "This is not what the old master taught," he says.',
    hide: ['Help him get back west', P('Help him get back west', 0.6, O('You got him to the Jade Gate. At the pass he bowed in the Cult way and said that the old master’s heir would remember. You did not know what he meant until later.', { rep: { cult: 6 }, sanity: 3 }), O('An Alliance patrol caught you both. They kept him and let you go, with a warning and a bruise.', { health: -4, rep: { orthodox: -2 } }))],
    feed: ['Leave him food and go', O('You left him food at the shrine. In the morning there was a carved wooden demon in its place, smiling.', { sanity: 2 })],
    turn: ['Take him to the Alliance', O('The Alliance paid a bounty for Cult prisoners. He went quietly, praying.', { wealth: 10, rep: { orthodox: 3, cult: -4 }, sanity: -6 })],
    extra: ['Ask him what the old master taught', O('"That strength is a duty, not a right," he said. "That the Cult protects the west, it does not eat the east." He talked until dawn. It did not sound like the Cult you had been told about.', { insight: 2, rep: { cult: 2 } })] },
  { key: 'namgung', if: { flag: 'wr.feud_war', year: [24, 30], region: ['jiangnan', 'hebei'], age: [14, 90] }, art: 'estate',
    text: 'A Namgung retainer has walked away from the march on the Jegal. His mother was a Jegal. "I will not kill my uncles for a rumour," he says, and the Namgung say that is exactly what a Jegal spy would say.',
    hide: ['Hide him in your lodging', P('Hide him in your lodging', 0.65, O('He stayed a season and left when the feud cooled, for his mother’s village. He sends you a jar of Jegal pickles every New Year.', { sanity: 4, rep: { families: -1 } }), O('The Namgung found him. They did not hurt him; they shamed him, which was worse.', { sanity: -4, rep: { families: -2 } }))],
    feed: ['Feed him and send him to his uncles', O('He went to the Jegal and told them everything he knew of the Namgung march. Whether that ended the feud sooner or made it bloodier, you will never know.', { insight: 1 })],
    turn: ['Return him to the Namgung', O('The Namgung thanked you coldly and took him away. He did not look at you.', { rep: { families: 3 }, sanity: -5 })],
    extra: ['Ask him to carry a message of peace', O('He carried it. Nobody listened to a deserter, but he said it in both halls, loudly, and that is not nothing.', { fame: 1, sanity: 2 })] },
  { key: 'dang', if: { happened: 'dang_civil_war', year: [26, 28], region: 'shu', age: [14, 90] }, art: 'forest',
    text: 'A young Dang poisoner has fled Dang Gwang’s faction with a satchel of his own work. He wants to sell it, burn it, or bury it, and cannot decide which. He is shaking.',
    hide: ['Hide him in Chengdu', P('Hide him in Chengdu', 0.6, O('He became an apothecary in Chengdu under a new name, and the best one in the city. He never sold a poison again, or so he says.', { sanity: 4 }), O('The Dang found him within a month. The Dang always do.', { sanity: -6 }))],
    feed: ['Help him bury the satchel', O('You buried it together under a pine on a mountain that has no name. He felt lighter. You felt you had buried something that would grow.', { sanity: 3 })],
    turn: ['Take him to the loyalists', O('The loyalists took the satchel and the poisoner. They kept the satchel.', { rep: { families: 4 }, sanity: -4 })],
    extra: ['Buy the satchel (20 taels)', O('Twenty taels, and a satchel of the Dang family’s worst ideas. You studied the antidotes and burned the rest.', { wealth: -20, insight: 2, recipe: 'healing_salve' }), { wealth: '>=20' }] },
  { key: 'greenforest', if: { happened: 'hebei_drought', year: [46, 50], region: 'hebei', age: [14, 90] }, art: 'road',
    text: 'A Green Forest bandit has come down from the Taihang to surrender, but the imperial camp is hanging bandits who surrender. He has a wife in a village a day away who thinks he is working at a mine.',
    hide: ['Walk him to his village', P('Walk him to his village', 0.7, O('A day’s walk, a door, a wife who hit him with a ladle and then hugged him. He grows sorghum now.', { sanity: 6 }), O('A patrol stopped you on the road. You got away. He did not.', { sanity: -8 }))],
    feed: ['Give him your cloak and some silver', O('Your cloak and two taels. He went to his village alone. You will never know if he got there.', { wealth: -2, sanity: 2 })],
    turn: ['Take him to the imperial camp', O('The camp paid you. The camp hanged him. You heard about it at noon.', { wealth: 5, rep: { court: 2 }, sanity: -10 })],
    extra: ['Ask Ma Hu to take him back', O('Ma Hu took him back and gave him a job guarding grain, which the Green Forest now had again. "A man who comes down the mountain once can come down it again," Ma Hu said. "Later."', { rel: { '@mountain_tiger': { res: 5 } }, rep: { unorthodox: 2 } })] },
  { key: 'depot', if: { happened: 'beggars_outlawed', year: [57, 62], region: ['central', 'hebei'], age: [14, 100] }, art: 'city',
    text: 'A Depot constable in torn black has run from his post. He was ordered to burn the Beggars’ hall under the third bridge, and saw a child in the window, and threw down his torch. The Depot is looking for him with more energy than for any beggar.',
    hide: ['Hide him with the Beggars', P('Hide him with the Beggars', 0.7, O('The Beggars took him in with a great deal of suspicion and a bowl of soup. Within a year he had three pouches and a beggar’s name.', { sanity: 5, rep: { orthodox: 3 } }), O('A Beggar who had lost a child in the fires recognised his face. The Beggars did not hand him to the Depot. They did not keep him either.', { sanity: -6 }))],
    feed: ['Give him money for the road', O('Five taels and a direction: south, and keep going. He kept going.', { wealth: -5, sanity: 3 })],
    turn: ['Turn him in for the bounty', O('The Depot paid twenty taels for him. Twenty taels was a great deal, for a man who threw down a torch.', { wealth: 20, rep: { court: 4 }, sanity: -10, infamy: 2 })],
    extra: ['Ask him to testify', O('He wrote down what the Depot had ordered, signed it with his real name, and gave it to you. After the coup it was read out in the palace, and his name was cleared, years too late.', { fame: 3, rep: { court: -2, orthodox: 4 } })] },
  { key: 'second', if: { happened: 'second_war', year: [74, 79], age: [40, 120] }, art: 'road',
    text: 'A boy has deserted from the Second War and come to your door, because someone in the village said you were in the first one and would understand. He reminds you of someone. He reminds you of yourself.',
    hide: ['Hide him in your house', P('Hide him in your house', 0.75, O('He stayed until the war ended, chopped all your wood, and left a man. He visits every spring.', { sanity: 6 }), O('The levy officer came for him. You said nothing. The officer said nothing. The boy went.', { sanity: -6 }))],
    feed: ['Tell him what you would have wanted to hear', O('"You are not a coward," you said. "You are alive. Those are different." He went back, in the end. He came back from it, too.', { sanity: 4, charm: 1 })],
    turn: ['Walk him back to his company', O('You walked him back to his company and spoke to his captain. They did not punish him. You made sure of that.', { fame: 2, sanity: 1 })],
    extra: ['Teach him how to survive it', O('Three days of everything you knew about staying alive in a war. He went back. He lived.', { fame: 1, sanity: 3 })] },
], (r) => E('wr_deserter', 'war', { if: r.if, art: r.art, title: 'A deserter', text: r.text, choices: [
  C(r.hide[0], r.hide[1]),
  C(r.feed[0], r.feed[1]),
  C(r.turn[0], r.turn[1]),
  C(r.extra[0], r.extra[1], r.extra[2] ? { req: r.extra[2] } : {}),
] }));

// Memorials, one per battle: what is left afterwards.
const tplMemorial = template('wr_memorial', [
  { key: 'hua', if: { happened: 'blood_night', year: [35, 90], loc: 'mounthua', age: [14, 100] }, art: 'grave',
    text: 'On the ruined main hall steps of Mount Hua, someone has started a memorial: a stone for each disciple who fell on the Blood Night. There are a great many stones, and a great many still without names.',
    carve: ['Carve a name you remember', O('You carved a name you remembered, slowly, with a borrowed chisel. A plum tree had seeded itself in the rubble beside it.', { sanity: 4, codex: 'timeline.blood_night' })],
    pay: ['Pay a mason to finish the names (30 taels)', { wealth: '>=30' }, O('A mason from Chang’an worked through the summer. Every stone had a name by autumn, and the survivors came up the mountain to read them.', { wealth: -30, fame: 5, rep: { orthodox: 6 } })],
    pray: ['Burn incense on the steps', O('You burned incense on the third step, where the fighting was worst. The smoke went straight up, which the old people say means the dead are listening.', { sanity: 3 })],
    leave: ['Walk past', O('You walked past the stones without reading them. You could not.', { sanity: -2 })] },
  { key: 'kongtong', if: { happened: 'kongtong_falls', year: [36, 90], loc: 'kongtong', age: [14, 100] }, art: 'grave',
    text: 'Kongtong is a wind-scoured ruin, and its memorial is a pile of fist-sized stones at the head of the dry gully behind the north gate, one stone for each fist-master. The wind has worn the oldest ones smooth.',
    carve: ['Add a stone', O('You added a stone to the pile, and stood at the head of the gully looking down it. You understood exactly how it had happened.', { sanity: 3, codex: KONGTONG_GULLY })],
    pay: ['Pay to rebuild the north gate (40 taels)', { wealth: '>=40' }, O('The new north gate faces the gully. A Kongtong survivor carved your name on the lintel, small, where only the wind would read it.', { wealth: -40, rep: { orthodox: 6 }, fame: 3 })],
    pray: ['Practise a fist form among the stones', O('You practised the Kongtong form you half-remembered among the stones until the wind dropped. It felt like being corrected by ghosts.', { body: 1, sanity: 2 })],
    leave: ['Leave before the dust rises', O('You left before the dust rose. You did not want to be on that mountain in a dust storm.')] },
  { key: 'song', if: { happened: 'siege_song', year: [37, 90], loc: 'songshan', age: [14, 100] }, art: 'temple',
    text: 'On the steps of the Scripture Pavilion, where the Abbot fell, the monks have set a plain stone with no inscription. They say the Abbot would have wanted it that way, and sweep it every morning.',
    carve: ['Sweep the stone with the monks', O('You swept it with the monks at dawn. Nobody spoke. The broom was older than you.', { sanity: 4, qi: 5 })],
    pay: ['Donate lamp oil for a year (15 taels)', { wealth: '>=15' }, O('A lamp burns at the plain stone every night now, on your oil. The monks never told anyone whose.', { wealth: -15, rep: { orthodox: 5 }, sanity: 3 })],
    pray: ['Sit in meditation where he fell', O('You sat where the Abbot fell until your legs went numb. For a moment you felt something like a hand on your head.', { insight: 2, sanity: 3 })],
    leave: ['Bow and go', O('You bowed and went. The monks bowed back.')] },
  { key: 'wudang', if: { happened: 'wudang_holds', year: [38, 90], loc: 'wudang', age: [14, 100] }, art: 'mountain',
    text: 'Wudang held, and its dead are remembered with a pine for each one, planted along the path to the Golden Summit. The young pines are already taller than the disciples who planted them.',
    carve: ['Plant a pine for someone', O('You planted a pine for someone the war took, and the Daoists added it to their list without asking whose.', { sanity: 4 })],
    pay: ['Pay for a shrine at the top of the path (25 taels)', { wealth: '>=25' }, O('A small shrine at the top, where the pines end. The Daoists use it for tea, which they say the dead would prefer.', { wealth: -25, rep: { orthodox: 5 }, fame: 2 })],
    pray: ['Walk the path slowly', O('You walked the path slowly, a pine at a time. It took the whole day. It was meant to.', { sanity: 3, qi: 5 })],
    leave: ['Walk it quickly', O('You walked it quickly. The pines did not mind.')] },
  { key: 'namgung', if: { happened: 'namgung_burns', year: [39, 90], loc: 'namgung', age: [14, 100] }, art: 'grave',
    text: 'The rebuilt Namgung gate is new white stone, and set in it is the old gate’s blackened lintel, where Namgung Jin died. The family brings incense on the anniversary, in white, and does not speak.',
    carve: ['Stand with them in white', O('You stood with the family in white, in silence. The young patriarch nodded to you as she left.', { rep: { families: 6 }, sanity: 3 })],
    pay: ['Pay for the family school to reopen (50 taels)', { wealth: '>=50' }, O('The family school reopened with thirty children and your silver. The Heavenly Emperor Sword is being taught again, badly, by children, which is how it starts.', { wealth: -50, rep: { families: 10 }, fame: 4 })],
    pray: ['Lay something on the lintel', O('You laid a flower on the black lintel. A servant removed it later, very gently, as tradition requires. You put another there the next year.', { sanity: 3 })],
    leave: ['Watch from the road', O('You watched from the road. The Namgung do not like strangers at their grief.')] },
  { key: 'ford', if: { happened: 'yellow_ford', year: [42, 100], region: 'central', age: [14, 100] }, art: 'river',
    text: 'At the Yellow River Ford, a forest of wooden markers on the bank, Alliance and Depot and Cult mixed together, because by the time anyone thought to separate them, nobody could. The river is eating the oldest ones.',
    carve: ['Re-carve the markers the river is eating', O('You spent a day re-carving markers, any markers, whoever they had been. The names were already half gone. You did your best.', { sanity: 5 })],
    pay: ['Pay for a stone embankment (60 taels)', { wealth: '>=60' }, O('A stone embankment to keep the river off the markers. It took two years. The river is patient, but so is stone.', { wealth: -60, fame: 6, rep: { orthodox: 4, cult: 2 } })],
    pray: ['Pour wine into the river', O('You poured a jar of wine into the Ford for everyone. The river took it without comment.', { sanity: 3 })],
    leave: ['Cross the Ford and keep going', O('You crossed the Ford. The water was cold and only knee-deep. It seemed impossible.', { sanity: -1 })] },
  { key: 'dang', if: { happened: 'dang_civil_war', year: [27, 90], loc: 'dangclan', age: [14, 100] }, art: 'garden',
    text: 'The Dang remember their civil war with a garden: a new bed of white chrysanthemums for each of the dead, none of them poisonous. It is the only bed in the manor anyone can safely walk through.',
    carve: ['Walk through the white garden', O('You walked through the only safe garden in the Dang manor. It was so strange to touch a flower without fear that you laughed, and a Dang gardener smiled.', { sanity: 4 })],
    pay: ['Pay for a new bed (20 taels)', { wealth: '>=20' }, O('A new bed of chrysanthemums for a servant nobody had counted. The gardener added her name to the list.', { wealth: -20, rep: { families: 5 }, sanity: 2 })],
    pray: ['Sit with the matriarch’s bed', O('You sat by Dang Ok-ran’s bed of chrysanthemums. Someone had planted one foxglove among them, very discreetly. Old habits.', { insight: 1, sanity: 2 })],
    leave: ['Touch nothing and leave', O('Even here you touched nothing. In the Dang manor, that is how you stay alive to remember.')] },
  { key: 'willow', if: { happened: 'willow_raid', year: [16, 90], loc: 'willow', age: [12, 100] }, art: 'grave',
    text: 'Where Willow Creek burned, a single willow has grown over the well, and the people who came back have hung a ribbon on it for each of the dead. There are a great many ribbons.',
    carve: ['Tie a ribbon', O('You tied a ribbon and said a name. The wind took the ribbon the way it took all the others, toward Mount Hua.', { sanity: 4 })],
    pay: ['Pay to rebuild the village shrine (20 taels)', { wealth: '>=20' }, O('A small shrine by the willow, with a roof that does not leak. The old people sit there in the evenings now.', { wealth: -20, fame: 2, sanity: 4 })],
    pray: ['Draw water from the well', O('You drew water from the well. It tasted exactly as it had when you were a child, which you had not expected.', { sanity: 3, health: 2 })],
    leave: ['Go before anyone sees you', O('You went before anyone saw you.', { sanity: -2 })] },
  { key: 'fleet', if: { happened: 'grain_fleet', year: [14, 70], loc: 'wuchang', age: [12, 100] }, art: 'river',
    text: 'On the Wuchang quay, the boatmen have set up a stone for the crews of the sunken grain fleet. Nobody from the court came to the dedication. The boatmen hold a feast on the anniversary anyway, and leave a place at the table for the river.',
    carve: ['Sit at the feast', O('You sat at the boatmen’s feast and drank to the drowned. A rower named Tak sat next to you and told you how it happened, again.', { sanity: 4, charm: 1 })],
    pay: ['Pay for the feast this year (15 taels)', { wealth: '>=15' }, O('You paid for the feast. The boatmen drank to you after the drowned, which is a great honour on the river.', { wealth: -15, rep: { merchants: 3 }, fame: 2 })],
    pray: ['Float a lantern', O('You floated a lantern on the Great River. It went downstream toward Dongting, burning.', { sanity: 3 })],
    leave: ['Leave the river to its dead', O('You left the river to its dead.')] },
  { key: 'second', if: { happened: 'second_war_end', year: [79, 120], region: ['central', 'guanzhong'], age: [14, 140] }, art: 'grave',
    text: 'A new memorial for the Second War, beside the one for the first. The masons have carved the dates. Someone has scratched underneath them: AGAIN.',
    carve: ['Scratch your name under AGAIN', O('You scratched your name under it. Not because you fought, but because you remember both.', { sanity: 3 })],
    pay: ['Pay for a school beside the memorials (50 taels)', { wealth: '>=50' }, O('A school beside the two memorials, so the children grow up between them. It seemed the only lesson worth paying for.', { wealth: -50, fame: 6, sanity: 5 })],
    pray: ['Tell the children what the first war was like', O('You told the children who play among the stones about the first war. They listened, and went back to playing. That is how it should be.', { sanity: 2, charm: 1 })],
    leave: ['Walk past both', O('You walked past both memorials. You have read them before.')] },
], (r) => E('wr_memorial', 'war', { if: r.if, art: r.art, title: 'The memorial', text: r.text, choices: [
  C(r.carve[0], r.carve[1]),
  Q(r.pay[0], r.pay[1], r.pay[2]),
  C(r.pray[0], r.pray[1]),
  C(r.leave[0], r.leave[1]),
] }));

// War orphans, one per war. Each instance binds a new child.
const tplOrphan = template('wr_orphan', [
  { key: 'hua', if: { happened: 'blood_night', year: [34, 40], region: 'guanzhong', age: [18, 100] }, child: ORPHAN([5, 8], 'f'), cost: 10, grow: 44, art: 'snow',
    text: 'A girl in a Mount Hua novice’s robe, much too big for her, is sitting by the Chang’an road holding a wooden sword. She will not say her name. She will say, if asked, that she is still a disciple.',
    adopt: 'You took her in. She practised the Plum Blossom Sword with her wooden blade every morning, wrong, until you found someone to teach it right.',
    sect: ['Take her to the survivors rebuilding Mount Hua', O('The survivors rebuilding the hall took her without a word and gave her a robe that fit. She bowed to you once, very correctly.', { rep: { orthodox: 5 }, sanity: 4 })],
    coin: ['Give her silver and directions', O('You gave her silver. She gave you a look you will remember, and walked toward the mountain alone.', { wealth: -3, sanity: -2 })],
    walk: O('You walked on. The wooden sword stayed on the road behind you, pointed at the sky.', { sanity: -6 }) },
  { key: 'kongtong', if: { happened: 'kongtong_falls', year: [35, 42], region: 'guanzhong', age: [18, 100] }, child: ORPHAN([6, 9], 'm'), cost: 10, grow: 40, art: 'mountain',
    text: 'A Kongtong boy has walked down the mountain with a fist-master’s bloodied wrappings around his hands, because his master told him to keep them. His master is not coming down.',
    adopt: 'You took him in. He kept the wrappings in a box and never took them out. When he was older, he wore them.',
    sect: ['Take him to the Kongtong survivors at Mount Zhongnan', O('The Kongtong survivors at Zhongnan recognised the wrappings and wept. They took him in as their master’s last disciple.', { rep: { orthodox: 6 }, sanity: 4 })],
    coin: ['Pay an inn to keep him for a winter', O('The innkeeper’s wife kept him for a winter and then for good. You paid for the first winter; the rest she paid herself.', { wealth: -6, sanity: 2 })],
    walk: O('You walked on. He watched you go with his wrapped fists held tight.', { sanity: -6 }) },
  { key: 'song', if: { happened: 'siege_song', year: [36, 42], region: 'central', age: [18, 100] }, child: ORPHAN([4, 7], 'm'), cost: 8, grow: 48, art: 'temple',
    text: 'A small boy from a village below Mount Song is following the monks around the ruined outer temple, imitating their bows. The monks have tried to send him away four times. He keeps bowing.',
    adopt: 'You took him in. He bowed to everything for a year: the stove, the door, you. Then he stopped, and laughed instead.',
    sect: ['Ask the monks to keep him as a lay disciple', O('The monks argued, and then the oldest one laughed and said any boy who bows that stubbornly has Shaolin bones. He shaved his own head the next day.', { rep: { orthodox: 5 }, sanity: 4 })],
    coin: ['Give the village headman silver to keep him', O('The headman promised. You hope he kept the promise.', { wealth: -5 })],
    walk: O('You walked on. He bowed to your back.', { sanity: -5 }) },
  { key: 'namgung', if: { happened: 'namgung_burns', year: [38, 44], region: 'jiangnan', age: [18, 100] }, child: ORPHAN([5, 9], 'f'), cost: 15, grow: 42, art: 'fire',
    text: 'The daughter of a Namgung sword-maid, whose mother died at the west court, is living in a Hangzhou temple and refusing every family that offers to take her. "My mother was a Namgung retainer," she says, "and so am I."',
    adopt: 'You took her in as a retainer, which was the only way she would come. She called you Master for two years, and then, one evening, something else.',
    sect: ['Take her to the surviving Namgung', O('The young Namgung patriarch took her in herself, as a retainer, with a full bow. The girl was satisfied at last.', { rep: { families: 8 }, sanity: 4 })],
    coin: ['Pay the temple for her keep', O('The temple kept her and her pride. Both grew.', { wealth: -8, sanity: 1 })],
    walk: O('You walked on. She would not have come with you anyway, you told yourself.', { sanity: -4 }) },
  { key: 'ford', if: { happened: 'yellow_ford', year: [41, 46], region: 'central', age: [18, 100] }, child: ORPHAN([6, 10], 'm'), cost: 10, grow: 38, art: 'river',
    text: 'A boy is going through the dead on the Yellow River bank, looking for one face. Each time it is not the face, he moves on to the next. He has been doing this for three days.',
    adopt: 'You took him in. He never found the face. He found, eventually, that he could stop looking.',
    sect: ['Take him to the Beggars’ Sect in Luoyang', O('The Beggars took him in and gave him a job: finding people. He was very good at it. He found a great many, for other people.', { rep: { orthodox: 4 }, sanity: 4 })],
    coin: ['Help him look, then give him silver', O('You looked together for a day. Then you gave him silver and a direction. He took both and went on looking.', { wealth: -4, sanity: -1 })],
    walk: O('You walked on. He was turning over the next one.', { sanity: -7 }) },
  { key: 'dang', if: { happened: 'dang_civil_war', year: [26, 32], region: 'shu', age: [18, 100] }, child: ORPHAN([5, 8], 'f'), cost: 12, grow: 44, art: 'garden',
    text: 'A Dang girl with no family left on either side of the civil war is living in the poison garden, because nobody will follow her in there. She knows every plant by name. She is eating very little.',
    adopt: 'You coaxed her out of the garden and took her in. She labelled every plant in your house with its toxicity, and was right every time.',
    sect: ['Take her to Dang Min', O('Dang Min took her in as his student and taught her to cure. She became, years later, a physician who could name every poison and undo most of them.', { rel: { '@dang_min': { aff: 10 } }, rep: { families: 4 }, sanity: 4 })],
    coin: ['Leave food at the garden gate', O('You left food at the gate every day for a month. It was always gone. One day there was a flower in its place, harmless.', { wealth: -4, sanity: 3 })],
    walk: O('You walked on. Nobody follows anyone into a Dang garden.', { sanity: -4 }) },
  { key: 'west', if: { flag: 'w.postwar', year: [42, 50], region: 'west', age: [18, 100] }, child: ORPHAN([5, 9], 'm'), cost: 10, grow: 42, art: 'desert',
    text: 'A Cult boy with a red armband sewn on his sleeve is begging at the Jade Gate. Alliance travellers spit at him. Cult travellers pretend not to see him. He has a very old face for his age.',
    adopt: 'You took him in and unpicked the armband with him, stitch by stitch, because he asked. He kept it in a box anyway.',
    sect: ['Take him to the Cult’s border post', O('A Cult officer at the border post knelt to the boy’s height, asked his father’s name, and went very quiet. He took him home himself.', { rep: { cult: 8 }, sanity: 4 })],
    coin: ['Buy him a meal and a coat', O('A meal and a coat. He ate the meal and sold the coat. Practical.', { wealth: -3, sanity: 1 })],
    walk: O('You walked on with the other travellers.', { sanity: -6 }) },
  { key: 'registry', if: { happened: 'registry_edict', year: [55, 62], locType: 'city', age: [18, 100] }, child: ORPHAN([6, 10], 'f'), cost: 15, grow: 38, art: 'city',
    text: 'A girl is selling her parents’ martial manuals in the market, page by page, because the Depot executed them for refusing to register and the landlord wants rent. She does not know what the pages are worth. Neither does anyone buying them.',
    adopt: 'You took her in and bought back every page you could find. She learned to read from them, and then to fight.',
    sect: ['Take her to an orthodox sect that will hide her', O('A sect took her in under a false name, and her parents’ manuals with her. She will carry their art one day, if the Depot never learns her face.', { rep: { orthodox: 6, court: -3 }, sanity: 4 })],
    coin: ['Pay her rent for a year (10 taels)', O('A year of rent, and the landlord’s word. You do not trust his word, but you trust the silver.', { wealth: -10, sanity: 2 }), { wealth: '>=10' }],
    walk: O('You bought a page, and walked on. You did not read it.', { sanity: -5, wealth: -1 }) },
  { key: 'second', if: { happened: 'second_war', year: [74, 80], age: [30, 140] }, child: ORPHAN([4, 8], 'm'), cost: 10, grow: 46, art: 'road',
    text: 'The Second War has made orphans as the first one did. One of them, a small boy, has attached himself to you specifically, and will not explain why. "You look like you know what to do," he says.',
    adopt: 'You took him in. You did, as it turned out, know what to do. You had learned it the first time.',
    sect: ['Find him a sect that is still taking children', O('You found him a sect that was still taking children, which in the Second War was not easy. He waved at you from the gate every day for a week.', { rep: { orthodox: 4 }, sanity: 4 })],
    coin: ['Pay a neighbour to keep him', O('The neighbour kept him, and kept him well. He visits you anyway, every day, to tell you what to do.', { wealth: -6, sanity: 3 })],
    walk: O('You told him you did not know what to do. It was a lie. He knew it.', { sanity: -6 }) },
], (r) => E('wr_orphan', 'war', { if: r.if, bind: { x: r.child }, art: r.art, title: 'A war orphan', text: r.text, choices: [
  Q('Take {x.him} in', { wealth: `>=${r.cost}` }, O(r.adopt, { role: { x: 'child' }, wealth: -r.cost, rel: { x: { aff: 20 } }, sanity: 6, next: { id: 'wr_orphan_grown', in: r.grow } })),
  C(r.sect[0], r.sect[1]),
  C(r.coin[0], r.coin[1], r.coin[2] ? { req: r.coin[2] } : {}),
  C('Walk on', r.walk),
] }));

export default [...events, ...tplBattle, ...tplSiege, ...tplRefugees, ...tplLevy, ...tplSupply, ...tplHospital, ...tplSpy, ...tplDeserter, ...tplMemorial, ...tplOrphan];
